-- [FUNCTION] auth.email()
CREATE OR REPLACE FUNCTION auth.email()
 RETURNS text
 LANGUAGE sql
 STABLE
AS $function$
  select 
  coalesce(
    nullif(current_setting('request.jwt.claim.email', true), ''),
    (nullif(current_setting('request.jwt.claims', true), '')::jsonb ->> 'email')
  )::text
$function$
;

-- [FUNCTION] auth.jwt()
CREATE OR REPLACE FUNCTION auth.jwt()
 RETURNS jsonb
 LANGUAGE sql
 STABLE
AS $function$
  select 
    coalesce(
        nullif(current_setting('request.jwt.claim', true), ''),
        nullif(current_setting('request.jwt.claims', true), '')
    )::jsonb
$function$
;

-- [FUNCTION] auth.role()
CREATE OR REPLACE FUNCTION auth.role()
 RETURNS text
 LANGUAGE sql
 STABLE
AS $function$
  select 
  coalesce(
    nullif(current_setting('request.jwt.claim.role', true), ''),
    (nullif(current_setting('request.jwt.claims', true), '')::jsonb ->> 'role')
  )::text
$function$
;

-- [FUNCTION] auth.uid()
CREATE OR REPLACE FUNCTION auth.uid()
 RETURNS uuid
 LANGUAGE sql
 STABLE
AS $function$
  select 
  coalesce(
    nullif(current_setting('request.jwt.claim.sub', true), ''),
    (nullif(current_setting('request.jwt.claims', true), '')::jsonb ->> 'sub')
  )::uuid
$function$
;

-- [FUNCTION] public.accept_organization_invitation(raw_token text)
CREATE OR REPLACE FUNCTION public.accept_organization_invitation(raw_token text)
 RETURNS TABLE(workspace_id uuid, workspace_name text, membership_id uuid, membership_role workspace_member_role)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE
  current_user_id UUID := auth.uid();
  current_email TEXT;
  invitation public.organization_invitations%ROWTYPE;
  selected_role public.organization_roles%ROWTYPE;
  resolved_membership public.workspace_members%ROWTYPE;
  resolved_workspace public.workspaces%ROWTYPE;
  digest_value TEXT;
  base_role public.workspace_member_role := 'member'::public.workspace_member_role;
BEGIN
  IF current_user_id IS NULL THEN
    RAISE EXCEPTION 'organization_invitation_authentication_required';
  END IF;

  IF raw_token IS NULL OR length(raw_token) < 32 THEN
    RAISE EXCEPTION 'organization_invitation_invalid';
  END IF;

  SELECT lower(btrim(email)) INTO current_email
  FROM public.user_profiles
  WHERE id = current_user_id;

  IF current_email IS NULL THEN
    RAISE EXCEPTION 'organization_invitation_profile_missing';
  END IF;

  digest_value := encode(digest(raw_token, 'sha256'), 'hex');

  SELECT * INTO invitation
  FROM public.organization_invitations
  WHERE token_hash = digest_value
  FOR UPDATE;

  IF invitation.id IS NULL OR invitation.status <> 'pending' THEN
    RAISE EXCEPTION 'organization_invitation_invalid';
  END IF;

  IF invitation.expires_at <= CURRENT_TIMESTAMP THEN
    UPDATE public.organization_invitations
    SET status = 'expired'
    WHERE id = invitation.id;
    RAISE EXCEPTION 'organization_invitation_expired';
  END IF;

  IF lower(btrim(invitation.email)) <> current_email THEN
    RAISE EXCEPTION 'organization_invitation_email_mismatch';
  END IF;

  SELECT * INTO resolved_workspace
  FROM public.workspaces
  WHERE id = invitation.workspace_id
    AND organization_enabled = TRUE
  FOR UPDATE;

  IF resolved_workspace.id IS NULL THEN
    RAISE EXCEPTION 'organization_invitation_workspace_unavailable';
  END IF;

  IF invitation.role_id IS NOT NULL THEN
    SELECT * INTO selected_role
    FROM public.organization_roles
    WHERE id = invitation.role_id
      AND workspace_id = invitation.workspace_id;

    IF selected_role.id IS NULL OR selected_role.system_key = 'owner' THEN
      RAISE EXCEPTION 'organization_invitation_role_invalid';
    END IF;

    IF selected_role.system_key = 'admin' THEN
      base_role := 'admin'::public.workspace_member_role;
    END IF;
  END IF;

  INSERT INTO public.workspace_members (
    workspace_id, user_id, role, status, invited_by, joined_at
  ) VALUES (
    invitation.workspace_id, current_user_id, base_role, 'active', invitation.invited_by, CURRENT_TIMESTAMP
  )
  ON CONFLICT (workspace_id, user_id) DO UPDATE
  SET status = 'active',
      role = CASE
        WHEN public.workspace_members.role = 'owner'::public.workspace_member_role THEN public.workspace_members.role
        ELSE EXCLUDED.role
      END,
      invited_by = COALESCE(public.workspace_members.invited_by, EXCLUDED.invited_by),
      offboarded_at = NULL,
      suspended_at = NULL
  RETURNING * INTO resolved_membership;

  IF selected_role.id IS NOT NULL THEN
    INSERT INTO public.organization_member_roles (workspace_id, member_id, role_id, assigned_by)
    VALUES (invitation.workspace_id, resolved_membership.id, selected_role.id, invitation.invited_by)
    ON CONFLICT (member_id, role_id) DO NOTHING;
  END IF;

  IF invitation.unit_id IS NOT NULL THEN
    INSERT INTO public.organization_unit_members (unit_id, member_id)
    SELECT invitation.unit_id, resolved_membership.id
    WHERE EXISTS (
      SELECT 1 FROM public.organization_units unit
      WHERE unit.id = invitation.unit_id
        AND unit.workspace_id = invitation.workspace_id
        AND unit.status = 'active'
    )
    ON CONFLICT (unit_id, member_id) DO NOTHING;
  END IF;

  UPDATE public.organization_invitations
  SET status = 'accepted',
      accepted_at = CURRENT_TIMESTAMP,
      accepted_by = current_user_id,
      token_hash = NULL
  WHERE id = invitation.id;

  UPDATE public.organization_invitations
  SET status = 'revoked',
      revoked_at = CURRENT_TIMESTAMP,
      revoked_by = current_user_id,
      token_hash = NULL
  WHERE workspace_id = invitation.workspace_id
    AND lower(btrim(email)) = current_email
    AND status = 'pending'
    AND id <> invitation.id;

  INSERT INTO public.organization_audit_events (
    workspace_id, actor_user_id, event_type, resource_type, resource_id,
    summary, payload, outcome, severity, module, origin
  ) VALUES (
    invitation.workspace_id, current_user_id, 'member.invitation.accepted',
    'organization_invitation', invitation.id::TEXT,
    'Invitacion de organizacion aceptada',
    jsonb_build_object('membership_id', resolved_membership.id, 'email', current_email),
    'success', 'medium', 'members', 'public_link'
  );

  INSERT INTO public.notifications (user_id, type, title, description, priority, metadata)
  SELECT invitation.invited_by, 'organization', 'Invitacion aceptada',
         current_email || ' se unio a ' || resolved_workspace.name,
         'media', jsonb_build_object('workspace_id', invitation.workspace_id, 'member_id', resolved_membership.id)
  WHERE invitation.invited_by IS NOT NULL;

  RETURN QUERY SELECT resolved_workspace.id, resolved_workspace.name, resolved_membership.id, resolved_membership.role;
END;
$function$
;

-- [FUNCTION] public.activate_collaboration_trial(ws_id uuid, requested_product_key text, request_key uuid)
CREATE OR REPLACE FUNCTION public.activate_collaboration_trial(ws_id uuid, requested_product_key text, request_key uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE
  v_product public.addon_products%ROWTYPE;
  v_subscription public.organization_addon_subscriptions%ROWTYPE;
  v_workspace public.workspaces%ROWTYPE;
  v_entitlement TEXT;
  v_trial_end TIMESTAMPTZ;
BEGIN
  IF NOT public.has_organization_permission(ws_id, 'subscription.manage_addons') THEN
    RAISE EXCEPTION 'permission_denied' USING ERRCODE = '42501';
  END IF;
  SELECT * INTO v_workspace FROM public.workspaces WHERE id = ws_id FOR UPDATE;
  IF v_workspace.id IS NULL OR v_workspace.workspace_type <> 'business' OR NOT COALESCE(v_workspace.organization_enabled, TRUE) THEN
    RAISE EXCEPTION 'organization_not_eligible' USING ERRCODE = '42501';
  END IF;
  SELECT * INTO v_product FROM public.addon_products
    WHERE product_key = requested_product_key AND status = 'available';
  IF v_product.id IS NULL THEN RAISE EXCEPTION 'addon_not_available'; END IF;

  SELECT oas.* INTO v_subscription
  FROM public.organization_addon_subscriptions oas
  WHERE workspace_id = ws_id AND product_id = v_product.id;
  IF v_subscription.id IS NOT NULL AND v_subscription.status IN ('trialing','active','past_due') THEN
    RETURN jsonb_build_object('success', TRUE, 'idempotent', TRUE, 'subscription_id', v_subscription.id, 'status', v_subscription.status);
  END IF;
  IF v_subscription.id IS NOT NULL AND v_subscription.trial_started_at IS NOT NULL THEN
    RAISE EXCEPTION 'trial_already_used' USING ERRCODE = '23514';
  END IF;

  v_trial_end := CURRENT_TIMESTAMP + make_interval(days => v_product.trial_days);
  INSERT INTO public.organization_addon_subscriptions(
    workspace_id, product_id, status, trial_started_at, trial_ends_at,
    current_period_start, current_period_end, idempotency_key, created_by
  ) VALUES (
    ws_id, v_product.id, 'trialing', CURRENT_TIMESTAMP, v_trial_end,
    CURRENT_TIMESTAMP, v_trial_end, request_key, auth.uid()
  )
  ON CONFLICT (workspace_id, product_id) DO UPDATE SET
    status = 'trialing', trial_started_at = CURRENT_TIMESTAMP, trial_ends_at = v_trial_end,
    current_period_start = CURRENT_TIMESTAMP, current_period_end = v_trial_end,
    idempotency_key = request_key, updated_at = CURRENT_TIMESTAMP
  RETURNING * INTO v_subscription;

  FOREACH v_entitlement IN ARRAY v_product.entitlement_keys LOOP
    INSERT INTO public.organization_entitlements(
      workspace_id, entitlement_key, status, source, addon_subscription_id,
      limits, starts_at, ends_at
    ) VALUES (
      ws_id, v_entitlement, 'trialing', 'trial', v_subscription.id,
      v_product.default_limits, CURRENT_TIMESTAMP, v_trial_end
    )
    ON CONFLICT (workspace_id, entitlement_key) DO UPDATE SET
      status = 'trialing', source = 'trial', addon_subscription_id = v_subscription.id,
      limits = EXCLUDED.limits, starts_at = CURRENT_TIMESTAMP, ends_at = v_trial_end,
      read_only_at = NULL, updated_at = CURRENT_TIMESTAMP;
  END LOOP;

  INSERT INTO public.collaboration_settings(workspace_id, created_by)
  VALUES (ws_id, auth.uid()) ON CONFLICT (workspace_id) DO NOTHING;

  INSERT INTO public.organization_audit_events(
    workspace_id, actor_user_id, event_type, resource_type, resource_id,
    summary, payload, outcome, severity, module
  ) VALUES (
    ws_id, auth.uid(), 'collaboration.trial.started', 'organization_addon_subscription', v_subscription.id::TEXT,
    'Prueba de Docubox Colabora iniciada',
    jsonb_build_object('product_key', requested_product_key, 'trial_ends_at', v_trial_end),
    'success', 'high', 'colabora'
  );

  RETURN jsonb_build_object('success', TRUE, 'idempotent', FALSE, 'subscription_id', v_subscription.id, 'status', 'trialing', 'trial_ends_at', v_trial_end);
END;
$function$
;

-- [FUNCTION] public.append_legal_evidence_event(p_document_id uuid, p_event_type text, p_event_category text, p_event_result text, p_actor_id uuid, p_actor_type text, p_payload jsonb, p_document_sha256 text, p_actor_email text, p_correlation_id uuid, p_idempotency_key text, p_source_system text, p_source_record_id uuid, p_occurred_at timestamp with time zone)
CREATE OR REPLACE FUNCTION public.append_legal_evidence_event(p_document_id uuid, p_event_type text, p_event_category text, p_event_result text, p_actor_id uuid, p_actor_type text, p_payload jsonb, p_document_sha256 text DEFAULT NULL::text, p_actor_email text DEFAULT NULL::text, p_correlation_id uuid DEFAULT NULL::uuid, p_idempotency_key text DEFAULT NULL::text, p_source_system text DEFAULT 'DOCUBOX'::text, p_source_record_id uuid DEFAULT NULL::uuid, p_occurred_at timestamp with time zone DEFAULT NULL::timestamp with time zone)
 RETURNS legal_evidence_events
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
  v_document public.documentos%ROWTYPE;
  v_existing public.legal_evidence_events%ROWTYPE;
  v_row public.legal_evidence_events%ROWTYPE;
  v_sequence integer;
  v_previous_hash text;
  v_payload jsonb := COALESCE(p_payload, '{}'::jsonb);
  v_payload_text text;
  v_payload_hash text;
  v_event_uuid uuid := gen_random_uuid();
  v_occurred_at timestamptz := COALESCE(p_occurred_at, now());
  v_chain_material text;
BEGIN
  IF auth.role() <> 'service_role' THEN
    RAISE EXCEPTION 'LEGAL_EVIDENCE_SERVICE_ROLE_REQUIRED';
  END IF;
  IF p_event_type !~ '^[A-Z0-9_]{3,80}$' THEN
    RAISE EXCEPTION 'LEGAL_EVIDENCE_EVENT_TYPE_INVALID';
  END IF;
  IF p_document_sha256 IS NOT NULL AND lower(p_document_sha256) !~ '^[a-f0-9]{64}$' THEN
    RAISE EXCEPTION 'LEGAL_EVIDENCE_DOCUMENT_HASH_INVALID';
  END IF;

  SELECT * INTO v_document FROM public.documentos WHERE id = p_document_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'LEGAL_EVIDENCE_DOCUMENT_NOT_FOUND'; END IF;

  PERFORM pg_advisory_xact_lock(hashtextextended(p_document_id::text, 0));

  IF p_idempotency_key IS NOT NULL THEN
    SELECT * INTO v_existing
    FROM public.legal_evidence_events
    WHERE document_id = p_document_id AND idempotency_key = p_idempotency_key;
    IF FOUND THEN RETURN v_existing; END IF;
  END IF;

  SELECT COALESCE(MAX(sequence_number), 0) + 1,
         (ARRAY_AGG(event_hash ORDER BY sequence_number DESC))[1]
    INTO v_sequence, v_previous_hash
  FROM public.legal_evidence_events
  WHERE document_id = p_document_id;

  v_payload_text := v_payload::text;
  v_payload_hash := encode(extensions.digest(convert_to(v_payload_text, 'UTF8'), 'sha256'::text), 'hex');
  v_chain_material := concat_ws('|',
    'DOCUBOX_LEGAL_EVIDENCE', '1.0', v_event_uuid::text, p_document_id::text,
    v_sequence::text, p_event_type, p_event_category, p_event_result,
    COALESCE(p_actor_id::text, ''), p_actor_type,
    to_char(v_occurred_at AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.US"Z"'),
    COALESCE(lower(p_document_sha256), ''), v_payload_hash,
    COALESCE(v_previous_hash, repeat('0', 64))
  );

  INSERT INTO public.legal_evidence_events (
    event_uuid, tenant_id, workspace_id, document_id, sequence_number,
    event_type, event_category, event_result, actor_id, actor_type,
    actor_email_hash, correlation_id, idempotency_key, source_system,
    source_record_id, document_sha256, payload, payload_canonical_text,
    payload_sha256, previous_event_hash, chain_material, event_hash, occurred_at
  ) VALUES (
    v_event_uuid, COALESCE(v_document.workspace_id, v_document.owner_id),
    v_document.workspace_id, p_document_id, v_sequence, p_event_type,
    p_event_category, p_event_result, p_actor_id, p_actor_type,
    CASE WHEN p_actor_email IS NULL THEN NULL ELSE encode(extensions.digest(lower(trim(p_actor_email)), 'sha256'::text), 'hex') END,
    COALESCE(p_correlation_id, gen_random_uuid()), p_idempotency_key,
    COALESCE(NULLIF(p_source_system, ''), 'DOCUBOX'), p_source_record_id,
    lower(p_document_sha256), v_payload, v_payload_text, v_payload_hash,
    v_previous_hash, v_chain_material,
    encode(extensions.digest(convert_to(v_chain_material, 'UTF8'), 'sha256'::text), 'hex'), v_occurred_at
  ) RETURNING * INTO v_row;

  RETURN v_row;
END;
$function$
;

