-- [FUNCTION] public.assign_business_member_system_role()
CREATE OR REPLACE FUNCTION public.assign_business_member_system_role()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE
  system_role_id UUID;
BEGIN
  SELECT r.id INTO system_role_id
  FROM public.organization_roles r
  JOIN public.workspaces w ON w.id = r.workspace_id
  WHERE r.workspace_id = NEW.workspace_id
    AND w.workspace_type = 'business'::public.workspace_type
    AND r.system_key = NEW.role::text
  LIMIT 1;

  IF system_role_id IS NOT NULL THEN
    INSERT INTO public.organization_member_roles (workspace_id, member_id, role_id, assigned_by)
    VALUES (NEW.workspace_id, NEW.id, system_role_id, COALESCE(NEW.invited_by, NEW.user_id))
    ON CONFLICT DO NOTHING;
  END IF;

  RETURN NEW;
END;
$function$
;

-- [FUNCTION] public.auto_set_participant_user_ids()
CREATE OR REPLACE FUNCTION public.auto_set_participant_user_ids()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE
  v_updated_parts JSONB;
  v_part JSONB;
  v_user_id UUID;
BEGIN
  IF NEW.participantes IS NULL OR jsonb_array_length(COALESCE(NEW.participantes, '[]'::jsonb)) = 0 THEN
    RETURN NEW;
  END IF;

  v_updated_parts := '[]'::jsonb;

  FOR v_part IN SELECT * FROM jsonb_array_elements(NEW.participantes)
  LOOP
    IF (v_part->>'email') IS NOT NULL AND (v_part->>'email') != '' THEN
      SELECT au.id INTO v_user_id
      FROM auth.users au
      WHERE lower(au.email) = lower(v_part->>'email')
      LIMIT 1;

      IF v_user_id IS NOT NULL THEN
        v_part := jsonb_set(v_part, '{user_id}', to_jsonb(v_user_id::text));
      END IF;
    END IF;

    -- Ensure sub_estado has a default value if missing
    IF (v_part->>'sub_estado') IS NULL OR (v_part->>'sub_estado') = '' THEN
      v_part := jsonb_set(v_part, '{sub_estado}', '"sin_revisar"'::jsonb);
    END IF;

    v_updated_parts := v_updated_parts || jsonb_build_array(v_part);
  END LOOP;

  NEW.participantes := v_updated_parts;
  RETURN NEW;
END;
$function$
;

-- [FUNCTION] public.backfill_participant_user_ids_v3()
CREATE OR REPLACE FUNCTION public.backfill_participant_user_ids_v3()
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE
  v_doc RECORD;
  v_updated_parts JSONB;
  v_part JSONB;
  v_user_id UUID;
  v_count INTEGER := 0;
BEGIN
  FOR v_doc IN
    SELECT id, participantes
    FROM public.documentos
    WHERE participantes IS NOT NULL
      AND jsonb_array_length(COALESCE(participantes, '[]'::jsonb)) > 0
      AND deleted_at IS NULL
  LOOP
    v_updated_parts := '[]'::jsonb;

    FOR v_part IN SELECT * FROM jsonb_array_elements(v_doc.participantes)
    LOOP
      -- Lookup user_id by email (always re-lookup to fix any stale/wrong user_id)
      IF (v_part->>'email') IS NOT NULL AND (v_part->>'email') != '' THEN
        SELECT au.id INTO v_user_id
        FROM auth.users au
        WHERE lower(au.email) = lower(v_part->>'email')
        LIMIT 1;

        IF v_user_id IS NOT NULL THEN
          -- Always set/overwrite user_id to ensure it is correct
          v_part := jsonb_set(v_part, '{user_id}', to_jsonb(v_user_id::text));
          v_count := v_count + 1;
        END IF;
      END IF;

      -- Ensure sub_estado has a default value if missing
      IF (v_part->>'sub_estado') IS NULL OR (v_part->>'sub_estado') = '' THEN
        v_part := jsonb_set(v_part, '{sub_estado}', '"sin_revisar"'::jsonb);
      END IF;

      v_updated_parts := v_updated_parts || jsonb_build_array(v_part);
    END LOOP;

    UPDATE public.documentos
    SET participantes = v_updated_parts,
        updated_at = NOW()
    WHERE id = v_doc.id;
  END LOOP;

  RETURN v_count;
END;
$function$
;

-- [FUNCTION] public.backfill_participantes_user_ids()
CREATE OR REPLACE FUNCTION public.backfill_participantes_user_ids()
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE
  v_doc RECORD;
  v_updated_parts JSONB;
  v_part JSONB;
  v_user_id UUID;
  v_count INTEGER := 0;
BEGIN
  FOR v_doc IN
    SELECT id, participantes
    FROM public.documentos
    WHERE participantes IS NOT NULL
      AND jsonb_array_length(COALESCE(participantes, '[]'::jsonb)) > 0
  LOOP
    v_updated_parts := '[]'::jsonb;
    
    FOR v_part IN SELECT * FROM jsonb_array_elements(v_doc.participantes)
    LOOP
      -- Only update if user_id is missing and email is present
      IF (v_part->>'user_id') IS NULL AND (v_part->>'email') IS NOT NULL THEN
        -- Look up the user by email
        SELECT au.id INTO v_user_id
        FROM auth.users au
        WHERE lower(au.email) = lower(v_part->>'email')
        LIMIT 1;
        
        IF v_user_id IS NOT NULL THEN
          v_part := jsonb_set(v_part, '{user_id}', to_jsonb(v_user_id::text));
          v_count := v_count + 1;
        END IF;
      END IF;
      
      v_updated_parts := v_updated_parts || jsonb_build_array(v_part);
    END LOOP;
    
    -- Only update if we made changes
    IF v_updated_parts != v_doc.participantes THEN
      UPDATE public.documentos
      SET participantes = v_updated_parts
      WHERE id = v_doc.id;
    END IF;
  END LOOP;
  
  RETURN v_count;
END;
$function$
;

