-- [FUNCTION] public.calc_enrollment_session_duration()
CREATE OR REPLACE FUNCTION public.calc_enrollment_session_duration()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
    -- Calcular duración cuando se establece fecha_fin
    IF NEW.fecha_fin IS NOT NULL AND OLD.fecha_fin IS NULL THEN
        NEW.duracion_segundos := EXTRACT(EPOCH FROM (NEW.fecha_fin - NEW.fecha_inicio))::INTEGER;
    END IF;
    RETURN NEW;
END;
$function$
;

-- [FUNCTION] public.can_access_documento(p_document_id uuid)
CREATE OR REPLACE FUNCTION public.can_access_documento(p_document_id uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
  SELECT EXISTS (
    SELECT 1
    FROM public.documentos d
    WHERE d.id = p_document_id
      AND (
        d.owner_id = auth.uid()
        OR EXISTS (
          SELECT 1
          FROM public.workspace_members wm
          WHERE wm.workspace_id = d.workspace_id
            AND wm.user_id = auth.uid()
        )
        OR EXISTS (
          SELECT 1
          FROM public.participation_responses pr
          WHERE pr.documento_id = d.id
            AND (
              pr.participante_id = auth.uid()
              OR lower(pr.participante_email) = lower(COALESCE(auth.jwt() ->> 'email', ''))
            )
        )
      )
  );
$function$
;

-- [FUNCTION] public.can_read_document_storage(object_name text)
CREATE OR REPLACE FUNCTION public.can_read_document_storage(object_name text)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE
  v_document_id TEXT;
  v_user_id UUID;
  v_user_email TEXT;
BEGIN
  v_user_id := auth.uid();
  IF v_user_id IS NULL THEN
    RETURN FALSE;
  END IF;

  v_user_email := public.current_user_email();

  -- El path es: {workspace_id}/{document_uuid}/{filename}
  -- Extraemos el segundo segmento como document UUID
  v_document_id := split_part(object_name, '/', 2);

  IF v_document_id IS NULL OR v_document_id = '' THEN
    RETURN FALSE;
  END IF;

  -- Verificar si el usuario es propietario O participante
  RETURN EXISTS (
    SELECT 1
    FROM public.documentos d
    WHERE (
      -- Comparar con UUID (d.id) - formato principal del path
      d.id::TEXT = v_document_id
      OR
      -- Comparar con documento_id textual como fallback
      d.documento_id = v_document_id
    )
    AND (
      -- Es el propietario
      d.owner_id = v_user_id
      OR
      -- Es participante por email
      (v_user_email IS NOT NULL AND EXISTS (
        SELECT 1
        FROM jsonb_array_elements(COALESCE(d.participantes, '[]'::jsonb)) AS p
        WHERE p->>'email' = v_user_email
      ))
      OR
      -- Es participante por UUID
      EXISTS (
        SELECT 1
        FROM jsonb_array_elements(COALESCE(d.participantes, '[]'::jsonb)) AS p
        WHERE (p->>'id')::uuid = v_user_id
      )
    )
  );
END;
$function$
;

-- [FUNCTION] public.can_read_documento(p_documento_id uuid)
CREATE OR REPLACE FUNCTION public.can_read_documento(p_documento_id uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE
  v_user_id UUID;
  v_user_email TEXT;
BEGIN
  v_user_id := auth.uid();
  IF v_user_id IS NULL THEN
    RETURN FALSE;
  END IF;

  v_user_email := public.current_user_email();

  RETURN EXISTS (
    SELECT 1
    FROM public.documentos d
    WHERE d.id = p_documento_id
      AND (
        -- Es el propietario
        d.owner_id = v_user_id
        OR
        -- Es participante por email
        (v_user_email IS NOT NULL AND EXISTS (
          SELECT 1
          FROM jsonb_array_elements(COALESCE(d.participantes, '[]'::jsonb)) AS p
          WHERE p->>'email' = v_user_email
        ))
        OR
        -- Es participante por UUID
        EXISTS (
          SELECT 1
          FROM jsonb_array_elements(COALESCE(d.participantes, '[]'::jsonb)) AS p
          WHERE (p->>'id')::uuid = v_user_id
        )
      )
  );
END;
$function$
;

-- [FUNCTION] public.cancel_organization_member_offboarding_job(target_job_id uuid)
CREATE OR REPLACE FUNCTION public.cancel_organization_member_offboarding_job(target_job_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE
  job public.organization_member_offboarding_jobs%ROWTYPE;
BEGIN
  SELECT * INTO job FROM public.organization_member_offboarding_jobs WHERE id = target_job_id FOR UPDATE;
  IF job.id IS NULL THEN RAISE EXCEPTION 'organization_offboarding_job_not_found' USING ERRCODE = 'P0002'; END IF;
  IF NOT public.has_organization_permission(job.workspace_id, 'members.offboard') THEN
    RAISE EXCEPTION 'organization_permission_denied' USING ERRCODE = '42501';
  END IF;
  IF job.status NOT IN ('pending', 'scheduled') THEN
    RAISE EXCEPTION 'organization_offboarding_job_not_cancellable' USING ERRCODE = '23514';
  END IF;
  UPDATE public.organization_member_offboarding_jobs
  SET status = 'cancelled', cancelled_at = CURRENT_TIMESTAMP
  WHERE id = job.id;
  INSERT INTO public.organization_audit_events (
    workspace_id, actor_user_id, event_type, resource_type, resource_id, summary, severity, module
  ) VALUES (
    job.workspace_id, auth.uid(), 'member.offboarding.cancelled', 'organization_member_offboarding_job', job.id::TEXT,
    'Baja organizacional cancelada', 'high', 'continuity'
  );
END;
$function$
;

-- [FUNCTION] public.cancel_organization_ownership_transfer(target_transfer_id uuid)
CREATE OR REPLACE FUNCTION public.cancel_organization_ownership_transfer(target_transfer_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE
  transfer public.organization_ownership_transfers%ROWTYPE;
BEGIN
  SELECT * INTO transfer FROM public.organization_ownership_transfers WHERE id = target_transfer_id FOR UPDATE;
  IF transfer.id IS NULL THEN RAISE EXCEPTION 'organization_ownership_transfer_not_found' USING ERRCODE = 'P0002'; END IF;
  IF NOT public.has_organization_permission(transfer.workspace_id, 'organization.transfer_ownership') THEN
    RAISE EXCEPTION 'organization_permission_denied' USING ERRCODE = '42501';
  END IF;
  IF transfer.status <> 'pending' THEN
    RAISE EXCEPTION 'organization_ownership_transfer_not_cancellable' USING ERRCODE = '23514';
  END IF;
  UPDATE public.organization_ownership_transfers
  SET status = 'cancelled', cancelled_at = CURRENT_TIMESTAMP
  WHERE id = transfer.id;
  INSERT INTO public.organization_audit_events (
    workspace_id, actor_user_id, event_type, resource_type, resource_id, summary, severity, module
  ) VALUES (
    transfer.workspace_id, auth.uid(), 'organization.ownership_transfer.cancelled',
    'organization_ownership_transfer', transfer.id::TEXT, 'Transferencia de propiedad cancelada',
    'critical', 'continuity'
  );
END;
$function$
;

-- [FUNCTION] public.certification_touch_updated_at()
