END;
$function$
;

-- [FUNCTION] public.chain_organization_audit_event()
CREATE OR REPLACE FUNCTION public.chain_organization_audit_event()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
DECLARE
  prior_sequence BIGINT;
  prior_hash TEXT;
  material TEXT;
BEGIN
  PERFORM pg_advisory_xact_lock(hashtextextended(NEW.workspace_id::TEXT, 0));
  IF auth.uid() IS NOT NULL THEN
    NEW.actor_user_id := auth.uid();
  END IF;
  SELECT sequence_number, event_hash INTO prior_sequence, prior_hash
  FROM public.organization_audit_events
  WHERE workspace_id = NEW.workspace_id
  ORDER BY sequence_number DESC NULLS LAST, occurred_at DESC, id DESC
  LIMIT 1;
  NEW.sequence_number := COALESCE(prior_sequence, 0) + 1;
  NEW.previous_event_hash := prior_hash;
  NEW.chain_version := 1;
  material := concat_ws('|',
    NEW.workspace_id::TEXT,
    NEW.sequence_number::TEXT,
    COALESCE(prior_hash, 'GENESIS'),
    NEW.occurred_at::TEXT,
    COALESCE(NEW.actor_user_id::TEXT, ''),
    NEW.event_type,
    NEW.resource_type,
    COALESCE(NEW.resource_id, ''),
    NEW.summary,
    NEW.payload::TEXT,
    NEW.outcome,
    NEW.severity,
    COALESCE(NEW.module, ''),
    NEW.origin,
    NEW.correlation_id::TEXT,
    COALESCE(NEW.ip_address::TEXT, ''),
    COALESCE(NEW.user_agent, ''),
    COALESCE(NEW.before_payload::TEXT, ''),
    COALESCE(NEW.after_payload::TEXT, ''),
    NEW.evidence_refs::TEXT
  );
  NEW.event_hash := encode(digest(material, 'sha256'), 'hex');
  RETURN NEW;
END;
$function$
;

-- [FUNCTION] public.check_auth_lockout(p_identifier text)
CREATE OR REPLACE FUNCTION public.check_auth_lockout(p_identifier text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE
  v_record public.auth_lockouts%ROWTYPE;
  v_seconds_remaining INTEGER;
BEGIN
  SELECT * INTO v_record
  FROM public.auth_lockouts
  WHERE identifier = p_identifier
    AND locked_until > NOW()
    AND unlocked_at IS NULL
  LIMIT 1;

  IF FOUND THEN
    v_seconds_remaining := EXTRACT(EPOCH FROM (v_record.locked_until - NOW()))::INTEGER;
    RETURN jsonb_build_object(
      'locked', true,
      'locked_until', v_record.locked_until,
      'lockout_level', v_record.lockout_level,
      'failed_attempts', v_record.failed_attempts,
      'seconds_remaining', v_seconds_remaining
    );
  END IF;

  RETURN jsonb_build_object('locked', false);
END;
$function$
;

-- [FUNCTION] public.check_ip_blocklist(p_ip inet)
CREATE OR REPLACE FUNCTION public.check_ip_blocklist(p_ip inet)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE
  v_record public.ip_blocklist%ROWTYPE;
BEGIN
  SELECT * INTO v_record
  FROM public.ip_blocklist
  WHERE ip_address = p_ip
    AND (permanent = true OR blocked_until > NOW())
  LIMIT 1;

  IF FOUND THEN
    RETURN jsonb_build_object(
      'blocked', true,
      'reason', v_record.reason,
      'blocked_until', v_record.blocked_until,
      'permanent', v_record.permanent
    );
  END IF;

  RETURN jsonb_build_object('blocked', false);
END;
$function$
;

-- [FUNCTION] public.check_rate_limit(p_ip inet, p_endpoint text, p_max_requests integer, p_window_seconds integer)
CREATE OR REPLACE FUNCTION public.check_rate_limit(p_ip inet, p_endpoint text, p_max_requests integer, p_window_seconds integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE
  v_record public.rate_limits%ROWTYPE;
  v_blocked_until TIMESTAMPTZ;
  v_retry_after INTEGER;
BEGIN
  SELECT * INTO v_record
  FROM public.rate_limits
  WHERE ip_address = p_ip
    AND endpoint = p_endpoint
    AND window_start > NOW() - (p_window_seconds || ' seconds')::INTERVAL
  ORDER BY window_start DESC
  LIMIT 1;

  IF NOT FOUND THEN
    INSERT INTO public.rate_limits (ip_address, endpoint, window_start, request_count)
    VALUES (p_ip, p_endpoint, NOW(), 1)
    ON CONFLICT DO NOTHING;
    RETURN jsonb_build_object(
      'allowed', true,
      'remaining', p_max_requests - 1,
      'retry_after', NULL
    );
  END IF;

  IF v_record.request_count >= p_max_requests THEN
    v_blocked_until := v_record.window_start + (p_window_seconds || ' seconds')::INTERVAL;
    UPDATE public.rate_limits
    SET blocked_until = v_blocked_until
    WHERE id = v_record.id;
    v_retry_after := EXTRACT(EPOCH FROM (v_blocked_until - NOW()))::INTEGER;
    RETURN jsonb_build_object(
      'allowed', false,
      'remaining', 0,
      'retry_after', v_retry_after
    );
  END IF;

  UPDATE public.rate_limits
  SET request_count = request_count + 1
  WHERE id = v_record.id;

  RETURN jsonb_build_object(
    'allowed', true,
    'remaining', p_max_requests - (v_record.request_count + 1),
    'retry_after', NULL
  );
END;
$function$
;

-- [FUNCTION] public.check_rate_limit(p_limit_key text, p_endpoint text, p_max_requests integer, p_window_seconds integer, p_dimension text)
CREATE OR REPLACE FUNCTION public.check_rate_limit(p_limit_key text, p_endpoint text, p_max_requests integer, p_window_seconds integer DEFAULT 60, p_dimension text DEFAULT 'ip'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE
  v_window_start  TIMESTAMPTZ;
  v_count         INT;
  v_blocked       BOOLEAN;
  v_blocked_until TIMESTAMPTZ;
BEGIN
  -- Calcular inicio de la ventana actual (truncar al intervalo)
  v_window_start := date_trunc('minute', now());

  -- Upsert atómico del contador
  INSERT INTO public.rate_limit_counters (
    limit_key, endpoint, dimension, window_start, window_seconds,
    request_count, max_requests, last_request_at, first_request_at
  )
  VALUES (
    p_limit_key, p_endpoint, p_dimension, v_window_start, p_window_seconds,
    1, p_max_requests, now(), now()
  )
  ON CONFLICT (limit_key, endpoint, window_start)
  DO UPDATE SET
    request_count = rate_limit_counters.request_count + 1,
    last_request_at = now()
  RETURNING request_count, is_blocked, blocked_until
  INTO v_count, v_blocked, v_blocked_until;

  -- Verificar si está bloqueado
  IF v_blocked AND v_blocked_until > now() THEN
    RETURN jsonb_build_object(
      'allowed', false,
      'reason', 'blocked',
      'blocked_until', v_blocked_until,
      'request_count', v_count
    );
  END IF;

  -- Verificar si excede el límite
  IF v_count > p_max_requests THEN
    -- Bloquear por 5 minutos si excede el doble del límite
    IF v_count > p_max_requests * 2 THEN
      UPDATE public.rate_limit_counters
      SET is_blocked = TRUE,
          blocked_until = now() + INTERVAL '5 minutes'
      WHERE limit_key = p_limit_key
        AND endpoint = p_endpoint
        AND window_start = v_window_start;
    END IF;

    RETURN jsonb_build_object(
      'allowed', false,
      'reason', 'rate_limit_exceeded',
      'request_count', v_count,
      'max_requests', p_max_requests,
      'window_seconds', p_window_seconds
    );
  END IF;

  RETURN jsonb_build_object(
    'allowed', true,
    'request_count', v_count,
    'max_requests', p_max_requests,
    'remaining', p_max_requests - v_count
  );
END;
$function$
;

-- [FUNCTION] public.cleanup_rate_limit_counters()
CREATE OR REPLACE FUNCTION public.cleanup_rate_limit_counters()
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE
  v_count INT;
BEGIN
  DELETE FROM public.rate_limit_counters
  WHERE window_start < now() - INTERVAL '2 hours'
    AND is_blocked = FALSE;

  GET DIAGNOSTICS v_count = ROW_COUNT;
  RETURN v_count;
END;
$function$
;

-- [FUNCTION] public.complete_identity_enrollment(p_token text, p_result jsonb)
CREATE OR REPLACE FUNCTION public.complete_identity_enrollment(p_token text, p_result jsonb)
 RETURNS TABLE(enrollment_result_id uuid)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE
  v_token public.enrollment_tokens%ROWTYPE;
  v_result_id uuid;
  v_completed_at timestamptz := now();
BEGIN
  IF auth.role() <> 'service_role' THEN
    RAISE EXCEPTION 'IDENTITY_ENROLLMENT_SERVICE_ROLE_REQUIRED';
  END IF;

  SELECT * INTO v_token
  FROM public.enrollment_tokens
  WHERE token = p_token
  FOR UPDATE;

  IF NOT FOUND THEN RAISE EXCEPTION 'IDENTITY_ENROLLMENT_NOT_FOUND'; END IF;
  IF v_token.expires_at <= now() THEN RAISE EXCEPTION 'IDENTITY_ENROLLMENT_EXPIRED'; END IF;
  IF v_token.status = 'completed' THEN RAISE EXCEPTION 'IDENTITY_ENROLLMENT_ALREADY_COMPLETED'; END IF;
  IF v_token.processing_status <> 'validated' THEN RAISE EXCEPTION 'IDENTITY_ENROLLMENT_NOT_VALIDATED'; END IF;

  INSERT INTO public.enrollment_results (
    enrollment_token_id, user_id, token, session_id, nombre,
    apellido_paterno, apellido_materno, curp, rfc, fecha_nacimiento,
    sexo, tipo_identificacion, face_encoding_encrypted, encryption_iv,
    encryption_version, face_match_score, face_match_passed,
    document_metadata, status, notified_at, raw_response
  ) VALUES (
    v_token.id, v_token.user_id, v_token.token, v_token.session_id,
    NULLIF(p_result ->> 'nombre', ''),
    NULLIF(p_result ->> 'apellido_paterno', ''),
    NULLIF(p_result ->> 'apellido_materno', ''),
    NULLIF(p_result ->> 'curp', ''),
    NULLIF(p_result ->> 'rfc', ''),
    NULLIF(p_result ->> 'fecha_nacimiento', ''),
    NULLIF(p_result ->> 'sexo', ''),
    NULLIF(p_result ->> 'tipo_identificacion', ''),
    v_token.face_encoding_encrypted, NULL,
    COALESCE(v_token.encryption_version, 'AES-256-GCM-V1'),
    v_token.face_match_score, true,
    COALESCE(p_result -> 'document_metadata', '{}'::jsonb),
    'completed', v_completed_at,
    COALESCE(p_result -> 'provider_reference', '{}'::jsonb)
  )
  RETURNING id INTO v_result_id;

  UPDATE public.enrollment_tokens SET
    status = 'completed', completed_at = v_completed_at,
    nombre = NULLIF(p_result ->> 'nombre', ''),
    apellido_paterno = NULLIF(p_result ->> 'apellido_paterno', ''),
    apellido_materno = NULLIF(p_result ->> 'apellido_materno', ''),
    curp = NULLIF(p_result ->> 'curp', ''),
    rfc = NULLIF(p_result ->> 'rfc', ''),
    fecha_nacimiento = NULLIF(p_result ->> 'fecha_nacimiento', ''),
    sexo = NULLIF(p_result ->> 'sexo', ''),
    tipo_identificacion = NULLIF(p_result ->> 'tipo_identificacion', ''),
    raw_data = COALESCE(p_result -> 'provider_reference', '{}'::jsonb)
  WHERE id = v_token.id;

  IF v_token.user_id IS NOT NULL THEN
    UPDATE public.user_verification_status SET
      biometric_verified = true,
      biometric_verified_at = COALESCE(biometric_verified_at, v_completed_at),
      biometric_source = 'enrollment',
      enrollment_result_id = v_result_id
    WHERE user_id = v_token.user_id;
  END IF;

  RETURN QUERY SELECT v_result_id;
END;
$function$
;

-- [FUNCTION] public.confirm_organization_ownership_transfer(raw_token text)
CREATE OR REPLACE FUNCTION public.confirm_organization_ownership_transfer(raw_token text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE
  transfer public.organization_ownership_transfers%ROWTYPE;
  current_owner public.workspace_members%ROWTYPE;
  target_member public.workspace_members%ROWTYPE;
  target_profile public.user_profiles%ROWTYPE;
  target_has_mfa BOOLEAN;
  owner_role_id UUID;
  admin_role_id UUID;
BEGIN
  SELECT * INTO transfer
  FROM public.organization_ownership_transfers
  WHERE token_hash = encode(digest(raw_token, 'sha256'), 'hex')
  FOR UPDATE;

  IF transfer.id IS NULL OR transfer.status <> 'pending' THEN
    RAISE EXCEPTION 'organization_ownership_transfer_invalid' USING ERRCODE = 'P0002';
  END IF;
  IF transfer.expires_at <= CURRENT_TIMESTAMP THEN
    UPDATE public.organization_ownership_transfers SET status = 'expired' WHERE id = transfer.id;
    RAISE EXCEPTION 'organization_ownership_transfer_expired' USING ERRCODE = '22023';
  END IF;

  SELECT * INTO current_owner FROM public.workspace_members
  WHERE id = transfer.current_owner_member_id AND workspace_id = transfer.workspace_id AND status = 'active'
  FOR UPDATE;
  SELECT * INTO target_member FROM public.workspace_members
  WHERE id = transfer.target_member_id AND workspace_id = transfer.workspace_id AND status = 'active'
  FOR UPDATE;

  IF target_member.id IS NULL OR target_member.user_id <> auth.uid() THEN
    RAISE EXCEPTION 'organization_ownership_confirmation_denied' USING ERRCODE = '42501';
  END IF;
  IF current_owner.id IS NULL OR current_owner.role <> 'owner'::public.workspace_member_role THEN
    RAISE EXCEPTION 'organization_current_owner_not_available' USING ERRCODE = '23514';
  END IF;
  IF NOT EXISTS (
    SELECT 1 FROM public.workspaces w
    WHERE w.id = transfer.workspace_id AND w.owner_id = current_owner.user_id
  ) THEN
    RAISE EXCEPTION 'organization_workspace_owner_changed' USING ERRCODE = '23514';
  END IF;

  SELECT * INTO target_profile FROM public.user_profiles WHERE id = target_member.user_id;
  IF NOT COALESCE(target_profile.email_verified, FALSE) THEN
    RAISE EXCEPTION 'organization_new_owner_email_not_verified' USING ERRCODE = '23514';
  END IF;
  SELECT EXISTS (
    SELECT 1 FROM public.user_totp_settings t
    WHERE t.user_id = target_member.user_id AND t.is_enabled = TRUE AND t.confirmed_at IS NOT NULL
  ) OR EXISTS (
    SELECT 1 FROM public.webauthn_credentials w
    WHERE w.user_id = target_member.user_id AND w.is_active = TRUE
  ) INTO target_has_mfa;
  IF NOT target_has_mfa THEN
    RAISE EXCEPTION 'organization_new_owner_mfa_required' USING ERRCODE = '23514';
  END IF;

  UPDATE public.workspace_members
  SET role = 'admin'::public.workspace_member_role
  WHERE id = current_owner.id;
  UPDATE public.workspace_members
  SET role = 'owner'::public.workspace_member_role
  WHERE id = target_member.id;
  UPDATE public.workspaces
  SET owner_id = target_member.user_id, updated_at = CURRENT_TIMESTAMP
  WHERE id = transfer.workspace_id;

  SELECT id INTO owner_role_id FROM public.organization_roles
  WHERE workspace_id = transfer.workspace_id AND system_key = 'owner';
  SELECT id INTO admin_role_id FROM public.organization_roles
  WHERE workspace_id = transfer.workspace_id AND system_key = 'admin';

  DELETE FROM public.organization_member_roles omr
  USING public.organization_roles r
  WHERE omr.role_id = r.id
    AND omr.workspace_id = transfer.workspace_id
    AND omr.member_id IN (current_owner.id, target_member.id)
    AND r.system_key IN ('owner', 'admin');
  IF admin_role_id IS NOT NULL THEN
    INSERT INTO public.organization_member_roles (workspace_id, member_id, role_id, assigned_by)
    VALUES (transfer.workspace_id, current_owner.id, admin_role_id, target_member.user_id)
    ON CONFLICT DO NOTHING;
  END IF;
  IF owner_role_id IS NOT NULL THEN
    INSERT INTO public.organization_member_roles (workspace_id, member_id, role_id, assigned_by)
    VALUES (transfer.workspace_id, target_member.id, owner_role_id, target_member.user_id)
    ON CONFLICT DO NOTHING;
  END IF;

  UPDATE public.organization_ownership_transfers
  SET status = 'completed', confirmed_by = target_member.user_id,
      confirmed_at = CURRENT_TIMESTAMP
  WHERE id = transfer.id;

  UPDATE public.organization_ownership_transfers
  SET status = 'cancelled', cancelled_at = CURRENT_TIMESTAMP
  WHERE workspace_id = transfer.workspace_id AND status = 'pending' AND id <> transfer.id;

  INSERT INTO public.organization_audit_events (
    workspace_id, actor_user_id, event_type, resource_type, resource_id,
    summary, severity, module, before_payload, after_payload
  ) VALUES (
    transfer.workspace_id, target_member.user_id, 'organization.ownership_transfer.completed',
    'organization_ownership_transfer', transfer.id::TEXT, 'Propiedad de la organización transferida',
    'critical', 'continuity', jsonb_build_object('owner_user_id', current_owner.user_id),
    jsonb_build_object('owner_user_id', target_member.user_id)
  );

  INSERT INTO public.notifications (user_id, type, title, description, priority, metadata)
  VALUES
    (current_owner.user_id, 'security', 'Propiedad transferida', 'La transferencia de propiedad se completó. Tu acceso continúa con rol de administrador.', 'alta', jsonb_build_object('workspace_id', transfer.workspace_id)),
    (target_member.user_id, 'security', 'Ahora eres propietario', 'La transferencia se confirmó y la organización permanece con un propietario activo.', 'alta', jsonb_build_object('workspace_id', transfer.workspace_id));

  RETURN jsonb_build_object('id', transfer.id, 'status', 'completed', 'workspace_id', transfer.workspace_id, 'new_owner_user_id', target_member.user_id);
END;
$function$
;

-- [FUNCTION] public.consume_signature_otp(p_document_id uuid, p_user_id uuid, p_code_digest text)
CREATE OR REPLACE FUNCTION public.consume_signature_otp(p_document_id uuid, p_user_id uuid, p_code_digest text)
 RETURNS TABLE(status text, challenge_id uuid, attempts_remaining integer)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE
  v_challenge public.signature_otp_challenges%ROWTYPE;
  v_attempts integer;
BEGIN
  IF auth.role() <> 'service_role' THEN
    RAISE EXCEPTION 'SIGNATURE_OTP_SERVICE_ROLE_REQUIRED';
  END IF;
  IF p_code_digest !~ '^[a-f0-9]{64}$' THEN
    RETURN QUERY SELECT 'INVALID'::text, NULL::uuid, 0;
    RETURN;
  END IF;

  SELECT * INTO v_challenge
  FROM public.signature_otp_challenges
  WHERE document_id = p_document_id
    AND user_id = p_user_id
    AND purpose = 'DOCUMENT_SIGNATURE'
    AND delivery_status = 'SENT'
  ORDER BY created_at DESC
  LIMIT 1
  FOR UPDATE;

  IF NOT FOUND THEN RETURN QUERY SELECT 'NOT_FOUND'::text, NULL::uuid, 0; RETURN; END IF;
  IF v_challenge.consumed_at IS NOT NULL THEN RETURN QUERY SELECT 'CONSUMED'::text, v_challenge.id, 0; RETURN; END IF;
  IF v_challenge.locked_at IS NOT NULL THEN RETURN QUERY SELECT 'LOCKED'::text, v_challenge.id, 0; RETURN; END IF;
  IF v_challenge.expires_at <= now() THEN RETURN QUERY SELECT 'EXPIRED'::text, v_challenge.id, 0; RETURN; END IF;

  IF v_challenge.code_digest = lower(p_code_digest) THEN
    UPDATE public.signature_otp_challenges
    SET consumed_at = now()
    WHERE id = v_challenge.id;
    RETURN QUERY SELECT 'VERIFIED'::text, v_challenge.id,
      GREATEST(v_challenge.max_attempts - v_challenge.attempts, 0);
    RETURN;
  END IF;

  v_attempts := v_challenge.attempts + 1;
  UPDATE public.signature_otp_challenges
  SET attempts = v_attempts,
      locked_at = CASE WHEN v_attempts >= max_attempts THEN now() ELSE locked_at END
  WHERE id = v_challenge.id;
  RETURN QUERY SELECT
    CASE WHEN v_attempts >= v_challenge.max_attempts THEN 'LOCKED' ELSE 'INVALID' END::text,
    v_challenge.id,
    GREATEST(v_challenge.max_attempts - v_attempts, 0);
END;
$function$
;

-- [FUNCTION] public.cosine_distance(halfvec, halfvec)
CREATE OR REPLACE FUNCTION public.cosine_distance(halfvec, halfvec)
 RETURNS double precision
 LANGUAGE c
 IMMUTABLE PARALLEL SAFE STRICT
AS '$libdir/vector', $function$halfvec_cosine_distance$function$
;

-- [FUNCTION] public.cosine_distance(sparsevec, sparsevec)
