 RETURNS text
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
  SELECT email FROM auth.users WHERE id = auth.uid() LIMIT 1;
$function$
;

-- [FUNCTION] public.diagnostico_usuarios()
CREATE OR REPLACE FUNCTION public.diagnostico_usuarios()
 RETURNS TABLE(user_id uuid, email text, tiene_workspace boolean, tiene_suscripcion_activa boolean, documentos_count bigint)
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
  SELECT
    up.id AS user_id,
    up.email,
    EXISTS (
      SELECT 1 FROM public.workspace_members wm
      WHERE wm.user_id = up.id
    ) AS tiene_workspace,
    EXISTS (
      SELECT 1 FROM public.subscriptions s
      WHERE s.user_id = up.id AND s.status = 'active'
    ) AS tiene_suscripcion_activa,
    (
      SELECT COUNT(*) FROM public.documentos d
      WHERE d.owner_id = up.id AND d.deleted_at IS NULL
    ) AS documentos_count
  FROM public.user_profiles up
  ORDER BY up.email;
$function$
;

-- [FUNCTION] public.efirma_vault_log_decrypt_attempt(p_vault_id uuid, p_user_id uuid, p_workspace_id uuid, p_document_id uuid, p_outcome text, p_failure_reason text, p_actor_ip text)
CREATE OR REPLACE FUNCTION public.efirma_vault_log_decrypt_attempt(p_vault_id uuid, p_user_id uuid, p_workspace_id uuid, p_document_id uuid DEFAULT NULL::uuid, p_outcome text DEFAULT 'success'::text, p_failure_reason text DEFAULT NULL::text, p_actor_ip text DEFAULT NULL::text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
BEGIN
  -- Registrar en security_audit_chain
  INSERT INTO public.security_audit_chain (
    actor_id,
    workspace_id,
    category,
    action,
    resource_type,
    resource_id,
    outcome,
    metadata,
    ip_address,
    is_legal_event
  )
  SELECT
    p_user_id,
    p_workspace_id,
    'vault',
    CASE p_outcome
      WHEN 'success' THEN 'vault.efirma.webauthn_decrypt_success'
      ELSE 'vault.efirma.webauthn_decrypt_failed'
    END,
    'efirma_vault',
    p_vault_id::TEXT,
    p_outcome,
    jsonb_build_object(
      'vault_id', p_vault_id,
      'document_id', p_document_id,
      'auth_mode', 'webauthn_wrapped',
      'failure_reason', p_failure_reason
    ),
    p_actor_ip::INET,
    true
  WHERE EXISTS (
    SELECT 1 FROM information_schema.tables
    WHERE table_name = 'security_audit_chain'
  );

  -- Si fue exitoso, actualizar last_used_at y use_count
  IF p_outcome = 'success' THEN
    UPDATE public.efirma_sat_vault
    SET
      last_used_at = now(),
      use_count    = use_count + 1,
      updated_at   = now()
    WHERE id = p_vault_id;
  END IF;
END;
$function$
;

-- [FUNCTION] public.efirma_vault_switch_mode(p_vault_id uuid, p_user_id uuid, p_new_mode efirma_auth_mode, p_actor_ip text)
CREATE OR REPLACE FUNCTION public.efirma_vault_switch_mode(p_vault_id uuid, p_user_id uuid, p_new_mode efirma_auth_mode, p_actor_ip text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE
  v_vault       RECORD;
  v_old_mode    public.efirma_auth_mode;
  v_audit_id    UUID;
BEGIN
  -- Verificar que la bóveda pertenece al usuario
  SELECT * INTO v_vault
  FROM public.efirma_sat_vault
  WHERE id = p_vault_id
    AND user_id = p_user_id
    AND vault_status = 'active'
  FOR UPDATE;

  IF NOT FOUND THEN
    RETURN jsonb_build_object(
      'success', false,
      'error', 'vault_not_found'
    );
  END IF;

  v_old_mode := v_vault.auth_mode;

  -- Si el modo es el mismo, no hacer nada
  IF v_old_mode = p_new_mode THEN
    RETURN jsonb_build_object(
      'success', true,
      'changed', false,
      'auth_mode', p_new_mode::TEXT
    );
  END IF;

  -- CRÍTICO: Invalidar contraseña envuelta al cambiar de modo
  -- Nunca reutilizar material cifrado bajo el modo anterior
  UPDATE public.efirma_sat_vault
  SET
    auth_mode                  = p_new_mode,
    encrypted_efirma_password  = NULL,   -- Invalida contraseña envuelta
    webauthn_credential_id     = CASE WHEN p_new_mode = 'password_per_use' THEN NULL ELSE webauthn_credential_id END,
    webauthn_hkdf_salt         = CASE WHEN p_new_mode = 'password_per_use' THEN NULL ELSE webauthn_hkdf_salt END,
    webauthn_wrapped_at        = CASE WHEN p_new_mode = 'password_per_use' THEN NULL ELSE webauthn_wrapped_at END,
    mode_changed_at            = now(),
    updated_at                 = now()
  WHERE id = p_vault_id;

  -- Registrar en security_audit_chain
  INSERT INTO public.security_audit_chain (
    actor_id,
    workspace_id,
    category,
    action,
    resource_type,
    resource_id,
    outcome,
    metadata,
    ip_address,
    is_legal_event
  )
  SELECT
    p_user_id,
    v_vault.workspace_id,
    'vault',
    'vault.efirma.mode_changed',
    'efirma_vault',
    p_vault_id::TEXT,
    'success',
    jsonb_build_object(
      'old_mode', v_old_mode::TEXT,
      'new_mode', p_new_mode::TEXT,
      'wrapped_password_invalidated', true,
      'cert_rfc', v_vault.cert_rfc,
      'cert_serial', v_vault.cert_serial
    ),
    p_actor_ip::INET,
    false
  WHERE EXISTS (
    SELECT 1 FROM information_schema.tables
    WHERE table_name = 'security_audit_chain'
  );

  RETURN jsonb_build_object(
    'success', true,
    'changed', true,
    'old_mode', v_old_mode::TEXT,
    'new_mode', p_new_mode::TEXT,
    'wrapped_password_invalidated', true
  );
END;
$function$
;

-- [FUNCTION] public.enforce_collaboration_usage_event_limit()
CREATE OR REPLACE FUNCTION public.enforce_collaboration_usage_event_limit()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE
  v_limit NUMERIC;
  v_usage NUMERIC;
BEGIN
  PERFORM pg_advisory_xact_lock(
    hashtextextended(NEW.workspace_id::TEXT || ':' || NEW.meter_key, 0)
  );
  SELECT NULLIF(oe.limits ->> NEW.meter_key, '')::NUMERIC
    INTO v_limit
  FROM public.organization_entitlements oe
  WHERE oe.workspace_id = NEW.workspace_id
    AND oe.entitlement_key = NEW.entitlement_key
    AND oe.status IN ('trialing', 'active', 'past_due')
    AND (oe.starts_at IS NULL OR oe.starts_at <= CURRENT_TIMESTAMP)
    AND (oe.ends_at IS NULL OR oe.ends_at > CURRENT_TIMESTAMP)
  LIMIT 1;
  IF v_limit IS NULL THEN RETURN NEW; END IF;

  SELECT COALESCE(SUM(quantity), 0)
    INTO v_usage
  FROM public.collaboration_usage_events
  WHERE workspace_id = NEW.workspace_id
    AND meter_key = NEW.meter_key
    AND occurred_at >= date_trunc('month', CURRENT_TIMESTAMP);
  IF v_usage + NEW.quantity > v_limit THEN
    RAISE EXCEPTION USING
      ERRCODE = 'P0001',
      MESSAGE = 'collaboration_usage_limit_exceeded',
      DETAIL = format('meter=%s usage=%s requested=%s limit=%s', NEW.meter_key, v_usage, NEW.quantity, v_limit),
      HINT = 'Upgrade the Colabora entitlement before retrying.';
  END IF;
  RETURN NEW;
END;
$function$
;

-- [FUNCTION] public.enforce_organization_phase2_tenant_scope()
CREATE OR REPLACE FUNCTION public.enforce_organization_phase2_tenant_scope()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
BEGIN
  IF TG_TABLE_NAME = 'organization_directory_people' AND NEW.member_id IS NOT NULL THEN
    IF NOT EXISTS (
      SELECT 1 FROM public.workspace_members member
      WHERE member.id = NEW.member_id AND member.workspace_id = NEW.workspace_id
    ) THEN
      RAISE EXCEPTION 'organization_directory_member_workspace_mismatch' USING ERRCODE = '23514';
    END IF;
  ELSIF TG_TABLE_NAME = 'organization_directory_evidence' THEN
    IF NOT EXISTS (
      SELECT 1 FROM public.organization_directory_people person
      WHERE person.id = NEW.person_id AND person.workspace_id = NEW.workspace_id
    ) THEN
      RAISE EXCEPTION 'organization_directory_evidence_workspace_mismatch' USING ERRCODE = '23514';
    END IF;
  ELSIF TG_TABLE_NAME = 'organization_shared_resources' THEN
    IF NEW.document_template_id IS NOT NULL AND NOT EXISTS (
      SELECT 1 FROM public.plantillas item
      WHERE item.id = NEW.document_template_id AND item.workspace_id = NEW.workspace_id
    ) THEN
      RAISE EXCEPTION 'organization_document_template_workspace_mismatch' USING ERRCODE = '23514';
    END IF;
    IF NEW.form_template_id IS NOT NULL AND NOT EXISTS (
      SELECT 1 FROM public.form_templates item
      WHERE item.id = NEW.form_template_id AND item.workspace_id = NEW.workspace_id
    ) THEN
      RAISE EXCEPTION 'organization_form_template_workspace_mismatch' USING ERRCODE = '23514';
    END IF;
    IF NEW.workflow_id IS NOT NULL AND NOT EXISTS (
      SELECT 1 FROM public.organization_approval_workflows item
      WHERE item.id = NEW.workflow_id AND item.workspace_id = NEW.workspace_id
    ) THEN
      RAISE EXCEPTION 'organization_resource_workflow_workspace_mismatch' USING ERRCODE = '23514';
    END IF;
    IF NEW.signature_policy_id IS NOT NULL AND NOT EXISTS (
      SELECT 1 FROM public.organization_signature_policies item
      WHERE item.id = NEW.signature_policy_id AND item.workspace_id = NEW.workspace_id
    ) THEN
      RAISE EXCEPTION 'organization_resource_policy_workspace_mismatch' USING ERRCODE = '23514';
    END IF;
  END IF;
  RETURN NEW;
END;
$function$
;

-- [FUNCTION] public.enforce_organization_tenant_scope()
CREATE OR REPLACE FUNCTION public.enforce_organization_tenant_scope()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE
  expected_workspace_id UUID;
  target_role_system_key TEXT;
BEGIN
  IF TG_TABLE_NAME = 'organization_member_roles' THEN
    SELECT workspace_id INTO expected_workspace_id
    FROM public.workspace_members
    WHERE id = NEW.member_id;
    IF expected_workspace_id IS DISTINCT FROM NEW.workspace_id THEN
      RAISE EXCEPTION 'organization_member_workspace_mismatch' USING ERRCODE = '23514';
    END IF;

    SELECT workspace_id INTO expected_workspace_id
    FROM public.organization_roles
    WHERE id = NEW.role_id;
    IF expected_workspace_id IS DISTINCT FROM NEW.workspace_id THEN
      RAISE EXCEPTION 'organization_role_workspace_mismatch' USING ERRCODE = '23514';
    END IF;
  ELSIF TG_TABLE_NAME = 'organization_units' THEN
    IF NEW.parent_id IS NOT NULL THEN
      SELECT workspace_id INTO expected_workspace_id
      FROM public.organization_units
      WHERE id = NEW.parent_id;
      IF expected_workspace_id IS DISTINCT FROM NEW.workspace_id THEN
        RAISE EXCEPTION 'organization_parent_unit_workspace_mismatch' USING ERRCODE = '23514';
      END IF;
    END IF;

    IF NEW.leader_member_id IS NOT NULL THEN
      SELECT workspace_id INTO expected_workspace_id
      FROM public.workspace_members
      WHERE id = NEW.leader_member_id;
      IF expected_workspace_id IS DISTINCT FROM NEW.workspace_id THEN
        RAISE EXCEPTION 'organization_unit_leader_workspace_mismatch' USING ERRCODE = '23514';
      END IF;
    END IF;
  ELSIF TG_TABLE_NAME = 'organization_unit_members' THEN
    SELECT workspace_id INTO expected_workspace_id
    FROM public.organization_units
    WHERE id = NEW.unit_id;
    IF expected_workspace_id IS NULL OR NOT EXISTS (
      SELECT 1
      FROM public.workspace_members wm
      WHERE wm.id = NEW.member_id
        AND wm.workspace_id = expected_workspace_id
    ) THEN
      RAISE EXCEPTION 'organization_unit_member_workspace_mismatch' USING ERRCODE = '23514';
    END IF;
  ELSIF TG_TABLE_NAME = 'organization_invitations' THEN
    IF NEW.role_id IS NOT NULL AND NOT EXISTS (
      SELECT 1
      FROM public.organization_roles r
      WHERE r.id = NEW.role_id
        AND r.workspace_id = NEW.workspace_id
    ) THEN
      RAISE EXCEPTION 'organization_invitation_role_workspace_mismatch' USING ERRCODE = '23514';
    END IF;

    IF NEW.role_id IS NOT NULL THEN
      SELECT system_key INTO target_role_system_key
      FROM public.organization_roles
      WHERE id = NEW.role_id;

      IF target_role_system_key = 'owner' THEN
        RAISE EXCEPTION 'organization_owner_role_cannot_be_invited' USING ERRCODE = '42501';
      END IF;

      IF target_role_system_key IS DISTINCT FROM 'member'
         AND NOT public.has_organization_permission(NEW.workspace_id, 'roles.manage') THEN
        RAISE EXCEPTION 'organization_invitation_role_assignment_denied' USING ERRCODE = '42501';
      END IF;
    END IF;

    IF NEW.unit_id IS NOT NULL AND NOT EXISTS (
      SELECT 1
      FROM public.organization_units u
      WHERE u.id = NEW.unit_id
        AND u.workspace_id = NEW.workspace_id
    ) THEN
      RAISE EXCEPTION 'organization_invitation_unit_workspace_mismatch' USING ERRCODE = '23514';
    END IF;
  ELSIF TG_TABLE_NAME = 'organization_authorities' THEN
    IF NEW.person_id IS NOT NULL AND NOT EXISTS (
      SELECT 1
      FROM public.organization_directory_people person
      WHERE person.id = NEW.person_id
        AND person.workspace_id = NEW.workspace_id
    ) THEN
      RAISE EXCEPTION 'organization_authority_person_workspace_mismatch' USING ERRCODE = '23514';
    END IF;

    IF NEW.member_id IS NOT NULL AND NOT EXISTS (
      SELECT 1
      FROM public.workspace_members wm
      WHERE wm.id = NEW.member_id
        AND wm.workspace_id = NEW.workspace_id
    ) THEN
      RAISE EXCEPTION 'organization_authority_member_workspace_mismatch' USING ERRCODE = '23514';
    END IF;
  END IF;

  RETURN NEW;
END;
$function$
;

-- [FUNCTION] public.enforce_single_collaboration_plan()
CREATE OR REPLACE FUNCTION public.enforce_single_collaboration_plan()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE
  v_product public.addon_products%ROWTYPE;
  v_key TEXT;
  v_pro_keys CONSTANT TEXT[] := ARRAY[
    'collaboration_external_rooms',
    'collaboration_data_rooms',
    'collaboration_advanced_workflows',
    'collaboration_automations',
    'collaboration_ai_assistant'
  ];
BEGIN
  IF NEW.status NOT IN ('trialing', 'active', 'past_due') THEN
    RETURN NEW;
  END IF;

  SELECT * INTO v_product FROM public.addon_products WHERE id = NEW.product_id;
  IF v_product.product_key NOT IN ('docubox_colabora', 'docubox_colabora_pro') THEN
    RETURN NEW;
  END IF;

  UPDATE public.organization_addon_subscriptions other
  SET status = 'cancelled',
      cancelled_at = COALESCE(other.cancelled_at, CURRENT_TIMESTAMP),
      read_only_at = COALESCE(other.read_only_at, CURRENT_TIMESTAMP),
      metadata = other.metadata || jsonb_build_object(
        'superseded_by_product', v_product.product_key,
        'superseded_at', CURRENT_TIMESTAMP
      ),
      updated_at = CURRENT_TIMESTAMP
  FROM public.addon_products other_product
  WHERE other.product_id = other_product.id
    AND other.workspace_id = NEW.workspace_id
    AND other.id <> NEW.id
    AND other_product.product_key IN ('docubox_colabora', 'docubox_colabora_pro')
    AND other.status IN ('trialing', 'active', 'past_due');

  IF v_product.product_key = 'docubox_colabora' THEN
    FOREACH v_key IN ARRAY v_pro_keys LOOP
      UPDATE public.organization_entitlements
      SET status = 'suspended',
          read_only_at = COALESCE(read_only_at, CURRENT_TIMESTAMP),
          ends_at = COALESCE(ends_at, CURRENT_TIMESTAMP),
          metadata = metadata || jsonb_build_object(
            'suspended_by_downgrade', TRUE,
            'suspended_at', CURRENT_TIMESTAMP
          ),
          updated_at = CURRENT_TIMESTAMP
      WHERE workspace_id = NEW.workspace_id
        AND entitlement_key = v_key
        AND status <> 'inactive';
    END LOOP;

    UPDATE public.collaboration_automations
    SET status = 'paused', updated_at = CURRENT_TIMESTAMP
    WHERE workspace_id = NEW.workspace_id AND status = 'active';

    UPDATE public.collaboration_external_sessions
    SET revoked_at = COALESCE(revoked_at, CURRENT_TIMESTAMP)
    WHERE workspace_id = NEW.workspace_id AND revoked_at IS NULL;

    UPDATE public.collaboration_room_guests
    SET status = 'revoked',
        revoked_at = COALESCE(revoked_at, CURRENT_TIMESTAMP),
        updated_at = CURRENT_TIMESTAMP
    WHERE workspace_id = NEW.workspace_id
      AND status IN ('pending', 'active');

    UPDATE public.collaboration_rooms
    SET status = 'closed',
        closed_at = COALESCE(closed_at, CURRENT_TIMESTAMP),
        updated_at = CURRENT_TIMESTAMP
    WHERE workspace_id = NEW.workspace_id
      AND status IN ('draft', 'active');
  END IF;

  RETURN NEW;
END;
$function$
;

-- [FUNCTION] public.enforce_workspace_member_update_scope()
CREATE OR REPLACE FUNCTION public.enforce_workspace_member_update_scope()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
BEGIN
  IF current_user IN ('postgres', 'supabase_admin') OR public.is_workspace_admin(OLD.workspace_id) THEN
    RETURN NEW;
  END IF;

  IF NEW.id IS DISTINCT FROM OLD.id
     OR NEW.workspace_id IS DISTINCT FROM OLD.workspace_id
     OR NEW.user_id IS DISTINCT FROM OLD.user_id
     OR NEW.joined_at IS DISTINCT FROM OLD.joined_at
     OR NEW.invited_by IS DISTINCT FROM OLD.invited_by
     OR NEW.last_access_at IS DISTINCT FROM OLD.last_access_at THEN
    RAISE EXCEPTION 'organization_member_protected_fields' USING ERRCODE = '42501';
  END IF;

  IF NEW.role IS DISTINCT FROM OLD.role
     AND NOT public.has_organization_permission(OLD.workspace_id, 'roles.manage') THEN
    RAISE EXCEPTION 'organization_member_role_update_denied' USING ERRCODE = '42501';
  END IF;

  IF NEW.status IS DISTINCT FROM OLD.status THEN
    IF NEW.status = 'offboarded'
       AND NOT public.has_organization_permission(OLD.workspace_id, 'members.offboard') THEN
      RAISE EXCEPTION 'organization_member_offboard_denied' USING ERRCODE = '42501';
    ELSIF NEW.status IN ('active', 'suspended', 'blocked')
          AND NOT public.has_organization_permission(OLD.workspace_id, 'members.suspend') THEN
      RAISE EXCEPTION 'organization_member_status_update_denied' USING ERRCODE = '42501';
    ELSIF NEW.status = 'invited'
          AND NOT public.has_organization_permission(OLD.workspace_id, 'members.update') THEN
      RAISE EXCEPTION 'organization_member_update_denied' USING ERRCODE = '42501';
    END IF;
  END IF;

  IF (
    NEW.job_title IS DISTINCT FROM OLD.job_title
    OR NEW.mfa_required IS DISTINCT FROM OLD.mfa_required
    OR NEW.biometric_required IS DISTINCT FROM OLD.biometric_required
    OR NEW.access_expires_at IS DISTINCT FROM OLD.access_expires_at
  ) AND NOT public.has_organization_permission(OLD.workspace_id, 'members.update') THEN
    RAISE EXCEPTION 'organization_member_update_denied' USING ERRCODE = '42501';
  END IF;

  IF NEW.suspended_at IS DISTINCT FROM OLD.suspended_at
     AND NOT public.has_organization_permission(OLD.workspace_id, 'members.suspend') THEN
    RAISE EXCEPTION 'organization_member_suspend_denied' USING ERRCODE = '42501';
  END IF;

  IF NEW.offboarded_at IS DISTINCT FROM OLD.offboarded_at
     AND NOT public.has_organization_permission(OLD.workspace_id, 'members.offboard') THEN
    RAISE EXCEPTION 'organization_member_offboard_denied' USING ERRCODE = '42501';
  END IF;

  RETURN NEW;
END;
$function$
;

-- [FUNCTION] public.enforce_workspace_organization_update_scope()
CREATE OR REPLACE FUNCTION public.enforce_workspace_organization_update_scope()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
BEGIN
  -- Trusted SECURITY DEFINER functions use the table owner while bootstrapping a
  -- workspace. Client requests continue to be evaluated as authenticated.
  IF current_user IN ('postgres', 'supabase_admin') THEN
    RETURN NEW;
  END IF;

  IF public.is_workspace_admin(OLD.id) THEN
    RETURN NEW;
  END IF;

  IF NEW.id IS DISTINCT FROM OLD.id
     OR NEW.owner_id IS DISTINCT FROM OLD.owner_id
     OR NEW.workspace_type IS DISTINCT FROM OLD.workspace_type
     OR NEW.organization_enabled IS DISTINCT FROM OLD.organization_enabled
     OR NEW.created_at IS DISTINCT FROM OLD.created_at THEN
    RAISE EXCEPTION 'organization_workspace_protected_fields' USING ERRCODE = '42501';
  END IF;

  IF (
    NEW.name IS DISTINCT FROM OLD.name
    OR NEW.description IS DISTINCT FROM OLD.description
    OR NEW.legal_name IS DISTINCT FROM OLD.legal_name
    OR NEW.trade_name IS DISTINCT FROM OLD.trade_name
    OR NEW.rfc IS DISTINCT FROM OLD.rfc
    OR NEW.legal_person_type IS DISTINCT FROM OLD.legal_person_type
    OR NEW.tax_regime IS DISTINCT FROM OLD.tax_regime
    OR NEW.industry IS DISTINCT FROM OLD.industry
    OR NEW.website IS DISTINCT FROM OLD.website
    OR NEW.contact_email IS DISTINCT FROM OLD.contact_email
    OR NEW.contact_phone IS DISTINCT FROM OLD.contact_phone
    OR NEW.timezone IS DISTINCT FROM OLD.timezone
    OR NEW.locale IS DISTINCT FROM OLD.locale
    OR NEW.currency IS DISTINCT FROM OLD.currency
    OR NEW.fiscal_address IS DISTINCT FROM OLD.fiscal_address
    OR NEW.legal_representative IS DISTINCT FROM OLD.legal_representative
    OR NEW.verification_status IS DISTINCT FROM OLD.verification_status
    OR NEW.verification_updated_at IS DISTINCT FROM OLD.verification_updated_at
    OR NEW.kyb_status IS DISTINCT FROM OLD.kyb_status
    OR NEW.organization_settings IS DISTINCT FROM OLD.organization_settings
  ) AND NOT public.has_organization_permission(OLD.id, 'organization.profile.update') THEN
    RAISE EXCEPTION 'organization_profile_update_denied' USING ERRCODE = '42501';
  END IF;

  IF NEW.security_settings IS DISTINCT FROM OLD.security_settings
     AND NOT public.has_organization_permission(OLD.id, 'security.manage') THEN
    RAISE EXCEPTION 'organization_security_update_denied' USING ERRCODE = '42501';
  END IF;

  IF (
    NEW.branding_settings IS DISTINCT FROM OLD.branding_settings
    OR NEW.logo_url IS DISTINCT FROM OLD.logo_url
  ) AND NOT public.has_organization_permission(OLD.id, 'branding.manage') THEN
    RAISE EXCEPTION 'organization_branding_update_denied' USING ERRCODE = '42501';
  END IF;

  RETURN NEW;
END;
$function$
;

-- [FUNCTION] public.enqueue_collaboration_automations_for_activity()
CREATE OR REPLACE FUNCTION public.enqueue_collaboration_automations_for_activity()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE
  candidate RECORD;
  event_depth INTEGER;
BEGIN
  event_depth := COALESCE((NEW.metadata ->> 'automation_depth')::INTEGER, 0);

  FOR candidate IN
    SELECT
      automation.id AS automation_id,
      automation.workspace_id,
      automation.max_depth,
      version.id AS version_id,
      version.trigger_definition
    FROM public.collaboration_automations automation
    JOIN public.collaboration_automation_versions version
      ON version.automation_id = automation.id
     AND version.version = automation.current_version
     AND version.published_at IS NOT NULL
    WHERE automation.workspace_id = NEW.workspace_id
      AND automation.status = 'active'
      AND (
        version.trigger_definition ->> 'event_type' = NEW.event_type
        OR version.trigger_definition ->> 'event_type' = '*'
      )
  LOOP
    IF event_depth < candidate.max_depth THEN
      INSERT INTO public.collaboration_automation_runs (
        workspace_id,
        automation_id,
        automation_version_id,
        event_id,
        idempotency_key,
        correlation_id,
        depth,
        input_snapshot,
        status,
        scheduled_at
      )
      VALUES (
        candidate.workspace_id,
        candidate.automation_id,
        candidate.version_id,
        NEW.id::TEXT,
        'activity:' || NEW.id::TEXT || ':automation:' || candidate.automation_id::TEXT,
        NEW.correlation_id,
        event_depth + 1,
        jsonb_build_object(
          'activity_event_id', NEW.id,
          'event_type', NEW.event_type,
          'resource_type', NEW.resource_type,
          'resource_id', NEW.resource_id,
          'actor_user_id', NEW.actor_user_id,
          'metadata', NEW.metadata
        ),
        'queued',
        CURRENT_TIMESTAMP
      )
      ON CONFLICT (workspace_id, idempotency_key) DO NOTHING;
    END IF;
  END LOOP;

  RETURN NEW;
END;
$function$
;

-- [FUNCTION] public.execute_organization_member_offboarding_job(target_job_id uuid)
CREATE OR REPLACE FUNCTION public.execute_organization_member_offboarding_job(target_job_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE
  job public.organization_member_offboarding_jobs%ROWTYPE;
  target_member public.workspace_members%ROWTYPE;
  successor_member public.workspace_members%ROWTYPE;
  target_email TEXT;
  report JSONB;
  started TIMESTAMPTZ := clock_timestamp();
  affected INTEGER;
  documents_count INTEGER := 0;
  cases_count INTEGER := 0;
  tasks_count INTEGER := 0;
  owned_resources_count INTEGER := 0;
  custody_resources_count INTEGER := 0;
  teams_count INTEGER := 0;
  units_removed_count INTEGER := 0;
  cost_centers_count INTEGER := 0;
  certificate_permissions_count INTEGER := 0;
  authorities_count INTEGER := 0;
  sessions_count INTEGER := 0;
  api_keys_count INTEGER := 0;
  invitations_count INTEGER := 0;
  error_state TEXT;
  error_message TEXT;
BEGIN
  SELECT * INTO job
  FROM public.organization_member_offboarding_jobs
  WHERE id = target_job_id
  FOR UPDATE;

  IF job.id IS NULL THEN
    RAISE EXCEPTION 'organization_offboarding_job_not_found' USING ERRCODE = 'P0002';
  END IF;
  IF auth.role() <> 'service_role' AND NOT public.has_organization_permission(job.workspace_id, 'members.offboard') THEN
    RAISE EXCEPTION 'organization_permission_denied' USING ERRCODE = '42501';
  END IF;
  IF job.status = 'completed' THEN
    RETURN COALESCE(job.completion_report, jsonb_build_object('id', job.id, 'status', 'completed'));
  END IF;
  IF job.status IN ('cancelled', 'failed') THEN
    RAISE EXCEPTION 'organization_offboarding_job_not_executable' USING ERRCODE = '23514';
  END IF;
  IF job.effective_at > CURRENT_TIMESTAMP THEN
    RAISE EXCEPTION 'organization_offboarding_not_due' USING ERRCODE = '22023';
  END IF;

  UPDATE public.organization_member_offboarding_jobs
  SET status = 'processing', started_at = CURRENT_TIMESTAMP, failure_code = NULL, failure_detail = NULL
  WHERE id = job.id;

  BEGIN
    SELECT * INTO target_member
    FROM public.workspace_members
    WHERE id = job.member_id AND workspace_id = job.workspace_id
    FOR UPDATE;

    IF target_member.id IS NULL OR target_member.status = 'offboarded' THEN
      RAISE EXCEPTION 'organization_member_not_available';
    END IF;
    IF target_member.role = 'owner'::public.workspace_member_role THEN
      RAISE EXCEPTION 'organization_owner_transfer_required';
    END IF;

    SELECT email INTO target_email FROM public.user_profiles WHERE id = target_member.user_id;

    IF job.successor_member_id IS NOT NULL THEN
      SELECT * INTO successor_member
      FROM public.workspace_members
      WHERE id = job.successor_member_id AND workspace_id = job.workspace_id AND status = 'active'
      FOR UPDATE;
      IF successor_member.id IS NULL THEN
        RAISE EXCEPTION 'organization_invalid_successor';
      END IF;
    END IF;

    IF COALESCE((job.transfer_plan ->> 'documents')::BOOLEAN, TRUE) THEN
      UPDATE public.documentos SET owner_id = successor_member.user_id
      WHERE workspace_id = job.workspace_id AND owner_id = target_member.user_id AND successor_member.id IS NOT NULL;
      GET DIAGNOSTICS documents_count = ROW_COUNT;
    END IF;

    IF COALESCE((job.transfer_plan ->> 'case_files')::BOOLEAN, TRUE) THEN
      UPDATE public.case_files SET owner_user_id = successor_member.user_id
      WHERE workspace_id = job.workspace_id AND owner_user_id = target_member.user_id AND successor_member.id IS NOT NULL;
      GET DIAGNOSTICS cases_count = ROW_COUNT;
    END IF;

    IF COALESCE((job.transfer_plan ->> 'tasks')::BOOLEAN, TRUE) THEN
      UPDATE public.tareas SET assigned_to = successor_member.user_id
      WHERE workspace_id = job.workspace_id AND assigned_to = target_member.user_id AND successor_member.id IS NOT NULL;
      GET DIAGNOSTICS tasks_count = ROW_COUNT;
    END IF;

    IF COALESCE((job.transfer_plan ->> 'shared_resources')::BOOLEAN, TRUE) THEN
      UPDATE public.organization_shared_resources SET owner_user_id = successor_member.user_id
      WHERE workspace_id = job.workspace_id AND owner_user_id = target_member.user_id AND successor_member.id IS NOT NULL;
      GET DIAGNOSTICS owned_resources_count = ROW_COUNT;

      UPDATE public.organization_shared_resources SET custodian_user_id = successor_member.user_id
      WHERE workspace_id = job.workspace_id AND custodian_user_id = target_member.user_id AND successor_member.id IS NOT NULL;
      GET DIAGNOSTICS custody_resources_count = ROW_COUNT;
    END IF;

    IF COALESCE((job.transfer_plan ->> 'responsibilities')::BOOLEAN, TRUE) THEN
      UPDATE public.organization_units SET leader_member_id = successor_member.id
      WHERE workspace_id = job.workspace_id AND leader_member_id = target_member.id AND successor_member.id IS NOT NULL;
      GET DIAGNOSTICS teams_count = ROW_COUNT;

      DELETE FROM public.organization_unit_members
      WHERE member_id = target_member.id
        AND unit_id IN (SELECT id FROM public.organization_units WHERE workspace_id = job.workspace_id);
      GET DIAGNOSTICS units_removed_count = ROW_COUNT;

      UPDATE public.organization_cost_centers SET owner_member_id = successor_member.id
      WHERE workspace_id = job.workspace_id AND owner_member_id = target_member.id AND successor_member.id IS NOT NULL;
      GET DIAGNOSTICS cost_centers_count = ROW_COUNT;

      UPDATE public.organization_certificate_permissions SET member_id = successor_member.id
      WHERE workspace_id = job.workspace_id AND member_id = target_member.id AND successor_member.id IS NOT NULL;
      GET DIAGNOSTICS certificate_permissions_count = ROW_COUNT;
    END IF;

    UPDATE public.organization_authorities
    SET status = 'suspended', updated_at = CURRENT_TIMESTAMP
    WHERE workspace_id = job.workspace_id AND member_id = target_member.id AND status IN ('active', 'pending_validation');
    GET DIAGNOSTICS authorities_count = ROW_COUNT;

    INSERT INTO public.organization_session_revocations (
      workspace_id, member_id, session_id, scope, reason, revoked_by
    )
    SELECT job.workspace_id, target_member.id, s.id, 'member_all',
      COALESCE(job.reason, 'Baja organizacional'), job.requested_by
    FROM public.user_sessions s
    WHERE s.user_id = target_member.user_id
      AND (s.expires_at IS NULL OR s.expires_at > CURRENT_TIMESTAMP)
      AND s.session_token NOT LIKE 'revoked:%';
    GET DIAGNOSTICS sessions_count = ROW_COUNT;

    UPDATE public.user_sessions
    SET expires_at = CURRENT_TIMESTAMP,
        is_current = FALSE,
        session_token = 'revoked:offboarding:' || id::TEXT || ':' || extract(epoch from CURRENT_TIMESTAMP)::BIGINT::TEXT
    WHERE user_id = target_member.user_id
      AND (expires_at IS NULL OR expires_at > CURRENT_TIMESTAMP)
      AND session_token NOT LIKE 'revoked:%';

    IF COALESCE((job.transfer_plan ->> 'api_credentials')::BOOLEAN, TRUE) THEN
      UPDATE public.organization_api_credentials
      SET status = 'revoked', revoked_at = CURRENT_TIMESTAMP
      WHERE workspace_id = job.workspace_id AND created_by = target_member.user_id AND status = 'active';
      GET DIAGNOSTICS api_keys_count = ROW_COUNT;
    END IF;

    UPDATE public.organization_invitations
    SET status = 'revoked'
    WHERE workspace_id = job.workspace_id AND lower(email) = lower(target_email) AND status = 'pending';
    GET DIAGNOSTICS invitations_count = ROW_COUNT;

    UPDATE public.workspace_members
    SET status = 'offboarded', offboarded_at = CURRENT_TIMESTAMP,
        suspended_at = COALESCE(suspended_at, CURRENT_TIMESTAMP), access_expires_at = CURRENT_TIMESTAMP
    WHERE id = target_member.id AND workspace_id = job.workspace_id;

    report := jsonb_build_object(
      'id', job.id,
      'status', 'completed',
      'member_id', target_member.id,
      'successor_member_id', successor_member.id,
      'effective_at', job.effective_at,
      'completed_at', CURRENT_TIMESTAMP,
      'transferred', jsonb_build_object(
        'documents', documents_count,
        'case_files', cases_count,
        'tasks', tasks_count,
        'shared_resources_owned', owned_resources_count,
        'shared_resources_custodied', custody_resources_count,
        'teams_led', teams_count,
        'unit_memberships_removed', units_removed_count,
        'cost_centers', cost_centers_count,
        'certificate_permissions', certificate_permissions_count
      ),
      'revoked', jsonb_build_object(
        'authorities_suspended', authorities_count,
        'sessions', sessions_count,
        'api_credentials', api_keys_count,
        'pending_invitations', invitations_count
      ),
      'preserved', jsonb_build_array('membership_history', 'document_authorship', 'signature_evidence', 'audit_history', 'personal_authenticators')
    );

    UPDATE public.organization_member_offboarding_jobs
    SET status = 'completed', completion_report = report, completed_at = CURRENT_TIMESTAMP
    WHERE id = job.id;

    INSERT INTO public.organization_audit_events (
      workspace_id, actor_user_id, event_type, resource_type, resource_id,
      summary, severity, module, payload, duration_ms
    ) VALUES (
      job.workspace_id, job.requested_by, 'member.offboarding.completed',
      'organization_member_offboarding_job', job.id::TEXT, 'Baja organizacional concluida',
      'critical', 'continuity', report,
      GREATEST(0, (extract(epoch FROM (clock_timestamp() - started)) * 1000)::INTEGER)
    );

    INSERT INTO public.notifications (user_id, type, title, description, priority, metadata)
    VALUES (
      target_member.user_id, 'security', 'Acceso a organización finalizado',
      'Tu membresía fue dada de baja. El historial documental y de firma se conserva.', 'alta',
      jsonb_build_object('workspace_id', job.workspace_id, 'offboarding_job_id', job.id)
    );

    IF successor_member.id IS NOT NULL THEN
      INSERT INTO public.notifications (user_id, type, title, description, priority, metadata)
      VALUES (
        successor_member.user_id, 'organization', 'Responsabilidades reasignadas',
        'Recibiste activos y responsabilidades por una baja organizacional.', 'alta',
        jsonb_build_object('workspace_id', job.workspace_id, 'offboarding_job_id', job.id)
      );
    END IF;

    RETURN report;
  EXCEPTION WHEN OTHERS THEN
    GET STACKED DIAGNOSTICS error_state = RETURNED_SQLSTATE, error_message = MESSAGE_TEXT;
    UPDATE public.organization_member_offboarding_jobs
    SET status = 'failed', failure_code = error_state, failure_detail = left(error_message, 1000)
    WHERE id = job.id;

    INSERT INTO public.organization_audit_events (
      workspace_id, actor_user_id, event_type, resource_type, resource_id,
      summary, outcome, severity, module, payload, duration_ms
    ) VALUES (
      job.workspace_id, job.requested_by, 'member.offboarding.failed',
      'organization_member_offboarding_job', job.id::TEXT, 'La baja organizacional no pudo completarse',
      'failed', 'critical', 'continuity', jsonb_build_object('failure_code', error_state),
      GREATEST(0, (extract(epoch FROM (clock_timestamp() - started)) * 1000)::INTEGER)
    );

    RETURN jsonb_build_object('id', job.id, 'status', 'failed', 'failure_code', error_state, 'message', 'No se realizó ningún cambio. Revisa la configuración y reintenta.');
  END;
END;
$function$
;

-- [FUNCTION] public.expire_efirma_vaults()
CREATE OR REPLACE FUNCTION public.expire_efirma_vaults()
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE
  v_count INT;
BEGIN
  UPDATE public.efirma_sat_vault
  SET vault_status = 'expired', updated_at = now()
  WHERE vault_status = 'active'
    AND expires_at < now();

  GET DIAGNOSTICS v_count = ROW_COUNT;
  RETURN v_count;
END;
$function$
;

-- [FUNCTION] public.fn_queue_xml_generation()
CREATE OR REPLACE FUNCTION public.fn_queue_xml_generation()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
BEGIN
  IF NEW.status = 'completado' AND OLD.status <> 'completado' THEN
    INSERT INTO public.xml_generation_queue (document_id)
    VALUES (NEW.id);
  END IF;
  RETURN NEW;
END;
$function$
;

-- [FUNCTION] public.fn_update_document_metadata_analyzed_at()
CREATE OR REPLACE FUNCTION public.fn_update_document_metadata_analyzed_at()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
