  NEW.analyzed_at = NOW();
  RETURN NEW;
END;
$function$
;

-- [FUNCTION] public.force_backfill_participantes_user_ids()
CREATE OR REPLACE FUNCTION public.force_backfill_participantes_user_ids()
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE
  v_doc RECORD;
  v_updated_parts JSONB;
  v_part JSONB;
  v_user_id UUID;
  v_count INTEGER := 0;
BEGIN
  FOR v_doc IN
    SELECT id, participantes
    FROM public.documentos
    WHERE participantes IS NOT NULL
      AND jsonb_array_length(COALESCE(participantes, '[]'::jsonb)) > 0
      AND deleted_at IS NULL
  LOOP
    v_updated_parts := '[]'::jsonb;
    
    FOR v_part IN SELECT * FROM jsonb_array_elements(v_doc.participantes)
    LOOP
      -- Update if email is present (always re-lookup to fix any stale/wrong user_id)
      IF (v_part->>'email') IS NOT NULL AND (v_part->>'email') != '' THEN
        SELECT au.id INTO v_user_id
        FROM auth.users au
        WHERE lower(au.email) = lower(v_part->>'email')
        LIMIT 1;
        
        IF v_user_id IS NOT NULL THEN
          -- Always set/overwrite user_id to ensure it's correct
          v_part := jsonb_set(v_part, '{user_id}', to_jsonb(v_user_id::text));
          v_count := v_count + 1;
        END IF;
      END IF;
      
      v_updated_parts := v_updated_parts || jsonb_build_array(v_part);
    END LOOP;
    
    -- Always update to ensure consistency
    UPDATE public.documentos
    SET participantes = v_updated_parts
    WHERE id = v_doc.id;
  END LOOP;
  
  RETURN v_count;
END;
$function$
;

-- [FUNCTION] public.generate_participant_dek_wrap(p_document_id uuid, p_workspace_id uuid, p_participant_email text, p_participant_user_id uuid, p_participant_role text, p_wrapped_dek text, p_kek_version text, p_key_derivation_ctx jsonb)
CREATE OR REPLACE FUNCTION public.generate_participant_dek_wrap(p_document_id uuid, p_workspace_id uuid, p_participant_email text, p_participant_user_id uuid, p_participant_role text, p_wrapped_dek text, p_kek_version text DEFAULT 'docubox-kek-v1'::text, p_key_derivation_ctx jsonb DEFAULT '{}'::jsonb)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE
  v_existing_id UUID;
  v_new_id      UUID;
BEGIN
  -- Check if an active DEK already exists for this participant
  SELECT id INTO v_existing_id
  FROM public.document_participant_deks
  WHERE document_id      = p_document_id
    AND participant_email = p_participant_email
    AND access_status    = 'active'
  LIMIT 1;

  IF v_existing_id IS NOT NULL THEN
    -- Already has an active DEK — idempotent, return existing id
    RETURN v_existing_id;
  END IF;

  -- Insert the new participant DEK wrap
  INSERT INTO public.document_participant_deks (
    document_id,
    workspace_id,
    participant_user_id,
    participant_email,
    participant_role,
    wrapped_dek,
    kek_version,
    wrap_algorithm,
    key_derivation_context,
    access_status,
    granted_at,
    created_at
  ) VALUES (
    p_document_id,
    p_workspace_id,
    p_participant_user_id,
    p_participant_email,
    p_participant_role,
    p_wrapped_dek,
    p_kek_version,
    'AES-256-GCM',
    p_key_derivation_ctx,
    'active',
    now(),
    now()
  )
  RETURNING id INTO v_new_id;

  RETURN v_new_id;
END;
$function$
;

-- [FUNCTION] public.get_collaboration_usage_snapshot(ws_id uuid)
CREATE OR REPLACE FUNCTION public.get_collaboration_usage_snapshot(ws_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE
  v_result JSONB;
BEGIN
  IF NOT public.is_active_workspace_member(ws_id)
     OR NOT public.has_organization_permission(ws_id, 'reports.view') THEN
    RAISE EXCEPTION 'permission_denied' USING ERRCODE = '42501';
  END IF;

  SELECT jsonb_build_object(
    'active_internal_users', (SELECT COUNT(*) FROM public.workspace_members WHERE workspace_id = ws_id AND status = 'active'),
    'active_spaces', (SELECT COUNT(*) FROM public.collaboration_spaces WHERE workspace_id = ws_id AND status = 'active'),
    'active_external_guests', (SELECT COUNT(*) FROM public.collaboration_room_guests WHERE workspace_id = ws_id AND status IN ('pending', 'active')),
    'external_rooms', (SELECT COUNT(*) FROM public.collaboration_rooms WHERE workspace_id = ws_id AND room_type <> 'data_room' AND status = 'active'),
    'data_rooms', (SELECT COUNT(*) FROM public.collaboration_rooms WHERE workspace_id = ws_id AND room_type = 'data_room' AND status = 'active'),
    'storage_bytes',
      COALESCE((SELECT SUM(file_size) FROM public.documentos WHERE workspace_id = ws_id), 0)
      + COALESCE((SELECT SUM(byte_size) FROM public.collaboration_request_files WHERE workspace_id = ws_id), 0),
    'comparisons', COALESCE((SELECT SUM(quantity) FROM public.collaboration_usage_events WHERE workspace_id = ws_id AND meter_key = 'comparisons' AND occurred_at >= date_trunc('month', CURRENT_TIMESTAMP)), 0),
    'automation_runs', COALESCE((SELECT SUM(quantity) FROM public.collaboration_usage_events WHERE workspace_id = ws_id AND meter_key = 'automation_runs' AND occurred_at >= date_trunc('month', CURRENT_TIMESTAMP)), 0),
    'ai_requests', COALESCE((SELECT SUM(quantity) FROM public.collaboration_usage_events WHERE workspace_id = ws_id AND meter_key = 'ai_requests' AND occurred_at >= date_trunc('month', CURRENT_TIMESTAMP)), 0),
    'generated_at', CURRENT_TIMESTAMP
  ) INTO v_result;
  RETURN v_result;
END;
$function$
;

-- [FUNCTION] public.get_document_chunks_count(p_document_id uuid, p_workspace_id uuid)
CREATE OR REPLACE FUNCTION public.get_document_chunks_count(p_document_id uuid, p_workspace_id uuid)
 RETURNS integer
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
  SELECT COUNT(*)::integer
  FROM public.ai_document_chunks
  WHERE document_id = p_document_id
    AND workspace_id = p_workspace_id;
$function$
;

-- [FUNCTION] public.get_document_with_evidence(p_document_id uuid)
CREATE OR REPLACE FUNCTION public.get_document_with_evidence(p_document_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE
  v_result JSONB;
BEGIN
  SELECT jsonb_build_object(
    'document', row_to_json(d.*),
    'evidence', row_to_json(e.*)
  )
  INTO v_result
  FROM public.documents d
  LEFT JOIN public.document_evidence e ON e.document_id = d.id
  WHERE d.id = p_document_id;

  RETURN v_result;
END;
$function$
;

-- [FUNCTION] public.get_immutable_evidence_status(p_document_id uuid)
CREATE OR REPLACE FUNCTION public.get_immutable_evidence_status(p_document_id uuid)
 RETURNS TABLE(evidence_id uuid, document_id uuid, evidence_status text, evidence_hash character, evidence_timestamp timestamp with time zone, evidence_confirmed_at timestamp with time zone, evidence_url text, confirmations_current integer, confirmations_required integer)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
BEGIN
  -- Verificar que el usuario autenticado es miembro del workspace del documento
  IF NOT EXISTS (
    SELECT 1
    FROM public.documentos d
    JOIN public.workspace_members wm ON wm.workspace_id = d.workspace_id
    WHERE d.id = p_document_id
      AND wm.user_id = auth.uid()
  ) THEN
    RAISE EXCEPTION 'Acceso denegado al documento %', p_document_id;
  END IF;

  RETURN QUERY
  SELECT
    pn.id                       AS evidence_id,
    pn.document_id              AS document_id,
    pn.notarization_status      AS evidence_status,
    pn.document_hash            AS evidence_hash,
    pn.submitted_at             AS evidence_timestamp,
    pn.confirmed_at             AS evidence_confirmed_at,
    pn.explorer_url             AS evidence_url,
    pn.confirmations_current    AS confirmations_current,
    pn.confirmations_required   AS confirmations_required
  FROM public.polygon_notarizations pn
  WHERE pn.document_id = p_document_id
  ORDER BY pn.created_at DESC
  LIMIT 1;
END;
$function$
;

-- [FUNCTION] public.get_my_collaboration_access(ws_id uuid)
CREATE OR REPLACE FUNCTION public.get_my_collaboration_access(ws_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE
  v_workspace public.workspaces%ROWTYPE;
  v_membership public.workspace_members%ROWTYPE;
  v_subscription public.organization_addon_subscriptions%ROWTYPE;
  v_product_key TEXT;
  v_entitlements JSONB;
  v_permissions JSONB;
  v_write_allowed BOOLEAN := FALSE;
  v_tier TEXT := 'none';
BEGIN
  SELECT * INTO v_workspace FROM public.workspaces WHERE id = ws_id;
  SELECT * INTO v_membership FROM public.workspace_members
    WHERE workspace_id = ws_id AND user_id = auth.uid() LIMIT 1;

  IF v_workspace.id IS NULL OR v_membership.id IS NULL THEN
    RETURN jsonb_build_object('eligible', FALSE, 'accessible', FALSE, 'code', 'NOT_A_MEMBER');
  END IF;

  SELECT oas.* INTO v_subscription
  FROM public.organization_addon_subscriptions oas
  JOIN public.addon_products ap ON ap.id = oas.product_id
  WHERE oas.workspace_id = ws_id
    AND ap.product_key IN ('docubox_colabora', 'docubox_colabora_pro')
  ORDER BY
    CASE oas.status WHEN 'active' THEN 1 WHEN 'trialing' THEN 2 WHEN 'past_due' THEN 3 ELSE 4 END,
    CASE ap.product_key WHEN 'docubox_colabora_pro' THEN 1 ELSE 2 END
  LIMIT 1;
  IF v_subscription.id IS NOT NULL THEN
    SELECT product_key INTO v_product_key
    FROM public.addon_products
    WHERE id = v_subscription.product_id;
  END IF;

  SELECT COALESCE(jsonb_object_agg(entitlement_key, jsonb_build_object(
    'status', status,
    'limits', limits,
    'ends_at', ends_at,
    'read_only_at', read_only_at,
    'access_level', access_level
  )), '{}'::JSONB)
  INTO v_entitlements
  FROM public.organization_entitlements
  WHERE workspace_id = ws_id;

  SELECT COALESCE(jsonb_agg(permission_key), '[]'::JSONB)
  INTO v_permissions
  FROM public.get_my_organization_permissions(ws_id);

  v_write_allowed := public.has_collaboration_entitlement(ws_id, 'collaboration_core', TRUE);
  v_tier := CASE
    WHEN public.has_collaboration_entitlement(ws_id, 'collaboration_advanced_workflows', TRUE) THEN 'pro'
    WHEN public.has_collaboration_entitlement(ws_id, 'collaboration_core', FALSE) THEN 'standard'
    ELSE 'none'
  END;

  RETURN jsonb_build_object(
    'eligible', v_workspace.workspace_type = 'business' AND COALESCE(v_workspace.organization_enabled, TRUE),
    'accessible', public.has_collaboration_entitlement(ws_id, 'collaboration_core', FALSE),
    'write_allowed', v_write_allowed,
    'workspace_status', CASE WHEN COALESCE(v_workspace.organization_enabled, TRUE) THEN 'active' ELSE 'suspended' END,
    'membership_status', v_membership.status,
    'membership_role', v_membership.role,
    'subscription_status', COALESCE(v_subscription.status, 'available'),
    'trial_ends_at', v_subscription.trial_ends_at,
    'current_period_end', v_subscription.current_period_end,
    'product_key', v_product_key,
    'commercial_tier', v_tier,
    'can_manage_subscription', public.has_organization_permission(ws_id, 'subscription.manage_addons'),
    'entitlements', v_entitlements,
    'permissions', v_permissions,
    'code', CASE
      WHEN v_workspace.workspace_type <> 'business' THEN 'ORGANIZATION_REQUIRED'
      WHEN v_membership.status <> 'active' THEN 'MEMBERSHIP_INACTIVE'
      WHEN NOT public.has_collaboration_entitlement(ws_id, 'collaboration_core', FALSE) THEN 'ADDON_REQUIRED'
      WHEN NOT v_write_allowed THEN 'READ_ONLY'
      ELSE 'OK'
    END
  );
END;
$function$
;

-- [FUNCTION] public.get_my_organization_permissions(ws_id uuid)
CREATE OR REPLACE FUNCTION public.get_my_organization_permissions(ws_id uuid)
 RETURNS TABLE(permission_key text)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
  SELECT op.permission_key
  FROM public.organization_permissions op
  WHERE public.has_organization_permission(ws_id, op.permission_key)
  ORDER BY op.permission_key;
$function$
;

-- [FUNCTION] public.get_next_participants_to_notify(p_documento_id uuid)
CREATE OR REPLACE FUNCTION public.get_next_participants_to_notify(p_documento_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE
  v_doc RECORD;
  v_participation_order TEXT;
  v_participantes JSONB;
  v_grupos JSONB;
  v_result JSONB := '[]'::JSONB;
  v_participant JSONB;
  v_grupo JSONB;
  v_grupo_participantes JSONB;
  v_grupo_tipo TEXT;
  v_all_terminal BOOLEAN;
  v_terminal_states TEXT[] := ARRAY['firmo','firmado','aprobo','aprobado','rechazo','rechazado','cancelo','cancelado'];
  v_active_states TEXT[] := ARRAY['sin_revisar','en_revision','en_participando','notificado'];
  v_participant_sub TEXT;
  v_participant_email TEXT;
  v_participant_id TEXT;
  v_found_active_group BOOLEAN := FALSE;
BEGIN
  -- Obtener documento
  SELECT participation_order, participantes, grupos_firma
  INTO v_participation_order, v_participantes, v_grupos
  FROM public.documentos
  WHERE id = p_documento_id;

  IF v_participantes IS NULL THEN
    RETURN '[]'::JSONB;
  END IF;

  -- PARALELO: todos los participantes son elegibles
  IF v_participation_order = 'paralelo' OR v_participation_order IS NULL THEN
    SELECT jsonb_agg(p)
    INTO v_result
    FROM jsonb_array_elements(v_participantes) AS p
    WHERE NOT (p->>'isCurrentUser')::BOOLEAN IS TRUE
      AND NOT (p->>'sub_estado' = ANY(v_terminal_states));
    RETURN COALESCE(v_result, '[]'::JSONB);
  END IF;

  -- SECUENCIAL: encontrar el primer participante sin estado terminal
  IF v_participation_order = 'secuencial' THEN
    FOR v_participant IN SELECT * FROM jsonb_array_elements(v_participantes)
    LOOP
      v_participant_sub := COALESCE(v_participant->>'sub_estado', 'sin_revisar');
      -- Saltar al dueño del documento
      IF (v_participant->>'isCurrentUser')::BOOLEAN IS TRUE THEN
        CONTINUE;
      END IF;
      -- Si este participante no ha terminado, es el siguiente
      IF NOT (v_participant_sub = ANY(v_terminal_states)) THEN
        v_result := jsonb_build_array(v_participant);
        RETURN v_result;
      END IF;
    END LOOP;
    RETURN '[]'::JSONB;
  END IF;

  -- MIXTO: procesar grupos en orden
  IF v_participation_order = 'mixto' AND v_grupos IS NOT NULL THEN
    FOR v_grupo IN SELECT * FROM jsonb_array_elements(v_grupos)
    LOOP
      v_grupo_tipo := COALESCE(v_grupo->>'tipo', 'paralelo');
      v_grupo_participantes := COALESCE(v_grupo->'participantIds', '[]'::JSONB);

      -- Verificar si este grupo ya completó (todos en estado terminal)
      v_all_terminal := TRUE;
      FOR v_participant_id IN SELECT jsonb_array_elements_text(v_grupo_participantes)
      LOOP
        -- Buscar el participante en el array de participantes
        SELECT p->>'sub_estado'
        INTO v_participant_sub
        FROM jsonb_array_elements(v_participantes) AS p
        WHERE p->>'id' = v_participant_id
        LIMIT 1;

        IF v_participant_sub IS NULL OR NOT (COALESCE(v_participant_sub, 'sin_revisar') = ANY(v_terminal_states)) THEN
          v_all_terminal := FALSE;
          EXIT;
        END IF;
      END LOOP;

      -- Si el grupo no completó, este es el grupo activo
      IF NOT v_all_terminal THEN
        v_found_active_group := TRUE;

        IF v_grupo_tipo = 'paralelo' THEN
          -- Retornar todos los participantes del grupo que no han terminado
          SELECT jsonb_agg(p)
          INTO v_result
          FROM jsonb_array_elements(v_participantes) AS p
          WHERE p->>'id' = ANY(
            SELECT jsonb_array_elements_text(v_grupo_participantes)
          )
          AND NOT (COALESCE(p->>'sub_estado', 'sin_revisar') = ANY(v_terminal_states))
          AND NOT (p->>'isCurrentUser')::BOOLEAN IS TRUE;
          RETURN COALESCE(v_result, '[]'::JSONB);

        ELSIF v_grupo_tipo = 'secuencial' THEN
          -- Retornar el primer participante del grupo que no ha terminado
          FOR v_participant_id IN SELECT jsonb_array_elements_text(v_grupo_participantes)
          LOOP
            SELECT p
            INTO v_participant
            FROM jsonb_array_elements(v_participantes) AS p
            WHERE p->>'id' = v_participant_id
            LIMIT 1;

            IF v_participant IS NOT NULL THEN
              v_participant_sub := COALESCE(v_participant->>'sub_estado', 'sin_revisar');
              IF NOT (v_participant_sub = ANY(v_terminal_states))
                AND NOT (v_participant->>'isCurrentUser')::BOOLEAN IS TRUE THEN
                RETURN jsonb_build_array(v_participant);
              END IF;
            END IF;
          END LOOP;
          RETURN '[]'::JSONB;
        END IF;

        EXIT; -- Salir del loop de grupos una vez encontrado el grupo activo
      END IF;
    END LOOP;

    RETURN '[]'::JSONB;
  END IF;

  -- Fallback: retornar todos
  SELECT jsonb_agg(p)
  INTO v_result
  FROM jsonb_array_elements(v_participantes) AS p
  WHERE NOT (p->>'isCurrentUser')::BOOLEAN IS TRUE;
  RETURN COALESCE(v_result, '[]'::JSONB);
END;
$function$
;

-- [FUNCTION] public.get_organization_crypto_overview(ws_id uuid)
CREATE OR REPLACE FUNCTION public.get_organization_crypto_overview(ws_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE
  result JSONB;
BEGIN
  IF NOT public.has_organization_permission(ws_id, 'certificates.read') THEN
    RAISE EXCEPTION 'organization_permission_denied' USING ERRCODE = '42501';
  END IF;

  SELECT jsonb_build_object(
    'certificate_count', (SELECT count(*) FROM public.organization_certificates oc WHERE oc.workspace_id = ws_id),
    'valid_certificates', (SELECT count(*) FROM public.organization_certificates oc WHERE oc.workspace_id = ws_id AND oc.status = 'valid'),
    'expiring_certificates', (SELECT count(*) FROM public.organization_certificates oc WHERE oc.workspace_id = ws_id AND (oc.status = 'expiring' OR oc.valid_until BETWEEN CURRENT_TIMESTAMP AND CURRENT_TIMESTAMP + INTERVAL '45 days')),
    'certifications_completed', (SELECT count(*) FROM public.document_certifications dc WHERE dc.workspace_id = ws_id AND dc.status = 'COMPLETED'),
    'certifications_failed', (SELECT count(*) FROM public.document_certifications dc WHERE dc.workspace_id = ws_id AND dc.status = 'FAILED'),
    'last_certification_at', (SELECT max(dc.completed_at) FROM public.document_certifications dc WHERE dc.workspace_id = ws_id AND dc.status = 'COMPLETED')
  ) INTO result;

  RETURN result;
END;
$function$
;

-- [FUNCTION] public.get_organization_directory_person(ws_id uuid, target_person_id uuid)
CREATE OR REPLACE FUNCTION public.get_organization_directory_person(ws_id uuid, target_person_id uuid)
 RETURNS TABLE(id uuid, workspace_id uuid, member_id uuid, full_name text, email text, phone text, rfc text, relationship_type text, person_type text, job_title text, area_name text, identity_status text, status text, valid_from date, valid_until date, data_version integer, metadata jsonb, sensitive_identifiers jsonb, created_at timestamp with time zone, updated_at timestamp with time zone)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE
  can_read_sensitive BOOLEAN;
BEGIN
  IF NOT public.has_organization_permission(ws_id, 'directory.read') THEN
    RAISE EXCEPTION 'organization_permission_denied' USING ERRCODE = '42501';
  END IF;
  can_read_sensitive := public.has_organization_permission(ws_id, 'directory.sensitive.read');
  RETURN QUERY
  SELECT person.id, person.workspace_id, person.member_id, person.full_name, person.email, person.phone,
    CASE WHEN can_read_sensitive THEN person.rfc ELSE NULL END,
    person.relationship_type, person.person_type, person.job_title, person.area_name, person.identity_status,
    person.status, person.valid_from, person.valid_until, person.data_version, person.metadata,
    CASE WHEN can_read_sensitive THEN person.sensitive_identifiers ELSE '{}'::jsonb END,
    person.created_at, person.updated_at
  FROM public.organization_directory_people person
  WHERE person.workspace_id = ws_id AND person.id = target_person_id;
END;
$function$
;

-- [FUNCTION] public.get_organization_member_offboarding_preview(ws_id uuid, target_member_id uuid)
CREATE OR REPLACE FUNCTION public.get_organization_member_offboarding_preview(ws_id uuid, target_member_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE
  target_member public.workspace_members%ROWTYPE;
  target_profile public.user_profiles%ROWTYPE;
  result JSONB;
BEGIN
  IF NOT public.has_organization_permission(ws_id, 'members.offboard') THEN
    RAISE EXCEPTION 'organization_permission_denied' USING ERRCODE = '42501';
  END IF;

  SELECT * INTO target_member
  FROM public.workspace_members
  WHERE id = target_member_id AND workspace_id = ws_id;

  IF target_member.id IS NULL THEN
    RAISE EXCEPTION 'organization_member_not_found' USING ERRCODE = 'P0002';
  END IF;

  SELECT * INTO target_profile FROM public.user_profiles WHERE id = target_member.user_id;

  SELECT jsonb_build_object(
    'member', jsonb_build_object(
      'id', target_member.id,
      'user_id', target_member.user_id,
      'role', target_member.role,
      'status', target_member.status,
      'full_name', COALESCE(target_profile.full_name, target_profile.email, 'Usuario'),
      'email', target_profile.email
    ),
    'assets', jsonb_build_object(
      'documents', (SELECT count(*) FROM public.documentos d WHERE d.workspace_id = ws_id AND d.owner_id = target_member.user_id),
      'case_files', (SELECT count(*) FROM public.case_files cf WHERE cf.workspace_id = ws_id AND cf.owner_user_id = target_member.user_id),
      'tasks', (SELECT count(*) FROM public.tareas t WHERE t.workspace_id = ws_id AND t.assigned_to = target_member.user_id),
      'shared_resources_owned', (SELECT count(*) FROM public.organization_shared_resources r WHERE r.workspace_id = ws_id AND r.owner_user_id = target_member.user_id),
      'shared_resources_custodied', (SELECT count(*) FROM public.organization_shared_resources r WHERE r.workspace_id = ws_id AND r.custodian_user_id = target_member.user_id),
      'teams_led', (SELECT count(*) FROM public.organization_units u WHERE u.workspace_id = ws_id AND u.leader_member_id = target_member.id),
      'cost_centers', (SELECT count(*) FROM public.organization_cost_centers c WHERE c.workspace_id = ws_id AND c.owner_member_id = target_member.id),
      'certificate_permissions', (SELECT count(*) FROM public.organization_certificate_permissions cp WHERE cp.workspace_id = ws_id AND cp.member_id = target_member.id),
      'active_authorities', (SELECT count(*) FROM public.organization_authorities a WHERE a.workspace_id = ws_id AND a.member_id = target_member.id AND a.status IN ('active', 'pending_validation'))
    ),
    'access', jsonb_build_object(
      'active_sessions', (
        SELECT count(*) FROM public.user_sessions s
        WHERE s.user_id = target_member.user_id
          AND (s.expires_at IS NULL OR s.expires_at > CURRENT_TIMESTAMP)
          AND s.session_token NOT LIKE 'revoked:%'
      ),
      'active_api_credentials', (
        SELECT count(*) FROM public.organization_api_credentials c
        WHERE c.workspace_id = ws_id AND c.created_by = target_member.user_id AND c.status = 'active'
      ),
      'pending_invitations', (
        SELECT count(*) FROM public.organization_invitations i
        WHERE i.workspace_id = ws_id AND lower(i.email) = lower(target_profile.email) AND i.status = 'pending'
      ),
      'global_authenticator_note', 'Los autenticadores personales se conservan porque pueden proteger otros espacios. El acceso a esta organización queda bloqueado por la membresía.'
    )
  ) INTO result;

  RETURN result;
END;
$function$
;

-- [FUNCTION] public.get_organization_resource_candidates(ws_id uuid)
CREATE OR REPLACE FUNCTION public.get_organization_resource_candidates(ws_id uuid)
 RETURNS TABLE(resource_type text, source_id uuid, name text, status text, updated_at timestamp with time zone)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
BEGIN
  IF NOT public.has_organization_permission(ws_id, 'resources.manage') THEN
    RAISE EXCEPTION 'organization_permission_denied' USING ERRCODE = '42501';
  END IF;
  RETURN QUERY
  SELECT 'document_template'::TEXT, template.id, template.name, template.status, template.updated_at
  FROM public.plantillas template
  WHERE template.workspace_id = ws_id
    AND NOT EXISTS (SELECT 1 FROM public.organization_shared_resources resource WHERE resource.document_template_id = template.id)
  UNION ALL
  SELECT 'form'::TEXT, form.id, form.name, form.status, form.updated_at
  FROM public.form_templates form
  WHERE form.workspace_id = ws_id
    AND NOT EXISTS (SELECT 1 FROM public.organization_shared_resources resource WHERE resource.form_template_id = form.id)
  ORDER BY 5 DESC;
END;
$function$
;

-- [FUNCTION] public.get_organization_resource_catalog(ws_id uuid)
CREATE OR REPLACE FUNCTION public.get_organization_resource_catalog(ws_id uuid)
 RETURNS TABLE(id uuid, resource_type text, source_id uuid, name text, description text, visibility text, version integer, status text, locked boolean, workflow_name text, policy_name text, updated_at timestamp with time zone)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
BEGIN
  IF NOT public.has_organization_permission(ws_id, 'resources.read') THEN
    RAISE EXCEPTION 'organization_permission_denied' USING ERRCODE = '42501';
  END IF;
  RETURN QUERY
  SELECT resource.id, resource.resource_type,
    COALESCE(resource.document_template_id, resource.form_template_id), resource.name, resource.description,
    resource.visibility, resource.version, resource.status, resource.locked,
    workflow.name, policy.name, resource.updated_at
  FROM public.organization_shared_resources resource
  LEFT JOIN public.organization_approval_workflows workflow ON workflow.id = resource.workflow_id
  LEFT JOIN public.organization_signature_policies policy ON policy.id = resource.signature_policy_id
  WHERE resource.workspace_id = ws_id
  ORDER BY resource.updated_at DESC;
END;
$function$
;

-- [FUNCTION] public.get_organization_security_sessions(ws_id uuid)
CREATE OR REPLACE FUNCTION public.get_organization_security_sessions(ws_id uuid)
 RETURNS TABLE(session_id uuid, member_id uuid, user_id uuid, full_name text, email text, device_name text, device_type text, browser text, os text, ip_address text, location text, is_current boolean, last_active_at timestamp with time zone, created_at timestamp with time zone, expires_at timestamp with time zone, risk_level text)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
BEGIN
  IF NOT public.has_organization_permission(ws_id, 'security.read') THEN
    RAISE EXCEPTION 'organization_permission_denied' USING ERRCODE = '42501';
  END IF;

  RETURN QUERY
  SELECT
    us.id,
    wm.id,
    wm.user_id,
    COALESCE(up.full_name, up.email, 'Usuario'),
    up.email,
    us.device_name,
    us.device_type,
    us.browser,
    us.os,
    us.ip_address,
    us.location,
    us.is_current,
    us.last_active_at,
    us.created_at,
    us.expires_at,
    CASE
      WHEN us.expires_at IS NOT NULL AND us.expires_at <= CURRENT_TIMESTAMP THEN 'expired'
      WHEN us.last_active_at < CURRENT_TIMESTAMP - INTERVAL '30 days' THEN 'stale'
      ELSE 'normal'
    END
  FROM public.workspace_members wm
  JOIN public.user_profiles up ON up.id = wm.user_id
  JOIN public.user_sessions us ON us.user_id = wm.user_id
  WHERE wm.workspace_id = ws_id
    AND wm.status = 'active'
  ORDER BY us.last_active_at DESC NULLS LAST;
END;
$function$
;

-- [FUNCTION] public.get_security_audit_summary(p_workspace_id uuid, p_days integer)
CREATE OR REPLACE FUNCTION public.get_security_audit_summary(p_workspace_id uuid, p_days integer DEFAULT 30)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE
  v_result JSONB;
BEGIN
  SELECT jsonb_build_object(
    'workspace_id',     p_workspace_id,
    'period_days',      p_days,
    'total_events',     COUNT(*),
    'success_events',   COUNT(*) FILTER (WHERE outcome = 'success'),
    'failure_events',   COUNT(*) FILTER (WHERE outcome = 'failure'),
    'blocked_events',   COUNT(*) FILTER (WHERE outcome = 'blocked'),
    'legal_events',     COUNT(*) FILTER (WHERE is_legal_event = TRUE),
    'by_category',      jsonb_object_agg(category, cat_count),
    'generated_at',     now()
  )
  INTO v_result
  FROM (
    SELECT
      outcome,
      is_legal_event,
      category,
      COUNT(*) OVER (PARTITION BY category) AS cat_count
    FROM public.security_audit_chain
    WHERE workspace_id = p_workspace_id
      AND created_at >= now() - (p_days || ' days')::INTERVAL
  ) sub;

  RETURN COALESCE(v_result, '{}'::JSONB);
END;
$function$
;

