-- [FUNCTION] public.handle_new_user()
CREATE OR REPLACE FUNCTION public.handle_new_user()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
BEGIN
    INSERT INTO public.user_profiles (id, email, full_name, avatar_url, phone)
    VALUES (
        NEW.id,
        NEW.email,
        COALESCE(NEW.raw_user_meta_data->>'full_name', ''),
        COALESCE(NEW.raw_user_meta_data->>'avatar_url', NULL),
        COALESCE(NEW.raw_user_meta_data->>'phone', NULL)
    )
    ON CONFLICT (id) DO UPDATE
        SET email      = EXCLUDED.email,
            full_name  = COALESCE(EXCLUDED.full_name, public.user_profiles.full_name),
            phone      = COALESCE(EXCLUDED.phone, public.user_profiles.phone),
            updated_at = CURRENT_TIMESTAMP;
    RETURN NEW;
END;
$function$
;

-- [FUNCTION] public.has_collaboration_entitlement(ws_id uuid, requested_entitlement text, require_write boolean)
CREATE OR REPLACE FUNCTION public.has_collaboration_entitlement(ws_id uuid, requested_entitlement text DEFAULT 'collaboration_core'::text, require_write boolean DEFAULT false)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
  SELECT EXISTS (
    SELECT 1
    FROM public.workspaces w
    JOIN public.workspace_members wm
      ON wm.workspace_id = w.id
     AND wm.user_id = auth.uid()
     AND wm.status = 'active'
    JOIN public.organization_entitlements oe
      ON oe.workspace_id = w.id
     AND oe.entitlement_key = requested_entitlement
    WHERE w.id = ws_id
      AND w.workspace_type = 'business'
      AND COALESCE(w.organization_enabled, TRUE)
      AND oe.status IN ('trialing','active','past_due','suspended','cancelled','expired')
      AND (oe.starts_at IS NULL OR oe.starts_at <= CURRENT_TIMESTAMP)
      AND (
        NOT require_write
        OR (
          oe.status IN ('trialing','active','past_due')
          AND oe.read_only_at IS NULL
          AND (oe.ends_at IS NULL OR oe.ends_at > CURRENT_TIMESTAMP)
        )
      )
  );
$function$
;

-- [FUNCTION] public.has_organization_permission(ws_id uuid, requested_permission text)
CREATE OR REPLACE FUNCTION public.has_organization_permission(ws_id uuid, requested_permission text)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
  SELECT EXISTS (
    SELECT 1
    FROM public.workspace_members wm
    WHERE wm.workspace_id = ws_id
      AND wm.user_id = auth.uid()
      AND wm.status = 'active'
      AND (wm.access_expires_at IS NULL OR wm.access_expires_at > CURRENT_TIMESTAMP)
      AND (
        wm.role = 'owner'
        OR (wm.role = 'admin' AND requested_permission <> 'organization.transfer_ownership')
        OR EXISTS (
          SELECT 1
          FROM public.organization_member_roles omr
          JOIN public.organization_role_permissions orp ON orp.role_id = omr.role_id
          JOIN public.organization_permissions op ON op.id = orp.permission_id
          WHERE omr.member_id = wm.id
            AND omr.workspace_id = ws_id
            AND op.permission_key = requested_permission
        )
      )
  );
$function$
;

