-- [FUNCTION] public.incorporate_collaboration_request_file(p_file_id uuid, p_workspace_id uuid, p_actor_id uuid)
CREATE OR REPLACE FUNCTION public.incorporate_collaboration_request_file(p_file_id uuid, p_workspace_id uuid, p_actor_id uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE
  v_file public.collaboration_request_files%ROWTYPE;
  v_item public.collaboration_request_items%ROWTYPE;
  v_request public.collaboration_document_requests%ROWTYPE;
  v_document_id UUID;
  v_folio TEXT;
BEGIN
  SELECT * INTO v_file
  FROM public.collaboration_request_files
  WHERE id = p_file_id AND workspace_id = p_workspace_id
  FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'request_file_not_found' USING ERRCODE = 'P0002'; END IF;
  IF v_file.canonical_document_id IS NOT NULL THEN RETURN v_file.canonical_document_id; END IF;
  IF v_file.malware_scan_status <> 'clean' THEN
    RAISE EXCEPTION 'request_file_security_scan_required' USING ERRCODE = '55000';
  END IF;

  SELECT * INTO STRICT v_item
  FROM public.collaboration_request_items
  WHERE id = v_file.request_item_id AND workspace_id = p_workspace_id;
  SELECT * INTO STRICT v_request
  FROM public.collaboration_document_requests
  WHERE id = v_item.request_id AND workspace_id = p_workspace_id;

  v_folio := 'DOC-' || to_char(CURRENT_DATE, 'YYYY') || '-' ||
    upper(substr(replace(gen_random_uuid()::TEXT, '-', ''), 1, 8));
  INSERT INTO public.documentos(
    documento_id, owner_id, workspace_id, file_name, file_size, file_type,
    file_hash_sha256, file_url, nombre, descripcion, ruta_guardado,
    estado, es_publico
  ) VALUES (
    v_folio,
    COALESCE(v_request.created_by, p_actor_id),
    p_workspace_id,
    v_file.original_name,
    v_file.byte_size,
    v_file.mime_type,
    v_file.sha256,
    v_file.storage_path,
    v_item.title,
    COALESCE(v_item.description, 'Documento recibido mediante Docubox Colabora.'),
    'raiz',
    'borrador',
    FALSE
  ) RETURNING id INTO v_document_id;

  UPDATE public.collaboration_request_files
  SET canonical_document_id = v_document_id,
      incorporated_at = CURRENT_TIMESTAMP,
      incorporated_by = p_actor_id,
      metadata = metadata || jsonb_build_object(
        'incorporation', jsonb_build_object(
          'document_id', v_document_id,
          'document_folio', v_folio,
          'incorporated_at', CURRENT_TIMESTAMP
        )
      )
  WHERE id = p_file_id;
  RETURN v_document_id;
END;
$function$
;

-- [FUNCTION] public.init_user_verification_status()
CREATE OR REPLACE FUNCTION public.init_user_verification_status()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE
  v_enrollment_result_id UUID;
  v_biometric_verified   BOOLEAN := false;
  v_biometric_source     TEXT := NULL;
  v_biometric_at         TIMESTAMPTZ := NULL;
BEGIN
  -- Check if user completed biometric enrollment
  IF NEW.identity_method = 'biometric' THEN
    SELECT id INTO v_enrollment_result_id
    FROM public.enrollment_results
    WHERE user_id = NEW.id
      AND face_match_passed = true
    ORDER BY created_at DESC
    LIMIT 1;

    IF v_enrollment_result_id IS NOT NULL THEN
      v_biometric_verified := true;
      v_biometric_source   := 'enrollment';
      v_biometric_at       := CURRENT_TIMESTAMP;
    END IF;
  END IF;

  INSERT INTO public.user_verification_status (
    user_id,
    email_verified,
    biometric_verified,
    biometric_verified_at,
    biometric_source,
    enrollment_result_id
  ) VALUES (
    NEW.id,
    false,
    v_biometric_verified,
    v_biometric_at,
    v_biometric_source,
    v_enrollment_result_id
  )
  ON CONFLICT (user_id) DO NOTHING;

  RETURN NEW;
END;
$function$
;

