-- [FUNCTION] public.insert_audit_event(p_user_id uuid, p_session_id uuid, p_workspace_id uuid, p_acting_role text, p_ip inet, p_user_agent text, p_country_code character, p_city text, p_event_type text, p_resource_type text, p_resource_id uuid, p_payload jsonb, p_outcome text, p_server_sig text)
CREATE OR REPLACE FUNCTION public.insert_audit_event(p_user_id uuid, p_session_id uuid, p_workspace_id uuid, p_acting_role text, p_ip inet, p_user_agent text, p_country_code character, p_city text, p_event_type text, p_resource_type text, p_resource_id uuid, p_payload jsonb, p_outcome text, p_server_sig text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE
  v_prev_hash   TEXT;
  v_occurred    TIMESTAMPTZ;
  v_canonical   JSONB;
  v_event_hash  TEXT;
  v_event_id    UUID;
BEGIN
  -- Obtener el hash del último evento (con bloqueo para evitar race conditions)
  SELECT event_hash INTO v_prev_hash
  FROM public.audit_log
  ORDER BY event_seq DESC
  LIMIT 1
  FOR UPDATE SKIP LOCKED;

  -- Si no hay eventos previos, usar el hash génesis
  IF v_prev_hash IS NULL THEN
    v_prev_hash := encode(digest('DOCUBOX_GENESIS', 'sha256'), 'hex');
  END IF;

  v_occurred := NOW();

  -- Construir el objeto canónico en orden fijo para el hash
  v_canonical := json_build_object(
    'occurred_at',    v_occurred::TEXT,
    'user_id',        COALESCE(p_user_id::TEXT, ''),
    'workspace_id',   COALESCE(p_workspace_id::TEXT, ''),
    'ip_address',     p_ip::TEXT,
    'event_type',     p_event_type::TEXT,
    'resource_type',  COALESCE(p_resource_type::TEXT, ''),
    'resource_id',    COALESCE(p_resource_id::TEXT, ''),
    'outcome',        p_outcome::TEXT,
    'prev_hash',      v_prev_hash::TEXT
  );

  v_event_hash := encode(digest(v_canonical::text, 'sha256'), 'hex');

  INSERT INTO public.audit_log (
    occurred_at, user_id, session_id, workspace_id, acting_as_role,
    ip_address, user_agent, country_code, city,
    event_type, resource_type, resource_id, event_payload,
    outcome, prev_hash, event_hash, server_sig
  ) VALUES (
    v_occurred, p_user_id, p_session_id, p_workspace_id, p_acting_role,
    p_ip, p_user_agent, p_country_code, p_city,
    p_event_type, p_resource_type, p_resource_id, COALESCE(p_payload, '{}'::jsonb),
    p_outcome, v_prev_hash, v_event_hash, p_server_sig
  )
  RETURNING event_id INTO v_event_id;

  RETURN v_event_id;
END;
$function$
;

