-- [FUNCTION] public.kms_alert_vault_admin(p_workspace_id uuid, p_subject text, p_body text, p_alert_type text)
CREATE OR REPLACE FUNCTION public.kms_alert_vault_admin(p_workspace_id uuid, p_subject text, p_body text, p_alert_type text DEFAULT 'key_rotation_alert'::text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE
  v_admin_email TEXT;
  v_supabase_url TEXT;
  v_service_key  TEXT;
  v_payload      JSONB;
BEGIN
  -- Obtener email del vault_admin del workspace
  SELECT u.email INTO v_admin_email
  FROM public.workspace_members wm
  JOIN auth.users u ON u.id = wm.user_id
  WHERE wm.workspace_id = p_workspace_id
    AND wm.role::TEXT IN ('vault_admin', 'owner', 'admin')
  ORDER BY
    CASE wm.role::TEXT
      WHEN 'vault_admin' THEN 1
      WHEN 'owner'       THEN 2
      WHEN 'admin'       THEN 3
    END
  LIMIT 1;

  IF v_admin_email IS NULL THEN
    RAISE WARNING '[KMS] No vault_admin found for workspace %. Alert not sent.', p_workspace_id;
    RETURN;
  END IF;

  -- Construir payload para send-email-notifications
  v_payload := jsonb_build_object(
    'type',          p_alert_type,
    'to',            v_admin_email,
    'recipientName', 'Vault Administrator',
    'actionDescription', p_body,
    'documentName',  p_subject
  );

  -- Obtener URL del proyecto Supabase desde configuración
  v_supabase_url := current_setting('app.supabase_url', true);
  v_service_key  := current_setting('app.service_role_key', true);

  IF v_supabase_url IS NULL OR v_service_key IS NULL THEN
    -- Fallback: registrar en audit chain sin enviar email
    RAISE WARNING '[KMS] app.supabase_url or app.service_role_key not set. Email alert skipped. Subject: %', p_subject;
    RETURN;
  END IF;

  -- Llamada HTTP asíncrona al Edge Function
  PERFORM net.http_post(
    url     := v_supabase_url || '/functions/v1/send-email-notifications',
    headers := jsonb_build_object(
      'Content-Type',  'application/json',
      'Authorization', 'Bearer ' || v_service_key
    ),
    body    := v_payload::TEXT
  );

EXCEPTION WHEN OTHERS THEN
  RAISE WARNING '[KMS] Failed to send vault_admin alert: %', SQLERRM;
END;
$function$
;

-- [FUNCTION] public.kms_get_active_key_version(p_key_name text)
CREATE OR REPLACE FUNCTION public.kms_get_active_key_version(p_key_name text DEFAULT 'docubox-master-kek-v1'::text)
 RETURNS TABLE(key_name text, key_version text, algorithm text)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
  SELECT
    kv.key_name::TEXT,
    kv.id::TEXT,       -- kms_key_versions.id (UUID) used as version token
    kv.algorithm::TEXT
  FROM public.kms_key_versions kv
  WHERE kv.key_name = p_key_name
    AND kv.is_active = true
  LIMIT 1;
$function$
;

-- [FUNCTION] public.kms_revoke_expired_key_versions()
CREATE OR REPLACE FUNCTION public.kms_revoke_expired_key_versions()
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE
  v_revoked_count INT := 0;
  v_rows_affected INT;
  v_rec           RECORD;
  v_dep_count     INT;
  v_workspace_id  UUID;
BEGIN
  -- Revisar versiones en estado 'retired' o cuya grace_period_ends_at ya pasó
  FOR v_rec IN
    SELECT DISTINCT key_version
    FROM public.sensitive_field_key_versions
    WHERE status IN ('retired', 'rotating')
      AND (
        grace_period_ends_at < now()
        OR rewrap_pending_count = 0
      )
  LOOP
    -- Verificar que ninguna clave activa dependa de esta versión
    SELECT COUNT(*) INTO v_dep_count FROM (
      SELECT id FROM public.document_encryption_metadata
        WHERE key_version = v_rec.key_version
      UNION ALL
      SELECT id FROM public.document_participant_deks
        WHERE kek_version = v_rec.key_version AND access_status = 'active'
      UNION ALL
      SELECT id FROM public.efirma_sat_vault
        WHERE kek_version = v_rec.key_version AND vault_status = 'active'
    ) deps;

    IF v_dep_count = 0 THEN
      -- Revocar la versión en sensitive_field_key_versions
      UPDATE public.sensitive_field_key_versions
      SET
        status     = 'revoked',
        revoked_at = now(),
        rewrap_pending_count = 0
      WHERE key_version = v_rec.key_version
        AND status IN ('retired', 'rotating');

      GET DIAGNOSTICS v_rows_affected = ROW_COUNT;
      v_revoked_count := v_revoked_count + v_rows_affected;

      -- Marcar la clave en kms_key_versions como inactiva (ya debería estarlo)
      UPDATE public.kms_key_versions
      SET is_active = false, rotated_at = COALESCE(rotated_at, now())
      WHERE key_name = v_rec.key_version AND is_active = true;

      -- Registrar revocación en security_audit_chain
      INSERT INTO public.security_audit_chain (
        actor_id,
        workspace_id,
        category,
        action,
        resource_type,
        outcome,
        metadata,
        chain_hash,
        previous_hash,
        is_legal_event,
        created_at
      )
      SELECT
        NULL,
        wm.workspace_id,
        'encryption',
        'key.revoked',
        'encryption_key',
        'success',
        jsonb_build_object(
          'key_version',   v_rec.key_version,
          'reason',        'no_active_dependencies',
          'triggered_by',  'pg_cron:kms-revoke-orphan-keys'
        ),
        encode(digest(
          'revoke:' || v_rec.key_version || ':' || now()::TEXT || ':' || wm.workspace_id::TEXT,
          'sha256'
        ), 'hex'),
        COALESCE((
          SELECT chain_hash FROM public.security_audit_chain
          WHERE workspace_id = wm.workspace_id
          ORDER BY created_at DESC LIMIT 1
        ), 'genesis'),
        false,
        now()
      FROM (SELECT DISTINCT workspace_id FROM public.workspace_members) wm
      ON CONFLICT DO NOTHING;

    ELSE
      -- Quedan dependencias pero la ventana de gracia cerró — alerta crítica
      IF (
        SELECT grace_period_ends_at < now()
        FROM public.sensitive_field_key_versions
        WHERE key_version = v_rec.key_version
        LIMIT 1
      ) THEN
        FOR v_workspace_id IN
          SELECT DISTINCT workspace_id FROM public.workspace_members
          WHERE role::TEXT IN ('vault_admin', 'owner')
        LOOP
          PERFORM public.kms_alert_vault_admin(
            v_workspace_id,
            '[CRÍTICO] Ventana de gracia cerrada con claves sin re-envolver',
            'La versión de clave ' || v_rec.key_version ||
            ' tiene ' || v_dep_count || ' claves (DEKs/KEKs) sin re-envolver ' ||
            'y su ventana de gracia ya cerró. ' ||
            'Acción inmediata requerida: ejecutar re-envolvimiento manual o extender la ventana de gracia.',
            'key_rotation_alert'
          );
        END LOOP;
      END IF;
    END IF;
  END LOOP;

  RETURN v_revoked_count;

EXCEPTION WHEN OTHERS THEN
  RAISE WARNING '[KMS] kms_revoke_expired_key_versions failed: %', SQLERRM;
  RETURN -1;
END;
$function$
;

-- [FUNCTION] public.kms_rewrap_deks_batch()
CREATE OR REPLACE FUNCTION public.kms_rewrap_deks_batch()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE
  v_batch_size        INT := 50;
  v_rewrapped_dem     INT := 0;
  v_rewrapped_dpd     INT := 0;
  v_rewrapped_esv     INT := 0;
  v_errors            INT := 0;
  v_old_key_version   TEXT;
  v_new_key_version   TEXT;
  v_old_vault_key_id  UUID;
  v_new_vault_key_id  UUID;
  v_rec               RECORD;
  v_plain_dek         BYTEA;
  v_new_wrapped_dek   TEXT;
  v_result            JSONB;
  v_workspace_id      UUID;
  v_grace_end         TIMESTAMPTZ;
  v_pending_total     INT := 0;
BEGIN
  -- Encontrar versiones en estado 'rotating' dentro de la ventana de gracia
  FOR v_rec IN
    SELECT DISTINCT
      sfkv.key_version AS old_version,
      sfkv.grace_period_ends_at,
      sfkv.rewrap_batch_size,
      kv_old.vault_key_id AS old_vault_key_id,
      kv_new.key_name AS new_version,
      kv_new.vault_key_id AS new_vault_key_id
    FROM public.sensitive_field_key_versions sfkv
    JOIN public.kms_key_versions kv_old
      ON kv_old.key_name = sfkv.key_version
    -- Obtener la versión activa más reciente
    JOIN public.kms_key_versions kv_new
      ON kv_new.is_active = true
      AND kv_new.key_name LIKE 'docubox-master-kek-v%'
    WHERE sfkv.status = 'rotating'
      AND sfkv.grace_period_ends_at > now()
      AND sfkv.key_version != kv_new.key_name
    LIMIT 1
  LOOP
    v_old_key_version  := v_rec.old_version;
    v_new_key_version  := v_rec.new_version;
    v_old_vault_key_id := v_rec.old_vault_key_id;
    v_new_vault_key_id := v_rec.new_vault_key_id;
    v_batch_size       := COALESCE(v_rec.rewrap_batch_size, 50);
    v_grace_end        := v_rec.grace_period_ends_at;

    -- ── 4a. Re-envolver document_encryption_metadata ──────────────────────
    FOR v_rec IN
      SELECT id, encrypted_dek, tenant_id
      FROM public.document_encryption_metadata
      WHERE key_version = v_old_key_version
      LIMIT v_batch_size
    LOOP
      BEGIN
        -- Desenvolver DEK con clave antigua
        v_plain_dek := public.kms_unwrap_key(v_rec.encrypted_dek, v_old_key_version);
        -- Re-envolver con clave nueva
        v_new_wrapped_dek := public.kms_wrap_key(v_plain_dek, v_new_key_version);

        UPDATE public.document_encryption_metadata
        SET
          encrypted_dek = v_new_wrapped_dek,
          key_version   = v_new_key_version
        WHERE id = v_rec.id;

        v_rewrapped_dem := v_rewrapped_dem + 1;
      EXCEPTION WHEN OTHERS THEN
        v_errors := v_errors + 1;
        RAISE WARNING '[KMS] Failed to rewrap document_encryption_metadata id=%: %', v_rec.id, SQLERRM;
      END;
    END LOOP;

    -- ── 4b. Re-envolver document_participant_deks ──────────────────────────
    FOR v_rec IN
      SELECT id, wrapped_dek, workspace_id
      FROM public.document_participant_deks
      WHERE kek_version = v_old_key_version
        AND access_status = 'active'
      LIMIT v_batch_size
    LOOP
      BEGIN
        v_plain_dek := public.kms_unwrap_key(v_rec.wrapped_dek, v_old_key_version);
        v_new_wrapped_dek := public.kms_wrap_key(v_plain_dek, v_new_key_version);

        UPDATE public.document_participant_deks
        SET
          wrapped_dek  = v_new_wrapped_dek,
          kek_version  = v_new_key_version
        WHERE id = v_rec.id;

        v_rewrapped_dpd := v_rewrapped_dpd + 1;
      EXCEPTION WHEN OTHERS THEN
        v_errors := v_errors + 1;
        RAISE WARNING '[KMS] Failed to rewrap document_participant_deks id=%: %', v_rec.id, SQLERRM;
      END;
    END LOOP;

    -- ── 4c. Re-envolver efirma_sat_vault ──────────────────────────────────
    -- Nota: efirma_sat_vault almacena el PATH del .key cifrado en Storage,
    -- no el .key directamente. El campo kek_version indica qué KEK se usó.
    -- Aquí actualizamos el registro de versión; el re-cifrado real del .key
    -- en Storage debe hacerse desde el microservicio FastAPI.
    -- Solo marcamos para re-cifrado pendiente si la versión coincide.
    UPDATE public.efirma_sat_vault
    SET kek_version = v_new_key_version || ':rewrap_pending'
    WHERE kek_version = v_old_key_version
      AND vault_status = 'active'
      AND id IN (
        SELECT id FROM public.efirma_sat_vault
        WHERE kek_version = v_old_key_version
          AND vault_status = 'active'
        LIMIT v_batch_size
      );

    GET DIAGNOSTICS v_rewrapped_esv = ROW_COUNT;

    -- ── 4d. Actualizar contador de pendientes ──────────────────────────────
    SELECT COUNT(*) INTO v_pending_total FROM (
      SELECT id FROM public.document_encryption_metadata
        WHERE key_version = v_old_key_version
      UNION ALL
      SELECT id FROM public.document_participant_deks
        WHERE kek_version = v_old_key_version AND access_status = 'active'
      UNION ALL
      SELECT id FROM public.efirma_sat_vault
        WHERE kek_version = v_old_key_version AND vault_status = 'active'
    ) remaining;

    UPDATE public.sensitive_field_key_versions
    SET rewrap_pending_count = v_pending_total
    WHERE key_version = v_old_key_version
      AND status = 'rotating';

    -- Si no quedan pendientes, marcar re-envolvimiento como completado
    IF v_pending_total = 0 THEN
      UPDATE public.sensitive_field_key_versions
      SET
        status              = 'retired',
        rewrap_completed_at = now(),
        rewrap_pending_count = 0
      WHERE key_version = v_old_key_version
        AND status = 'rotating';
    END IF;

    -- ── 4e. Alerta si la ventana de gracia está por cerrarse y quedan pendientes
    IF v_pending_total > 0 AND v_grace_end < now() + INTERVAL '7 days' THEN
      FOR v_workspace_id IN
        SELECT DISTINCT workspace_id FROM public.workspace_members
        WHERE role::TEXT IN ('vault_admin', 'owner')
      LOOP
        PERFORM public.kms_alert_vault_admin(
          v_workspace_id,
          '[ALERTA] Claves sin re-envolver — ventana de gracia próxima a cerrar',
          'Quedan ' || v_pending_total || ' claves (DEKs/KEKs) sin re-envolver para la versión ' ||
          v_old_key_version || '. La ventana de gracia cierra el ' ||
          to_char(v_grace_end, 'DD/MM/YYYY HH24:MI') || ' UTC. ' ||
          'Acción requerida: verificar logs del job kms-rewrap-deks-batch.',
          'key_rotation_alert'
        );
      END LOOP;
    END IF;

    -- ── 4f. Registrar en security_audit_chain ─────────────────────────────
    INSERT INTO public.security_audit_chain (
      actor_id,
      workspace_id,
      category,
      action,
      resource_type,
      outcome,
      metadata,
      chain_hash,
      previous_hash,
      is_legal_event,
      created_at
    )
    SELECT
      NULL,
      wm.workspace_id,
      'encryption',
      'key.rewrap_batch',
      'encryption_key',
      CASE WHEN v_errors > 0 THEN 'partial' ELSE 'success' END,
      jsonb_build_object(
        'old_key_version',      v_old_key_version,
        'new_key_version',      v_new_key_version,
        'rewrapped_dem',        v_rewrapped_dem,
        'rewrapped_dpd',        v_rewrapped_dpd,
        'rewrapped_esv_marked', v_rewrapped_esv,
        'errors',               v_errors,
        'pending_remaining',    v_pending_total,
        'triggered_by',         'pg_cron:kms-rewrap-deks-batch',
        'grace_period_ends_at', v_grace_end::TEXT
      ),
      encode(digest(
        'rewrap:' || v_old_key_version || ':' || now()::TEXT || ':' || wm.workspace_id::TEXT,
        'sha256'
      ), 'hex'),
      COALESCE((
        SELECT chain_hash FROM public.security_audit_chain
        WHERE workspace_id = wm.workspace_id
        ORDER BY created_at DESC LIMIT 1
      ), 'genesis'),
      false,
      now()
    FROM (SELECT DISTINCT workspace_id FROM public.workspace_members) wm
    ON CONFLICT DO NOTHING;

  END LOOP;

  v_result := jsonb_build_object(
    'status',           CASE WHEN v_errors > 0 THEN 'partial' ELSE 'success' END,
    'rewrapped_dem',    v_rewrapped_dem,
    'rewrapped_dpd',    v_rewrapped_dpd,
    'rewrapped_esv',    v_rewrapped_esv,
    'errors',           v_errors,
    'pending_remaining', v_pending_total
  );

  RETURN v_result;

EXCEPTION WHEN OTHERS THEN
  RAISE WARNING '[KMS] kms_rewrap_deks_batch failed: %', SQLERRM;
  RETURN jsonb_build_object('status', 'error', 'message', SQLERRM);
END;
$function$
;

-- [FUNCTION] public.kms_rotate_master_key()
CREATE OR REPLACE FUNCTION public.kms_rotate_master_key()
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE
  v_old_key_name    TEXT := 'docubox-master-kek-v1';
  v_version_num     INT;
  v_new_key_name    TEXT;
  v_new_vault_key   UUID;
  v_old_kv_id       UUID;
  v_new_kv_id       UUID;
  v_audit_hash      TEXT;
  v_prev_hash       TEXT;
  v_workspace_id    UUID;
  v_result          TEXT;
BEGIN
  -- Determinar número de versión siguiente
  SELECT COUNT(*) + 1 INTO v_version_num
  FROM public.kms_key_versions
  WHERE key_name LIKE 'docubox-master-kek-v%';

  v_new_key_name := 'docubox-master-kek-v' || v_version_num;

  -- Verificar que no exista ya
  IF EXISTS (SELECT 1 FROM public.kms_key_versions WHERE key_name = v_new_key_name) THEN
    RAISE NOTICE '[KMS] Key % already exists — rotation skipped.', v_new_key_name;
    RETURN 'skipped:already_exists:' || v_new_key_name;
  END IF;

  -- Crear nueva clave en pgsodium Vault
  BEGIN
    SELECT id INTO v_new_vault_key
    FROM pgsodium.create_key(
      'aead-det',
      v_new_key_name,
      NULL,
      NULL,
      NULL,
      decode('646f63756f787800', 'hex'),
      NULL,
      NULL
    );
  EXCEPTION WHEN OTHERS THEN
    -- Alertar a vault_admin en todos los workspaces con vault_admin
    FOR v_workspace_id IN
      SELECT DISTINCT workspace_id FROM public.workspace_members
      WHERE role::TEXT IN ('vault_admin', 'owner')
    LOOP
      PERFORM public.kms_alert_vault_admin(
        v_workspace_id,
        '[ALERTA] Fallo en rotación de master key',
        'La rotación automática de la master key falló al crear la nueva versión en Vault. Error: ' || SQLERRM || '. Acción requerida: revisar logs y ejecutar rotación manual.',
        'key_rotation_alert'
      );
    END LOOP;

    RAISE WARNING '[KMS] Failed to create new vault key: %', SQLERRM;
    RETURN 'error:vault_create_failed:' || SQLERRM;
  END;

  -- Registrar nueva versión en kms_key_versions
  INSERT INTO public.kms_key_versions (key_name, vault_key_id, algorithm, comment)
  VALUES (
    v_new_key_name,
    v_new_vault_key,
    'aead-det',
    'Auto-rotated master key. Predecessor: ' || v_old_key_name || '. Rotation timestamp: ' || now()::TEXT
  )
  RETURNING id INTO v_new_kv_id;

  -- Obtener ID de la versión anterior
  SELECT id INTO v_old_kv_id
  FROM public.kms_key_versions
  WHERE key_name = v_old_key_name AND is_active = true
  LIMIT 1;

  -- Marcar versión anterior como no-activa (se mantiene para re-envolvimiento)
  UPDATE public.kms_key_versions
  SET is_active = false, rotated_at = now()
  WHERE key_name = v_old_key_name;

  -- Registrar en sensitive_field_key_versions para TODOS los workspaces activos
  -- (la master key es global, pero el registro es por workspace para auditoría)
  INSERT INTO public.sensitive_field_key_versions (
    workspace_id,
    key_version,
    key_purpose,
    status,
    activated_at,
    vault_key_id,
    next_rotation_at,
    grace_period_ends_at,
    rewrap_pending_count,
    notes
  )
  SELECT
    wm.workspace_id,
    v_new_key_name,
    'document-encryption',
    'active',
    now(),
    v_new_vault_key,
    now() + INTERVAL '90 days',
    now() + INTERVAL '270 days',
    0,
    'Auto-rotated by pg_cron kms-rotate-master-key job'
  FROM (
    SELECT DISTINCT workspace_id FROM public.workspace_members
  ) wm
  ON CONFLICT (workspace_id, key_version, key_purpose) DO NOTHING;

  -- Marcar versión anterior como 'rotating' en sensitive_field_key_versions
  UPDATE public.sensitive_field_key_versions
  SET
    status = 'rotating',
    grace_period_ends_at = COALESCE(grace_period_ends_at, now() + INTERVAL '180 days'),
    rewrap_pending_count = (
      -- Contar DEKs/KEKs que aún usan esta versión
      SELECT COUNT(*) FROM (
        SELECT id FROM public.document_encryption_metadata
          WHERE key_version = v_old_key_name
        UNION ALL
        SELECT id FROM public.document_participant_deks
          WHERE kek_version = v_old_key_name AND access_status = 'active'
        UNION ALL
        SELECT id FROM public.efirma_sat_vault
          WHERE kek_version = v_old_key_name AND vault_status = 'active'
      ) deps
    )
  WHERE key_version = v_old_key_name
    AND status = 'active';

  -- Registrar en security_audit_chain
  SELECT COALESCE(MAX(chain_hash), 'genesis') INTO v_prev_hash
  FROM public.security_audit_chain
  ORDER BY created_at DESC
  LIMIT 1;

  v_audit_hash := encode(
    digest(
      v_prev_hash || ':key.rotation:' || v_new_key_name || ':' || now()::TEXT,
      'sha256'
    ),
    'hex'
  );

  INSERT INTO public.security_audit_chain (
    actor_id,
    workspace_id,
    category,
    action,
    resource_type,
    resource_id,
    outcome,
    metadata,
    chain_hash,
    previous_hash,
    is_legal_event,
    created_at
  )
  SELECT
    NULL,                          -- actor_id: sistema (pg_cron)
    wm.workspace_id,
    'encryption',
    'key.rotation',
    'encryption_key',
    v_new_kv_id::TEXT,
    'success',
    jsonb_build_object(
      'key_purpose',       'document-encryption',
      'old_key_version',   v_old_key_name,
      'new_key_version',   v_new_key_name,
      'triggered_by',      'pg_cron:kms-rotate-master-key',
      'vault_key_id',      v_new_vault_key::TEXT
    ),
    v_audit_hash,
    v_prev_hash,
    false,
    now()
  FROM (SELECT DISTINCT workspace_id FROM public.workspace_members) wm
  ON CONFLICT DO NOTHING;

  v_result := 'success:' || v_new_key_name || ':vault_key_id=' || v_new_vault_key::TEXT;
  RAISE NOTICE '[KMS] Master key rotated: %', v_result;
  RETURN v_result;

EXCEPTION WHEN OTHERS THEN
  RAISE WARNING '[KMS] kms_rotate_master_key failed: %', SQLERRM;
  RETURN 'error:' || SQLERRM;
END;
$function$
;

-- [FUNCTION] public.kms_unwrap_key(wrapped_kek_b64 text, key_name text)
CREATE OR REPLACE FUNCTION public.kms_unwrap_key(wrapped_kek_b64 text, key_name text DEFAULT 'docubox-master-kek-v1'::text)
 RETURNS bytea
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE
  v_vault_key_id UUID;
  v_plain        BYTEA;
BEGIN
  SELECT vault_key_id INTO v_vault_key_id
  FROM public.kms_key_versions
  WHERE kms_key_versions.key_name = kms_unwrap_key.key_name
    AND is_active = true
  LIMIT 1;

  IF v_vault_key_id IS NULL THEN
    RAISE EXCEPTION '[KMS] No active master key found for name: %', key_name;
  END IF;

  v_plain := pgsodium.crypto_aead_det_decrypt(
    decode(wrapped_kek_b64, 'base64'),
    convert_to(key_name, 'UTF8'),   -- must match additional data used during wrap
    v_vault_key_id
  );

  RETURN v_plain;
END;
$function$
;

-- [FUNCTION] public.kms_wrap_key(plain_kek bytea, key_name text)
CREATE OR REPLACE FUNCTION public.kms_wrap_key(plain_kek bytea, key_name text DEFAULT 'docubox-master-kek-v1'::text)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE
  v_vault_key_id UUID;
  v_wrapped      BYTEA;
BEGIN
  -- Resolve vault key id
  SELECT vault_key_id INTO v_vault_key_id
  FROM public.kms_key_versions
  WHERE kms_key_versions.key_name = kms_wrap_key.key_name
    AND is_active = true
  LIMIT 1;

  IF v_vault_key_id IS NULL THEN
    RAISE EXCEPTION '[KMS] No active master key found for name: %', key_name;
  END IF;

  -- Encrypt using pgsodium deterministic AEAD (XChaCha20-Poly1305)
  -- additional_data = key_name bytes for domain separation
  v_wrapped := pgsodium.crypto_aead_det_encrypt(
    plain_kek,
    convert_to(key_name, 'UTF8'),   -- additional authenticated data
    v_vault_key_id
  );

  RETURN encode(v_wrapped, 'base64');
END;
$function$
;

