-- [FUNCTION] public.match_document_chunks(query_embedding vector, p_workspace_id uuid, p_document_id uuid, match_threshold double precision, match_count integer)
CREATE OR REPLACE FUNCTION public.match_document_chunks(query_embedding vector, p_workspace_id uuid, p_document_id uuid DEFAULT NULL::uuid, match_threshold double precision DEFAULT 0.70, match_count integer DEFAULT 8)
 RETURNS TABLE(id uuid, document_id uuid, workspace_id uuid, content text, page_number integer, chunk_index integer, metadata jsonb, similarity double precision)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
BEGIN
  RETURN QUERY
  SELECT
    c.id,
    c.document_id,
    c.workspace_id,
    c.content,
    c.page_number,
    c.chunk_index,
    c.metadata,
    1 - (c.embedding <=> query_embedding) AS similarity
  FROM public.ai_document_chunks c
  WHERE
    c.workspace_id = p_workspace_id
    AND (p_document_id IS NULL OR c.document_id = p_document_id)
    AND c.embedding IS NOT NULL
    AND 1 - (c.embedding <=> query_embedding) >= match_threshold
  ORDER BY c.embedding <=> query_embedding
  LIMIT match_count;
END;
$function$
;

-- [FUNCTION] public.next_case_file_folio(target_workspace uuid)
CREATE OR REPLACE FUNCTION public.next_case_file_folio(target_workspace uuid)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE next_number integer;
BEGIN
  SELECT COALESCE(MAX((regexp_match(folio, '([0-9]+)$'))[1]::integer), 0) + 1 INTO next_number
  FROM public.case_files WHERE workspace_id = target_workspace AND folio LIKE 'EXP-' || EXTRACT(YEAR FROM now())::text || '-%';
  RETURN 'EXP-' || EXTRACT(YEAR FROM now())::text || '-' || lpad(next_number::text, 6, '0');
END;
$function$
;

-- [FUNCTION] public.notify_enrollment_complete()
CREATE OR REPLACE FUNCTION public.notify_enrollment_complete()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
BEGIN
    -- Only fire when status changes TO 'completed'
    IF NEW.status = 'completed' AND (OLD.status IS NULL OR OLD.status <> 'completed') THEN
        PERFORM pg_notify(
            'enrollment_complete',
            json_build_object(
                'enrollment_result_id', NEW.id,
                'enrollment_token_id', NEW.enrollment_token_id,
                'token', NEW.token,
                'session_id', NEW.session_id,
                'user_id', NEW.user_id,
                'curp', NEW.curp,
                'nombre', NEW.nombre,
                'apellido_paterno', NEW.apellido_paterno,
                'tipo_identificacion', NEW.tipo_identificacion,
                'face_match_score', NEW.face_match_score,
                'face_match_passed', NEW.face_match_passed,
                'created_at', NEW.created_at
            )::text
        );
    END IF;
    RETURN NEW;
END;
$function$
;

-- [FUNCTION] public.notify_new_participant_dek_needed()
CREATE OR REPLACE FUNCTION public.notify_new_participant_dek_needed()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE
  v_old_participants JSONB;
  v_new_participants JSONB;
  v_participant      JSONB;
  v_email            TEXT;
  v_user_id          TEXT;
  v_role             TEXT;
  v_has_dek          BOOLEAN;
  v_payload          JSONB;
BEGIN
  -- Only fire when participantes JSONB actually changes
  IF TG_OP = 'UPDATE' AND (OLD.participantes IS NOT DISTINCT FROM NEW.participantes) THEN
    RETURN NEW;
  END IF;

  -- Only process documents that already have encryption metadata
  -- (i.e., the document has been encrypted — not just a draft)
  IF NOT EXISTS (
    SELECT 1 FROM public.document_encryption_metadata
    WHERE document_id = NEW.id
  ) THEN
    RETURN NEW;
  END IF;

  v_old_participants := COALESCE(OLD.participantes, '[]'::JSONB);
  v_new_participants := COALESCE(NEW.participantes, '[]'::JSONB);

  -- Iterate over new participants to find newly added ones
  FOR v_participant IN SELECT * FROM jsonb_array_elements(v_new_participants)
  LOOP
    v_email   := v_participant->>'email';
    v_user_id := v_participant->>'user_id';
    v_role    := COALESCE(v_participant->>'acto', 'signer');

    -- Skip if no email
    IF v_email IS NULL OR v_email = '' THEN
      CONTINUE;
    END IF;

    -- Check if this participant was already in the old list
    -- (avoid re-notifying for existing participants)
    IF v_old_participants @> jsonb_build_array(jsonb_build_object('email', v_email)) THEN
      CONTINUE;
    END IF;

    -- Check if this participant already has an active DEK
    SELECT EXISTS (
      SELECT 1 FROM public.document_participant_deks
      WHERE document_id = NEW.id
        AND participant_email = v_email
        AND access_status = 'active'
    ) INTO v_has_dek;

    IF v_has_dek THEN
      CONTINUE;
    END IF;

    -- Emit notification for the backend to generate the wrap
    v_payload := jsonb_build_object(
      'document_id',         NEW.id,
      'workspace_id',        NEW.workspace_id,
      'participant_email',   v_email,
      'participant_user_id', v_user_id,
      'participant_role',    v_role
    );

    PERFORM pg_notify('new_participant_dek_needed', v_payload::TEXT);

  END LOOP;

  RETURN NEW;
END;
$function$
;

