-- [FUNCTION] public.prevent_certification_source_mutation()
CREATE OR REPLACE FUNCTION public.prevent_certification_source_mutation()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
BEGIN
  IF OLD.document_version_id IS NOT NULL
    AND OLD.execution_status <> 'created'
    AND (
      NEW.document_id IS DISTINCT FROM OLD.document_id
      OR NEW.document_version_id IS DISTINCT FROM OLD.document_version_id
      OR NEW.source_document_hash IS DISTINCT FROM OLD.source_document_hash
      OR NEW.source_document_hash_algorithm IS DISTINCT FROM OLD.source_document_hash_algorithm
      OR NEW.source_document_size_bytes IS DISTINCT FROM OLD.source_document_size_bytes
      OR NEW.source_storage_bucket IS DISTINCT FROM OLD.source_storage_bucket
      OR NEW.source_storage_path IS DISTINCT FROM OLD.source_storage_path
    )
  THEN
    RAISE EXCEPTION 'certification_source_is_immutable' USING ERRCODE = '55000';
  END IF;
  RETURN NEW;
END;
$function$
;

-- [FUNCTION] public.prevent_formal_comment_delete()
CREATE OR REPLACE FUNCTION public.prevent_formal_comment_delete()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
BEGIN
  IF OLD.audience = 'formal' OR OLD.parent_id IS NOT NULL OR EXISTS (
    SELECT 1 FROM public.collaboration_comments reply WHERE reply.parent_id = OLD.id
  ) THEN
    RAISE EXCEPTION 'comment_must_be_redacted' USING ERRCODE = '55000';
  END IF;
  RETURN OLD;
END;
$function$
;

-- [FUNCTION] public.prevent_frozen_document_version_delete()
CREATE OR REPLACE FUNCTION public.prevent_frozen_document_version_delete()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
BEGIN
  IF OLD.frozen_at IS NOT NULL OR OLD.status IN ('sent','signed') THEN
    RAISE EXCEPTION 'frozen_document_version' USING ERRCODE = '55000';
  END IF;
  RETURN OLD;
END;
$function$
;

-- [FUNCTION] public.prevent_frozen_document_version_mutation()
CREATE OR REPLACE FUNCTION public.prevent_frozen_document_version_mutation()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
BEGIN
  IF OLD.frozen_at IS NOT NULL OR OLD.status IN ('sent','signed') THEN
    RAISE EXCEPTION 'frozen_document_version' USING ERRCODE = '55000';
  END IF;
  NEW.version_number := OLD.version_number;
  NEW.document_id := OLD.document_id;
  NEW.workspace_id := OLD.workspace_id;
  RETURN NEW;
END;
$function$
;

-- [FUNCTION] public.prevent_organization_audit_mutation()
CREATE OR REPLACE FUNCTION public.prevent_organization_audit_mutation()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
BEGIN
  RAISE EXCEPTION 'organization_audit_events_are_immutable' USING ERRCODE = '55000';
END;
$function$
;

-- [FUNCTION] public.prevent_sealed_case_mutation()
CREATE OR REPLACE FUNCTION public.prevent_sealed_case_mutation()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE case_status text;
BEGIN
  IF TG_TABLE_NAME = 'case_files' THEN
    IF OLD.status = 'sealed' AND NEW.status <> 'reopened' THEN
      RAISE EXCEPTION 'A sealed case file is immutable';
    END IF;
    RETURN NEW;
  END IF;
  SELECT status INTO case_status FROM public.case_files WHERE id = COALESCE(NEW.case_file_id, OLD.case_file_id);
  IF case_status = 'sealed' THEN RAISE EXCEPTION 'A sealed case file is immutable'; END IF;
  RETURN COALESCE(NEW, OLD);
END;
$function$
;

-- [FUNCTION] public.protect_certification_original()
CREATE OR REPLACE FUNCTION public.protect_certification_original()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
BEGIN
  IF OLD.original_sha256 IS NOT NULL AND (
    NEW.original_sha256 IS DISTINCT FROM OLD.original_sha256 OR
    NEW.original_storage_path IS DISTINCT FROM OLD.original_storage_path OR
    NEW.original_size_bytes IS DISTINCT FROM OLD.original_size_bytes OR
    NEW.original_filename IS DISTINCT FROM OLD.original_filename
  ) THEN
    RAISE EXCEPTION 'certification_original_is_immutable';
  END IF;
  RETURN NEW;
END;
$function$
;

-- [FUNCTION] public.protect_document_governance_snapshot()
CREATE OR REPLACE FUNCTION public.protect_document_governance_snapshot()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
BEGIN
  IF auth.role() = 'authenticated' THEN
    IF TG_OP = 'INSERT' AND (
      NEW.organization_workflow_id IS NOT NULL
      OR NEW.organization_signature_policy_id IS NOT NULL
      OR NEW.organization_workflow_instance_id IS NOT NULL
      OR NEW.organization_governance_snapshot IS NOT NULL
      OR NEW.organization_governance_applied_at IS NOT NULL
    ) THEN
      RAISE EXCEPTION 'document_governance_is_backend_managed' USING ERRCODE = '42501';
    ELSIF TG_OP = 'UPDATE' AND (
      NEW.organization_workflow_id IS DISTINCT FROM OLD.organization_workflow_id
      OR NEW.organization_signature_policy_id IS DISTINCT FROM OLD.organization_signature_policy_id
      OR NEW.organization_workflow_instance_id IS DISTINCT FROM OLD.organization_workflow_instance_id
      OR NEW.organization_governance_snapshot IS DISTINCT FROM OLD.organization_governance_snapshot
      OR NEW.organization_governance_applied_at IS DISTINCT FROM OLD.organization_governance_applied_at
    ) THEN
      RAISE EXCEPTION 'document_governance_is_backend_managed' USING ERRCODE = '42501';
    END IF;
  END IF;
  RETURN NEW;
END;
$function$
;

-- [FUNCTION] public.protect_organization_ownership()
CREATE OR REPLACE FUNCTION public.protect_organization_ownership()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
BEGIN
  IF TG_TABLE_NAME = 'workspaces' AND NEW.owner_id IS DISTINCT FROM OLD.owner_id THEN
    RAISE EXCEPTION 'organization_owner_change_requires_transfer_workflow' USING ERRCODE = '42501';
  END IF;

  IF TG_TABLE_NAME = 'workspace_members' AND OLD.role = 'owner'::public.workspace_member_role THEN
    IF TG_OP = 'DELETE' THEN
      RAISE EXCEPTION 'organization_owner_membership_is_protected' USING ERRCODE = '42501';
    END IF;
    IF NEW.role IS DISTINCT FROM OLD.role OR NEW.status IS DISTINCT FROM 'active' THEN
      RAISE EXCEPTION 'organization_owner_change_requires_transfer_workflow' USING ERRCODE = '42501';
    END IF;
  END IF;

  IF TG_OP = 'DELETE' THEN
    RETURN OLD;
  END IF;
  RETURN NEW;
END;
$function$
;

-- [FUNCTION] public.protect_organization_system_roles()
CREATE OR REPLACE FUNCTION public.protect_organization_system_roles()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
BEGIN
  IF OLD.is_system AND (
    NEW.name IS DISTINCT FROM OLD.name
    OR NEW.system_key IS DISTINCT FROM OLD.system_key
    OR NEW.is_system IS DISTINCT FROM OLD.is_system
    OR NEW.status IS DISTINCT FROM OLD.status
  ) THEN
    RAISE EXCEPTION 'organization_system_role_is_protected' USING ERRCODE = '42501';
  END IF;
  IF NEW.status = 'archived' AND OLD.status IS DISTINCT FROM 'archived' THEN
    NEW.archived_at := CURRENT_TIMESTAMP;
  ELSIF NEW.status = 'active' THEN
    NEW.archived_at := NULL;
  END IF;
  RETURN NEW;
END;
$function$
;

-- [FUNCTION] public.protect_published_organization_governance()
CREATE OR REPLACE FUNCTION public.protect_published_organization_governance()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
BEGIN
  IF OLD.status = 'published' THEN
    IF TG_TABLE_NAME = 'organization_approval_workflows'
       AND (NEW.name, NEW.description, NEW.version, NEW.definition, NEW.document_type, NEW.applicable_areas)
           IS DISTINCT FROM
           (OLD.name, OLD.description, OLD.version, OLD.definition, OLD.document_type, OLD.applicable_areas) THEN
      RAISE EXCEPTION 'published_workflow_is_immutable' USING ERRCODE = '55000';
    ELSIF TG_TABLE_NAME = 'organization_signature_policies'
       AND (NEW.name, NEW.description, NEW.version, NEW.security_level, NEW.resource_scope, NEW.allowed_signature_types, NEW.requirements)
           IS DISTINCT FROM
           (OLD.name, OLD.description, OLD.version, OLD.security_level, OLD.resource_scope, OLD.allowed_signature_types, OLD.requirements) THEN
      RAISE EXCEPTION 'published_signature_policy_is_immutable' USING ERRCODE = '55000';
    END IF;
  END IF;
  RETURN NEW;
END;
$function$
;

-- [FUNCTION] public.protect_published_organization_resource()
CREATE OR REPLACE FUNCTION public.protect_published_organization_resource()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
BEGIN
  IF OLD.status = 'published' AND (
    NEW.name IS DISTINCT FROM OLD.name
    OR NEW.description IS DISTINCT FROM OLD.description
    OR NEW.visibility IS DISTINCT FROM OLD.visibility
    OR NEW.workflow_id IS DISTINCT FROM OLD.workflow_id
    OR NEW.signature_policy_id IS DISTINCT FROM OLD.signature_policy_id
    OR NEW.configuration IS DISTINCT FROM OLD.configuration
    OR NEW.version IS DISTINCT FROM OLD.version
    OR NEW.locked IS DISTINCT FROM OLD.locked
  ) THEN
    RAISE EXCEPTION 'published_organization_resource_is_immutable' USING ERRCODE = '55000';
  END IF;
  RETURN NEW;
END;
$function$
;

-- [FUNCTION] public.publish_organization_shared_resource(ws_id uuid, target_resource_id uuid)
CREATE OR REPLACE FUNCTION public.publish_organization_shared_resource(ws_id uuid, target_resource_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE
  resource_record public.organization_shared_resources%ROWTYPE;
BEGIN
  IF NOT public.has_organization_permission(ws_id, 'resources.manage') THEN
    RAISE EXCEPTION 'organization_permission_denied' USING ERRCODE = '42501';
  END IF;
  SELECT * INTO resource_record
  FROM public.organization_shared_resources
  WHERE id = target_resource_id AND workspace_id = ws_id
  FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'organization_resource_not_found' USING ERRCODE = 'P0002'; END IF;
  IF resource_record.status NOT IN ('draft', 'in_review', 'approved') THEN
    RAISE EXCEPTION 'organization_resource_cannot_be_published' USING ERRCODE = '55000';
  END IF;
  IF resource_record.workflow_id IS NOT NULL AND NOT EXISTS (
    SELECT 1 FROM public.organization_approval_workflows
    WHERE id = resource_record.workflow_id AND workspace_id = ws_id AND status = 'published'
  ) THEN
    RAISE EXCEPTION 'organization_resource_workflow_not_published' USING ERRCODE = '23514';
  END IF;
  IF resource_record.signature_policy_id IS NOT NULL AND NOT EXISTS (
    SELECT 1 FROM public.organization_signature_policies
    WHERE id = resource_record.signature_policy_id AND workspace_id = ws_id AND status = 'published'
  ) THEN
    RAISE EXCEPTION 'organization_resource_policy_not_published' USING ERRCODE = '23514';
  END IF;
  UPDATE public.organization_shared_resources
  SET status = 'published', locked = TRUE, updated_at = CURRENT_TIMESTAMP
  WHERE id = target_resource_id;
  INSERT INTO public.organization_audit_events (workspace_id, actor_user_id, event_type, resource_type, resource_id, summary, payload, module, severity)
  VALUES (ws_id, auth.uid(), 'resource.published', 'organization_shared_resource', target_resource_id::TEXT,
    'Recurso organizacional publicado', jsonb_build_object('version', resource_record.version), 'resources', 'high');
END;
$function$
;

-- [FUNCTION] public.publish_organization_signature_policy(ws_id uuid, target_policy_id uuid)
CREATE OR REPLACE FUNCTION public.publish_organization_signature_policy(ws_id uuid, target_policy_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE
  policy_record public.organization_signature_policies%ROWTYPE;
BEGIN
  IF NOT public.has_organization_permission(ws_id, 'signature_policies.manage') THEN
    RAISE EXCEPTION 'organization_permission_denied' USING ERRCODE = '42501';
  END IF;
  SELECT * INTO policy_record FROM public.organization_signature_policies
  WHERE id = target_policy_id AND workspace_id = ws_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'organization_signature_policy_not_found' USING ERRCODE = 'P0002'; END IF;
  IF policy_record.status <> 'draft' THEN RAISE EXCEPTION 'only_draft_policies_can_be_published' USING ERRCODE = '55000'; END IF;
  IF COALESCE(cardinality(policy_record.allowed_signature_types), 0) = 0 THEN
    RAISE EXCEPTION 'signature_policy_requires_a_method' USING ERRCODE = '23514';
  END IF;
  IF jsonb_array_length(COALESCE(policy_record.requirements->'unavailable_capabilities', '[]'::jsonb)) > 0 THEN
    RAISE EXCEPTION 'signature_policy_has_unavailable_capabilities' USING ERRCODE = '23514';
  END IF;
  UPDATE public.organization_signature_policies
  SET status = 'published', published_at = CURRENT_TIMESTAMP, published_by = auth.uid(), updated_at = CURRENT_TIMESTAMP
  WHERE id = target_policy_id;
  INSERT INTO public.organization_audit_events (workspace_id, actor_user_id, event_type, resource_type, resource_id, summary, payload)
  VALUES (ws_id, auth.uid(), 'signature_policy.published', 'organization_signature_policy', target_policy_id::TEXT,
    'Política de firma publicada', jsonb_build_object('version', policy_record.version));
END;
$function$
;

-- [FUNCTION] public.publish_organization_workflow(ws_id uuid, target_workflow_id uuid)
CREATE OR REPLACE FUNCTION public.publish_organization_workflow(ws_id uuid, target_workflow_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE
  workflow_record public.organization_approval_workflows%ROWTYPE;
  step JSONB;
  has_start BOOLEAN := FALSE;
  has_terminal BOOLEAN := FALSE;
BEGIN
  IF NOT public.has_organization_permission(ws_id, 'workflows.manage') THEN
    RAISE EXCEPTION 'organization_permission_denied' USING ERRCODE = '42501';
  END IF;
  SELECT * INTO workflow_record FROM public.organization_approval_workflows
  WHERE id = target_workflow_id AND workspace_id = ws_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'organization_workflow_not_found' USING ERRCODE = 'P0002'; END IF;
  IF workflow_record.status <> 'draft' THEN RAISE EXCEPTION 'only_draft_workflows_can_be_published' USING ERRCODE = '55000'; END IF;
  IF jsonb_typeof(workflow_record.definition->'steps') <> 'array'
     OR jsonb_array_length(workflow_record.definition->'steps') < 2 THEN
    RAISE EXCEPTION 'workflow_requires_at_least_two_steps' USING ERRCODE = '23514';
  END IF;
  FOR step IN SELECT value FROM jsonb_array_elements(workflow_record.definition->'steps') LOOP
    IF COALESCE(step->>'type', '') NOT IN ('start', 'review', 'approval', 'signature', 'identity', 'condition', 'notification', 'wait', 'approved', 'rejected', 'cancelled')
       OR NULLIF(BTRIM(step->>'label'), '') IS NULL THEN
      RAISE EXCEPTION 'workflow_contains_invalid_step' USING ERRCODE = '23514';
    END IF;
    has_start := has_start OR step->>'type' = 'start';
    has_terminal := has_terminal OR step->>'type' IN ('approved', 'rejected', 'cancelled');
  END LOOP;
  IF NOT has_start OR NOT has_terminal THEN
    RAISE EXCEPTION 'workflow_requires_start_and_terminal_steps' USING ERRCODE = '23514';
  END IF;
  UPDATE public.organization_approval_workflows
  SET status = 'published', published_at = CURRENT_TIMESTAMP, published_by = auth.uid(), updated_at = CURRENT_TIMESTAMP
  WHERE id = target_workflow_id;
  INSERT INTO public.organization_audit_events (workspace_id, actor_user_id, event_type, resource_type, resource_id, summary, payload)
  VALUES (ws_id, auth.uid(), 'workflow.published', 'organization_approval_workflow', target_workflow_id::TEXT,
    'Flujo de aprobación publicado', jsonb_build_object('version', workflow_record.version));
END;
$function$
;

-- [FUNCTION] public.record_collaboration_usage(ws_id uuid, requested_entitlement_key text, requested_meter_key text, requested_quantity numeric, requested_idempotency_key text, requested_resource_type text, requested_resource_id uuid, requested_metadata jsonb)
CREATE OR REPLACE FUNCTION public.record_collaboration_usage(ws_id uuid, requested_entitlement_key text, requested_meter_key text, requested_quantity numeric, requested_idempotency_key text, requested_resource_type text DEFAULT NULL::text, requested_resource_id uuid DEFAULT NULL::uuid, requested_metadata jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE
  v_existing_id UUID;
  v_event_id UUID;
BEGIN
  IF ws_id IS NULL
     OR NULLIF(trim(requested_entitlement_key), '') IS NULL
     OR NULLIF(trim(requested_meter_key), '') IS NULL
     OR NULLIF(trim(requested_idempotency_key), '') IS NULL
     OR requested_quantity IS NULL
     OR requested_quantity <= 0 THEN
    RAISE EXCEPTION 'invalid_usage_event' USING ERRCODE = '22023';
  END IF;

  PERFORM pg_advisory_xact_lock(
    hashtextextended(ws_id::TEXT || ':' || requested_meter_key, 0)
  );

  SELECT id INTO v_existing_id
  FROM public.collaboration_usage_events
  WHERE workspace_id = ws_id
    AND meter_key = requested_meter_key
    AND idempotency_key = requested_idempotency_key;

  IF v_existing_id IS NOT NULL THEN
    RETURN jsonb_build_object('event_id', v_existing_id, 'created', FALSE);
  END IF;

  INSERT INTO public.collaboration_usage_events(
    workspace_id, entitlement_key, meter_key, quantity,
    idempotency_key, resource_type, resource_id, metadata
  ) VALUES (
    ws_id, requested_entitlement_key, requested_meter_key, requested_quantity,
    requested_idempotency_key, requested_resource_type, requested_resource_id,
    COALESCE(requested_metadata, '{}'::JSONB)
  )
  RETURNING id INTO v_event_id;

  RETURN jsonb_build_object('event_id', v_event_id, 'created', TRUE);
END;
$function$
;

-- [FUNCTION] public.record_collaboration_usage_insert()
CREATE OR REPLACE FUNCTION public.record_collaboration_usage_insert()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE
  v_entitlement TEXT;
  v_meter TEXT;
  v_limit NUMERIC;
  v_usage NUMERIC := 0;
  v_should_meter BOOLEAN := TRUE;
BEGIN
  CASE TG_TABLE_NAME
    WHEN 'collaboration_spaces' THEN
      v_entitlement := 'collaboration_core'; v_meter := 'active_spaces';
    WHEN 'collaboration_rooms' THEN
      v_entitlement := 'collaboration_external_rooms'; v_meter := 'external_rooms';
    WHEN 'collaboration_room_guests' THEN
      v_entitlement := 'collaboration_external_rooms'; v_meter := 'external_guests';
    WHEN 'collaboration_automation_runs' THEN
      v_entitlement := 'collaboration_automations'; v_meter := 'automation_runs';
    ELSE
      RETURN NEW;
  END CASE;

  -- Serialize the meter per workspace. This prevents two concurrent requests from
  -- both observing the same remaining capacity and exceeding the contracted limit.
  PERFORM pg_advisory_xact_lock(
    hashtextextended(NEW.workspace_id::TEXT || ':' || v_meter, 0)
  );

  SELECT NULLIF(oe.limits ->> v_meter, '')::NUMERIC
    INTO v_limit
  FROM public.organization_entitlements oe
  WHERE oe.workspace_id = NEW.workspace_id
    AND oe.entitlement_key = v_entitlement
    AND oe.status IN ('trialing', 'active', 'past_due')
    AND (oe.starts_at IS NULL OR oe.starts_at <= CURRENT_TIMESTAMP)
    AND (oe.ends_at IS NULL OR oe.ends_at > CURRENT_TIMESTAMP)
  LIMIT 1;

  IF TG_TABLE_NAME = 'collaboration_spaces' THEN
    v_should_meter := NEW.status = 'active';
    IF v_should_meter THEN
      SELECT COUNT(*) INTO v_usage
      FROM public.collaboration_spaces
      WHERE workspace_id = NEW.workspace_id AND status = 'active';
    END IF;
  ELSIF TG_TABLE_NAME = 'collaboration_rooms' THEN
    v_should_meter := NEW.status = 'active';
    IF v_should_meter THEN
      SELECT COUNT(*) INTO v_usage
      FROM public.collaboration_rooms
      WHERE workspace_id = NEW.workspace_id AND status = 'active';
    END IF;
  ELSIF TG_TABLE_NAME = 'collaboration_room_guests' THEN
    v_should_meter := NEW.status NOT IN ('expired', 'revoked', 'blocked');
    IF v_should_meter THEN
      SELECT COUNT(*) INTO v_usage
      FROM public.collaboration_room_guests
      WHERE workspace_id = NEW.workspace_id
        AND status NOT IN ('expired', 'revoked', 'blocked');
    END IF;
  ELSE
    SELECT COALESCE(SUM(quantity), 0) INTO v_usage
    FROM public.collaboration_usage_events
    WHERE workspace_id = NEW.workspace_id
      AND meter_key = v_meter
      AND occurred_at >= date_trunc('month', CURRENT_TIMESTAMP);
  END IF;

  -- AFTER INSERT means the current resource is already represented in table counts.
  -- Event meters are historical, so include the current execution explicitly.
  IF TG_TABLE_NAME = 'collaboration_automation_runs' THEN
    v_usage := v_usage + 1;
  END IF;

  IF v_should_meter AND v_limit IS NOT NULL AND v_usage > v_limit THEN
    RAISE EXCEPTION USING
      ERRCODE = 'P0001',
      MESSAGE = 'collaboration_usage_limit_exceeded',
      DETAIL = format('meter=%s usage=%s limit=%s', v_meter, v_usage, v_limit),
      HINT = 'Upgrade the Colabora entitlement or release active capacity.';
  END IF;

  IF NOT v_should_meter THEN
    RETURN NEW;
  END IF;

  INSERT INTO public.collaboration_usage_events(
    workspace_id, entitlement_key, meter_key, quantity,
    idempotency_key, resource_type, resource_id, metadata
  ) VALUES (
    NEW.workspace_id, v_entitlement, v_meter, 1,
    TG_TABLE_NAME || ':' || NEW.id::TEXT, TG_TABLE_NAME, NEW.id,
    jsonb_build_object('source', 'database_trigger')
  ) ON CONFLICT (workspace_id, meter_key, idempotency_key) DO NOTHING;
  RETURN NEW;
END;
$function$
;

-- [FUNCTION] public.record_verification_access(p_token text)
CREATE OR REPLACE FUNCTION public.record_verification_access(p_token text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE
  v_record public.public_verification_tokens%ROWTYPE;
BEGIN
  SELECT * INTO v_record
  FROM public.public_verification_tokens
  WHERE verification_token = p_token
    AND token_status = 'active'
    AND (expires_at IS NULL OR expires_at > now());

  IF NOT FOUND THEN
    RETURN jsonb_build_object('valid', false, 'error', 'Token no encontrado o expirado');
  END IF;

  UPDATE public.public_verification_tokens
  SET verification_count = verification_count + 1,
      last_verified_at = now()
  WHERE id = v_record.id;

  RETURN jsonb_build_object(
    'valid', true,
    'document_id', v_record.document_id,
    'document_hash', v_record.document_hash,
    'verification_payload', v_record.verification_payload,
    'generated_at', v_record.generated_at
  );
END;
$function$
;

-- [FUNCTION] public.register_auth_attempt(p_identifier text, p_identifier_type text, p_ip inet, p_success boolean, p_failure_reason text)
CREATE OR REPLACE FUNCTION public.register_auth_attempt(p_identifier text, p_identifier_type text, p_ip inet, p_success boolean, p_failure_reason text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE
  v_failure_count BIGINT;
  v_lockout_level INTEGER;
  v_lockout_duration INTERVAL;
  v_locked_until TIMESTAMPTZ;
BEGIN
  INSERT INTO public.auth_attempts (identifier, identifier_type, ip_address, success, failure_reason)
  VALUES (p_identifier, p_identifier_type, p_ip, p_success, p_failure_reason);

  IF p_success THEN
    UPDATE public.auth_lockouts
    SET unlocked_at = NOW()
    WHERE identifier = p_identifier
      AND unlocked_at IS NULL;
    RETURN jsonb_build_object('locked', false);
  END IF;

  SELECT COUNT(*) INTO v_failure_count
  FROM public.auth_attempts
  WHERE identifier = p_identifier
    AND success = false
    AND attempted_at > NOW() - INTERVAL '24 hours';

  IF v_failure_count >= 20 THEN
    v_lockout_level := 4;
    v_lockout_duration := INTERVAL '24 hours';
  ELSIF v_failure_count >= 15 THEN
    v_lockout_level := 3;
    v_lockout_duration := INTERVAL '30 minutes';
  ELSIF v_failure_count >= 10 THEN
    v_lockout_level := 2;
    v_lockout_duration := INTERVAL '5 minutes';
  ELSIF v_failure_count >= 5 THEN
    v_lockout_level := 1;
    v_lockout_duration := INTERVAL '30 seconds';
  ELSE
    RETURN jsonb_build_object('locked', false, 'lockout_level', 0, 'locked_until', NULL);
  END IF;

  v_locked_until := NOW() + v_lockout_duration;

  INSERT INTO public.auth_lockouts (identifier, locked_until, failed_attempts, lockout_level)
  VALUES (p_identifier, v_locked_until, v_failure_count, v_lockout_level)
  ON CONFLICT (identifier) DO UPDATE
    SET locked_until = v_locked_until,
        lockout_level = v_lockout_level,
        failed_attempts = v_failure_count,
        locked_at = NOW(),
        unlocked_at = NULL;

  RETURN jsonb_build_object(
    'locked', true,
    'lockout_level', v_lockout_level,
    'locked_until', v_locked_until
  );
END;
$function$
;

