-- [FUNCTION] public.revoke_organization_member_sessions(ws_id uuid, target_member_id uuid, revocation_reason text)
CREATE OR REPLACE FUNCTION public.revoke_organization_member_sessions(ws_id uuid, target_member_id uuid, revocation_reason text DEFAULT NULL::text)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE
  target_user_id UUID;
  revoked_count INTEGER := 0;
BEGIN
  IF NOT public.has_organization_permission(ws_id, 'security.manage') THEN
    RAISE EXCEPTION 'organization_permission_denied' USING ERRCODE = '42501';
  END IF;

  SELECT user_id INTO target_user_id
  FROM public.workspace_members
  WHERE id = target_member_id AND workspace_id = ws_id;

  IF target_user_id IS NULL THEN
    RAISE EXCEPTION 'organization_member_not_found' USING ERRCODE = 'P0002';
  END IF;

  WITH revoked AS (
    UPDATE public.user_sessions
    SET expires_at = CURRENT_TIMESTAMP,
        is_current = FALSE,
        session_token = 'revoked:' || id::TEXT || ':' || extract(epoch from CURRENT_TIMESTAMP)::BIGINT::TEXT
    WHERE user_id = target_user_id
      AND (expires_at IS NULL OR expires_at > CURRENT_TIMESTAMP OR is_current)
    RETURNING id
  ), recorded AS (
    INSERT INTO public.organization_session_revocations (
      workspace_id, member_id, session_id, scope, reason, revoked_by
    )
    SELECT ws_id, target_member_id, id, 'member_all', NULLIF(trim(revocation_reason), ''), auth.uid()
    FROM revoked
    RETURNING id
  )
  SELECT count(*) INTO revoked_count FROM recorded;

  INSERT INTO public.organization_audit_events (
    workspace_id, actor_user_id, event_type, resource_type, resource_id,
    summary, payload, severity, module
  ) VALUES (
    ws_id, auth.uid(), 'security.member_sessions.revoked', 'workspace_member', target_member_id::TEXT,
    'Sesiones del miembro revocadas',
    jsonb_build_object('revoked_count', revoked_count, 'reason_provided', NULLIF(trim(revocation_reason), '') IS NOT NULL),
    'high', 'security'
  );

  RETURN revoked_count;
END;
$function$
;

-- [FUNCTION] public.revoke_organization_session(ws_id uuid, target_session_id uuid, revocation_reason text)
CREATE OR REPLACE FUNCTION public.revoke_organization_session(ws_id uuid, target_session_id uuid, revocation_reason text DEFAULT NULL::text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE
  target_member_id UUID;
BEGIN
  IF NOT public.has_organization_permission(ws_id, 'security.manage') THEN
    RAISE EXCEPTION 'organization_permission_denied' USING ERRCODE = '42501';
  END IF;

  SELECT wm.id INTO target_member_id
  FROM public.user_sessions us
  JOIN public.workspace_members wm ON wm.user_id = us.user_id
  WHERE us.id = target_session_id AND wm.workspace_id = ws_id AND wm.status = 'active';

  IF target_member_id IS NULL THEN
    RAISE EXCEPTION 'organization_session_not_found' USING ERRCODE = 'P0002';
  END IF;

  UPDATE public.user_sessions
  SET expires_at = CURRENT_TIMESTAMP, is_current = FALSE,
      session_token = 'revoked:' || id::TEXT || ':' || extract(epoch from CURRENT_TIMESTAMP)::BIGINT::TEXT
  WHERE id = target_session_id;

  INSERT INTO public.organization_session_revocations (
    workspace_id, member_id, session_id, scope, reason, revoked_by
  ) VALUES (
    ws_id, target_member_id, target_session_id, 'single', NULLIF(trim(revocation_reason), ''), auth.uid()
  );

  INSERT INTO public.organization_audit_events (
    workspace_id, actor_user_id, event_type, resource_type, resource_id,
    summary, severity, module, correlation_id
  ) VALUES (
    ws_id, auth.uid(), 'security.session.revoked', 'user_session', target_session_id::TEXT,
    'Sesión organizacional revocada', 'high', 'security', gen_random_uuid()
  );
END;
$function$
;

