-- [FUNCTION] public.set_organization_governance_default(ws_id uuid, requested_kind text, requested_resource_id uuid, requested_correlation_id uuid)
CREATE OR REPLACE FUNCTION public.set_organization_governance_default(ws_id uuid, requested_kind text, requested_resource_id uuid DEFAULT NULL::uuid, requested_correlation_id uuid DEFAULT gen_random_uuid())
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE
  required_permission TEXT;
  setting_key TEXT;
  resource_type_name TEXT;
  resource_name TEXT;
  resource_version INTEGER;
  before_settings JSONB;
  after_settings JSONB;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'authentication_required' USING ERRCODE = '42501';
  END IF;

  CASE requested_kind
    WHEN 'workflow' THEN
      required_permission := 'workflows.manage';
      setting_key := 'default_workflow_id';
      resource_type_name := 'organization_approval_workflow';
    WHEN 'signature_policy' THEN
      required_permission := 'signature_policies.manage';
      setting_key := 'default_signature_policy_id';
      resource_type_name := 'organization_signature_policy';
    ELSE
      RAISE EXCEPTION 'invalid_governance_kind' USING ERRCODE = '22023';
  END CASE;

  IF NOT public.has_organization_permission(ws_id, required_permission) THEN
    RAISE EXCEPTION 'permission_denied' USING ERRCODE = '42501';
  END IF;

  IF requested_resource_id IS NOT NULL THEN
    IF requested_kind = 'workflow' THEN
      SELECT name, version INTO resource_name, resource_version
      FROM public.organization_approval_workflows
      WHERE workspace_id = ws_id
        AND id = requested_resource_id
        AND status = 'published';
    ELSE
      SELECT name, version INTO resource_name, resource_version
      FROM public.organization_signature_policies
      WHERE workspace_id = ws_id
        AND id = requested_resource_id
        AND status = 'published';
    END IF;

    IF resource_name IS NULL THEN
      RAISE EXCEPTION 'published_resource_required' USING ERRCODE = '23514';
    END IF;
  END IF;

  SELECT COALESCE(organization_settings, '{}'::JSONB)
  INTO before_settings
  FROM public.workspaces
  WHERE id = ws_id
    AND workspace_type = 'business'
    AND organization_enabled = TRUE
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'organization_not_found' USING ERRCODE = 'P0002';
  END IF;

  IF requested_resource_id IS NULL THEN
    after_settings := before_settings - setting_key;
  ELSE
    after_settings := jsonb_set(
      before_settings,
      ARRAY[setting_key],
      to_jsonb(requested_resource_id::TEXT),
      TRUE
    );
  END IF;

  UPDATE public.workspaces
  SET organization_settings = after_settings
  WHERE id = ws_id;

  INSERT INTO public.organization_audit_events (
    workspace_id,
    actor_user_id,
    event_type,
    resource_type,
    resource_id,
    summary,
    before_payload,
    after_payload,
    payload,
    outcome,
    severity,
    module,
    origin,
    correlation_id
  ) VALUES (
    ws_id,
    auth.uid(),
    format('governance.default.%s.updated', requested_kind),
    resource_type_name,
    requested_resource_id::TEXT,
    CASE
      WHEN requested_resource_id IS NULL THEN 'Se retiró el valor predeterminado'
      ELSE format('Se estableció %s como predeterminado', resource_name)
    END,
    jsonb_build_object(setting_key, before_settings -> setting_key),
    jsonb_build_object(setting_key, requested_resource_id),
    jsonb_build_object('version', resource_version),
    'success',
    'high',
    'governance',
    'api',
    requested_correlation_id
  );

  RETURN jsonb_build_object(
    'kind', requested_kind,
    'resource_id', requested_resource_id,
    'resource_name', resource_name,
    'resource_version', resource_version,
    'settings', after_settings
  );
END;
$function$
;

-- [FUNCTION] public.set_organization_member_access_status(ws_id uuid, target_member_id uuid, requested_status text)
CREATE OR REPLACE FUNCTION public.set_organization_member_access_status(ws_id uuid, target_member_id uuid, requested_status text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE
  target_user_id UUID;
  target_role public.workspace_member_role;
  revoked_count INTEGER := 0;
BEGIN
  IF NOT public.has_organization_permission(ws_id, 'members.suspend') THEN
    RAISE EXCEPTION 'organization_permission_denied' USING ERRCODE = '42501';
  END IF;

  IF requested_status NOT IN ('active', 'suspended') THEN
    RAISE EXCEPTION 'organization_member_status_invalid' USING ERRCODE = '22023';
  END IF;

  SELECT user_id, role INTO target_user_id, target_role
  FROM public.workspace_members
  WHERE id = target_member_id AND workspace_id = ws_id;

  IF target_user_id IS NULL THEN
    RAISE EXCEPTION 'organization_member_not_found' USING ERRCODE = 'P0002';
  END IF;

  IF target_role = 'owner'::public.workspace_member_role THEN
    RAISE EXCEPTION 'organization_owner_access_is_protected' USING ERRCODE = '42501';
  END IF;

  IF target_user_id = auth.uid() AND requested_status = 'suspended' THEN
    RAISE EXCEPTION 'organization_cannot_suspend_self' USING ERRCODE = '42501';
  END IF;

  UPDATE public.workspace_members
  SET status = requested_status,
      suspended_at = CASE WHEN requested_status = 'suspended' THEN CURRENT_TIMESTAMP ELSE NULL END
  WHERE id = target_member_id AND workspace_id = ws_id;

  IF requested_status = 'suspended' THEN
    WITH revoked AS (
      UPDATE public.user_sessions
      SET expires_at = CURRENT_TIMESTAMP,
          is_current = FALSE,
          session_token = 'revoked:' || id::TEXT || ':' || extract(epoch from CURRENT_TIMESTAMP)::BIGINT::TEXT
      WHERE user_id = target_user_id
        AND (expires_at IS NULL OR expires_at > CURRENT_TIMESTAMP OR is_current)
      RETURNING id
    ), recorded AS (
      INSERT INTO public.organization_session_revocations (
        workspace_id, member_id, session_id, scope, reason, revoked_by
      )
      SELECT ws_id, target_member_id, id, 'member_all', 'Suspensión de acceso', auth.uid()
      FROM revoked
      RETURNING id
    )
    SELECT count(*) INTO revoked_count FROM recorded;
  END IF;

  INSERT INTO public.organization_audit_events (
    workspace_id, actor_user_id, event_type, resource_type, resource_id,
    summary, payload, severity, module
  ) VALUES (
    ws_id, auth.uid(), 'member.' || requested_status, 'workspace_member', target_member_id::TEXT,
    CASE WHEN requested_status = 'suspended' THEN 'Acceso del miembro suspendido' ELSE 'Acceso del miembro reactivado' END,
    jsonb_build_object('status', requested_status, 'revoked_sessions', revoked_count),
    CASE WHEN requested_status = 'suspended' THEN 'high' ELSE 'info' END,
    'members'
  );
END;
$function$
;

-- [FUNCTION] public.set_organization_member_roles(ws_id uuid, target_member_id uuid, requested_role_ids uuid[])
CREATE OR REPLACE FUNCTION public.set_organization_member_roles(ws_id uuid, target_member_id uuid, requested_role_ids uuid[])
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE
  actor_role public.workspace_member_role;
  target_role public.workspace_member_role;
  invalid_role_count INTEGER;
  assigns_admin BOOLEAN;
BEGIN
  IF NOT public.has_organization_permission(ws_id, 'roles.manage') THEN
    RAISE EXCEPTION 'organization_permission_denied' USING ERRCODE = '42501';
  END IF;

  SELECT role INTO actor_role
  FROM public.workspace_members
  WHERE workspace_id = ws_id AND user_id = auth.uid() AND status = 'active';

  SELECT role INTO target_role
  FROM public.workspace_members
  WHERE id = target_member_id AND workspace_id = ws_id;

  IF target_role IS NULL THEN
    RAISE EXCEPTION 'organization_member_not_found' USING ERRCODE = 'P0002';
  END IF;

  IF target_role = 'owner'::public.workspace_member_role THEN
    RAISE EXCEPTION 'organization_owner_role_is_protected' USING ERRCODE = '42501';
  END IF;

  SELECT count(*) INTO invalid_role_count
  FROM unnest(COALESCE(requested_role_ids, ARRAY[]::UUID[])) AS requested(requested_id)
  LEFT JOIN public.organization_roles role
    ON role.id = requested_id AND role.workspace_id = ws_id
  WHERE role.id IS NULL OR role.system_key = 'owner';

  IF invalid_role_count > 0 THEN
    RAISE EXCEPTION 'organization_role_scope_invalid' USING ERRCODE = '23514';
  END IF;

  SELECT EXISTS (
    SELECT 1 FROM public.organization_roles
    WHERE workspace_id = ws_id
      AND id = ANY(COALESCE(requested_role_ids, ARRAY[]::UUID[]))
      AND system_key = 'admin'
  ) INTO assigns_admin;

  IF assigns_admin AND actor_role <> 'owner'::public.workspace_member_role THEN
    RAISE EXCEPTION 'organization_admin_assignment_requires_owner' USING ERRCODE = '42501';
  END IF;

  DELETE FROM public.organization_member_roles
  WHERE workspace_id = ws_id AND member_id = target_member_id;

  INSERT INTO public.organization_member_roles (workspace_id, member_id, role_id, assigned_by)
  SELECT ws_id, target_member_id, role.id, auth.uid()
  FROM public.organization_roles role
  WHERE role.workspace_id = ws_id
    AND role.id = ANY(COALESCE(requested_role_ids, ARRAY[]::UUID[]));

  UPDATE public.workspace_members
  SET role = CASE
        WHEN assigns_admin THEN 'admin'::public.workspace_member_role
        ELSE 'member'::public.workspace_member_role
      END
  WHERE id = target_member_id AND workspace_id = ws_id;

  INSERT INTO public.organization_audit_events (
    workspace_id, actor_user_id, event_type, resource_type, resource_id,
    summary, payload, severity, module
  ) VALUES (
    ws_id, auth.uid(), 'member.roles.updated', 'workspace_member', target_member_id::TEXT,
    'Roles del miembro actualizados',
    jsonb_build_object('role_ids', COALESCE(requested_role_ids, ARRAY[]::UUID[])),
    'high', 'members'
  );
END;
$function$
;

-- [FUNCTION] public.set_organization_member_units(ws_id uuid, target_member_id uuid, requested_unit_ids uuid[])
CREATE OR REPLACE FUNCTION public.set_organization_member_units(ws_id uuid, target_member_id uuid, requested_unit_ids uuid[])
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE
  invalid_unit_count INTEGER;
BEGIN
  IF NOT public.has_organization_permission(ws_id, 'teams.manage') THEN
    RAISE EXCEPTION 'organization_permission_denied' USING ERRCODE = '42501';
  END IF;

  IF NOT EXISTS (
    SELECT 1 FROM public.workspace_members
    WHERE id = target_member_id AND workspace_id = ws_id
  ) THEN
    RAISE EXCEPTION 'organization_member_not_found' USING ERRCODE = 'P0002';
  END IF;

  SELECT count(*) INTO invalid_unit_count
  FROM unnest(COALESCE(requested_unit_ids, ARRAY[]::UUID[])) AS requested(requested_id)
  LEFT JOIN public.organization_units unit
    ON unit.id = requested_id AND unit.workspace_id = ws_id AND unit.status = 'active'
  WHERE unit.id IS NULL;

  IF invalid_unit_count > 0 THEN
    RAISE EXCEPTION 'organization_unit_scope_invalid' USING ERRCODE = '23514';
  END IF;

  DELETE FROM public.organization_unit_members membership
  USING public.organization_units unit
  WHERE membership.unit_id = unit.id
    AND membership.member_id = target_member_id
    AND unit.workspace_id = ws_id;

  INSERT INTO public.organization_unit_members (unit_id, member_id)
  SELECT unit.id, target_member_id
  FROM public.organization_units unit
  WHERE unit.workspace_id = ws_id
    AND unit.status = 'active'
    AND unit.id = ANY(COALESCE(requested_unit_ids, ARRAY[]::UUID[]));

  INSERT INTO public.organization_audit_events (
    workspace_id, actor_user_id, event_type, resource_type, resource_id,
    summary, payload, module
  ) VALUES (
    ws_id, auth.uid(), 'member.units.updated', 'workspace_member', target_member_id::TEXT,
    'Equipos del miembro actualizados',
    jsonb_build_object('unit_ids', COALESCE(requested_unit_ids, ARRAY[]::UUID[])),
    'members'
  );
END;
$function$
;

-- [FUNCTION] public.set_organization_role_permissions(ws_id uuid, target_role_id uuid, permission_keys text[])
CREATE OR REPLACE FUNCTION public.set_organization_role_permissions(ws_id uuid, target_role_id uuid, permission_keys text[])
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE
  target_is_system BOOLEAN;
BEGIN
  IF NOT public.has_organization_permission(ws_id, 'roles.manage') THEN
    RAISE EXCEPTION 'organization_permission_denied' USING ERRCODE = '42501';
  END IF;

  SELECT is_system
  INTO target_is_system
  FROM public.organization_roles
  WHERE id = target_role_id AND workspace_id = ws_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'organization_role_not_found' USING ERRCODE = 'P0002';
  END IF;

  IF target_is_system THEN
    RAISE EXCEPTION 'system_role_is_read_only' USING ERRCODE = '42501';
  END IF;

  DELETE FROM public.organization_role_permissions
  WHERE role_id = target_role_id;

  INSERT INTO public.organization_role_permissions (role_id, permission_id)
  SELECT target_role_id, permission.id
  FROM public.organization_permissions permission
  WHERE permission.permission_key = ANY(COALESCE(permission_keys, ARRAY[]::TEXT[]));

  INSERT INTO public.organization_audit_events (
    workspace_id, actor_user_id, event_type, resource_type, resource_id, summary, payload
  ) VALUES (
    ws_id,
    auth.uid(),
    'role.permissions.updated',
    'organization_role',
    target_role_id::TEXT,
    'Permisos de rol actualizados',
    jsonb_build_object('permission_keys', COALESCE(permission_keys, ARRAY[]::TEXT[]))
  );
END;
$function$
;

-- [FUNCTION] public.set_organization_unit_members(ws_id uuid, target_unit_id uuid, requested_member_ids uuid[])
CREATE OR REPLACE FUNCTION public.set_organization_unit_members(ws_id uuid, target_unit_id uuid, requested_member_ids uuid[])
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
BEGIN
  IF auth.uid() IS NULL OR NOT public.has_organization_permission(ws_id, 'teams.manage') THEN
    RAISE EXCEPTION 'organization_permission_denied' USING ERRCODE = '42501';
  END IF;

  IF NOT EXISTS (
    SELECT 1 FROM public.organization_units
    WHERE id = target_unit_id AND workspace_id = ws_id AND status = 'active'
  ) THEN
    RAISE EXCEPTION 'organization_unit_not_found' USING ERRCODE = 'P0002';
  END IF;

  IF EXISTS (
    SELECT 1 FROM unnest(COALESCE(requested_member_ids, ARRAY[]::UUID[])) requested_id
    WHERE NOT EXISTS (
      SELECT 1 FROM public.workspace_members member
      WHERE member.id = requested_id AND member.workspace_id = ws_id AND member.status = 'active'
    )
  ) THEN
    RAISE EXCEPTION 'organization_unit_member_scope_invalid' USING ERRCODE = '23514';
  END IF;

  DELETE FROM public.organization_unit_members WHERE unit_id = target_unit_id;
  INSERT INTO public.organization_unit_members(unit_id, member_id)
  SELECT target_unit_id, requested_id
  FROM unnest(COALESCE(requested_member_ids, ARRAY[]::UUID[])) requested_id
  ON CONFLICT DO NOTHING;

  INSERT INTO public.organization_audit_events(
    workspace_id, actor_user_id, event_type, resource_type, resource_id, summary, payload, module
  ) VALUES (
    ws_id, auth.uid(), 'organization.unit.members.updated', 'organization_unit', target_unit_id,
    'Membresías de unidad actualizadas', jsonb_build_object('member_count', cardinality(COALESCE(requested_member_ids, ARRAY[]::UUID[]))), 'teams'
  );
END;
$function$
;

-- [FUNCTION] public.set_participants_visible(p_documento_id uuid, p_participant_ids text[])
CREATE OR REPLACE FUNCTION public.set_participants_visible(p_documento_id uuid, p_participant_ids text[])
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
BEGIN
  UPDATE public.documentos
  SET participantes = (
    SELECT jsonb_agg(
      CASE
        WHEN (elem->>'id') = ANY(p_participant_ids)
          OR (elem->>'email') = ANY(p_participant_ids)
          THEN jsonb_set(
                jsonb_set(elem, '{visible}', 'true'::jsonb),
                '{notificado}', 'true'::jsonb
               )
        ELSE elem
      END
    )
    FROM jsonb_array_elements(COALESCE(participantes, '[]'::jsonb)) AS elem
  )
  WHERE id = p_documento_id;
END;
$function$
;

