-- [FUNCTION] public.setup_free_workspace_and_subscription(p_user_id uuid, p_full_name text, p_account_type text, p_personalidad_juridica text, p_identity_method text, p_rfc text, p_curp text, p_phone text, p_document_type_1 text, p_document_type_2 text)
CREATE OR REPLACE FUNCTION public.setup_free_workspace_and_subscription(p_user_id uuid, p_full_name text, p_account_type text, p_personalidad_juridica text, p_identity_method text, p_rfc text DEFAULT NULL::text, p_curp text DEFAULT NULL::text, p_phone text DEFAULT NULL::text, p_document_type_1 text DEFAULT NULL::text, p_document_type_2 text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE
    v_workspace_id UUID;
    v_plan_id UUID;
    v_subscription_id UUID;
    v_workspace_type public.workspace_type;
    v_period_end TIMESTAMPTZ;
    v_biometric_verified BOOLEAN := false;
    v_biometric_at TIMESTAMPTZ := NULL;
    v_enrollment_result_id UUID := NULL;
BEGIN
    -- Determine workspace type
    IF p_account_type = 'empresarial' THEN
        v_workspace_type := 'business'::public.workspace_type;
    ELSE
        v_workspace_type := 'personal'::public.workspace_type;
    END IF;

    -- Get free plan id
    SELECT id INTO v_plan_id
    FROM public.subscription_plans
    WHERE slug = 'free'
    LIMIT 1;

    IF v_plan_id IS NULL THEN
        RAISE EXCEPTION 'Free plan not found in subscription_plans';
    END IF;

    -- Calculate period end (1 month from now)
    v_period_end := CURRENT_TIMESTAMP + INTERVAL '1 month';

    -- Create workspace
    INSERT INTO public.workspaces (id, name, workspace_type, owner_id, description)
    VALUES (
        gen_random_uuid(),
        COALESCE(p_full_name, 'Mi Workspace'),
        v_workspace_type,
        p_user_id,
        'Workspace personal de ' || COALESCE(p_full_name, 'usuario')
    )
    RETURNING id INTO v_workspace_id;

    -- Add user as owner member
    INSERT INTO public.workspace_members (workspace_id, user_id, role)
    VALUES (v_workspace_id, p_user_id, 'owner'::public.workspace_member_role)
    ON CONFLICT DO NOTHING;

    -- Create free subscription
    INSERT INTO public.subscriptions (
        id, user_id, plan_id, workspace_id, status,
        documents_used, documents_limit,
        current_period_start, current_period_end
    )
    VALUES (
        gen_random_uuid(),
        p_user_id,
        v_plan_id,
        v_workspace_id,
        'active'::public.subscription_status,
        0,
        2,
        CURRENT_TIMESTAMP,
        v_period_end
    )
    RETURNING id INTO v_subscription_id;

    -- Record subscription history
    INSERT INTO public.subscription_history (
        user_id, subscription_id, plan_id, plan_name,
        amount, interval, event_type,
        period_start, period_end,
        notes
    )
    VALUES (
        p_user_id,
        v_subscription_id,
        v_plan_id,
        'Plan Gratuito',
        0.00,
        'monthly'::public.subscription_interval,
        'created',
        CURRENT_TIMESTAMP,
        v_period_end,
        'Plan gratuito activado al registrarse. Renovacion mensual automatica.'
    );

    -- Add validated documents to workspace
    IF p_document_type_1 IS NOT NULL THEN
        INSERT INTO public.workspace_documents (
            workspace_id, user_id, document_type, document_name,
            status, is_validated, validated_at
        )
        VALUES (
            v_workspace_id, p_user_id,
            p_document_type_1,
            CASE p_document_type_1
                WHEN 'biometrico' THEN 'Enrolamiento Biometrico'
                WHEN 'efirma_fisica' THEN 'e.Firma Persona Fisica'
                WHEN 'efirma_moral' THEN 'e.Firma Persona Moral'
                ELSE p_document_type_1
            END,
            'active'::public.document_status,
            true,
            CURRENT_TIMESTAMP
        );
    END IF;

    IF p_document_type_2 IS NOT NULL THEN
        INSERT INTO public.workspace_documents (
            workspace_id, user_id, document_type, document_name,
            status, is_validated, validated_at
        )
        VALUES (
            v_workspace_id, p_user_id,
            p_document_type_2,
            CASE p_document_type_2
                WHEN 'biometrico' THEN 'Enrolamiento Biometrico'
                WHEN 'efirma_fisica' THEN 'e.Firma Persona Fisica'
                WHEN 'efirma_moral' THEN 'e.Firma Persona Moral'
                ELSE p_document_type_2
            END,
            'active'::public.document_status,
            true,
            CURRENT_TIMESTAMP
        );
    END IF;

    -- Update user profile with all registration data
    UPDATE public.user_profiles
    SET
        full_name             = COALESCE(p_full_name, full_name),
        phone                 = COALESCE(p_phone, phone),
        account_type          = COALESCE(p_account_type, account_type),
        personalidad_juridica = COALESCE(p_personalidad_juridica, personalidad_juridica),
        identity_method       = COALESCE(p_identity_method, identity_method),
        rfc                   = COALESCE(p_rfc, rfc),
        curp                  = COALESCE(p_curp, curp),
        updated_at            = CURRENT_TIMESTAMP
    WHERE id = p_user_id;

    -- Determine biometric status based on identity_method
    -- 'biometrico' = user completed biometric enrollment during registration
    IF p_identity_method = 'biometrico' THEN
        -- Look for a completed enrollment result for this user
        SELECT id INTO v_enrollment_result_id
        FROM public.enrollment_results
        WHERE user_id = p_user_id
          AND face_match_passed = true
        ORDER BY created_at DESC
        LIMIT 1;

        v_biometric_verified := true;
        v_biometric_at := CURRENT_TIMESTAMP;
    END IF;

    -- Upsert user_verification_status with phone and biometric status
    INSERT INTO public.user_verification_status (
        user_id,
        phone_number,
        biometric_verified,
        biometric_verified_at,
        biometric_source,
        enrollment_result_id
    )
    VALUES (
        p_user_id,
        p_phone,
        v_biometric_verified,
        v_biometric_at,
        CASE WHEN v_biometric_verified THEN 'enrollment' ELSE NULL END,
        v_enrollment_result_id
    )
    ON CONFLICT (user_id) DO UPDATE
        SET phone_number          = COALESCE(p_phone, public.user_verification_status.phone_number),
            biometric_verified    = CASE
                                      WHEN p_identity_method = 'biometrico' THEN true
                                      ELSE public.user_verification_status.biometric_verified
                                    END,
            biometric_verified_at = CASE
                                      WHEN p_identity_method = 'biometrico' AND public.user_verification_status.biometric_verified_at IS NULL
                                      THEN CURRENT_TIMESTAMP
                                      ELSE public.user_verification_status.biometric_verified_at
                                    END,
            biometric_source      = CASE
                                      WHEN p_identity_method = 'biometrico' THEN 'enrollment'
                                      ELSE public.user_verification_status.biometric_source
                                    END,
            enrollment_result_id  = COALESCE(v_enrollment_result_id, public.user_verification_status.enrollment_result_id),
            updated_at            = CURRENT_TIMESTAMP;

    RETURN jsonb_build_object(
        'success', true,
        'workspace_id', v_workspace_id,
        'subscription_id', v_subscription_id,
        'plan_id', v_plan_id
    );

EXCEPTION
    WHEN OTHERS THEN
        RETURN jsonb_build_object(
            'success', false,
            'error', SQLERRM
        );
END;
$function$
;

-- [FUNCTION] public.setup_free_workspace_and_subscription(p_user_id uuid, p_full_name text, p_account_type text, p_personalidad_juridica text, p_identity_method text, p_rfc text, p_curp text, p_phone text, p_document_type_1 text, p_document_type_2 text, p_nombre text, p_apellido_paterno text, p_apellido_materno text, p_telefono text, p_fecha_nacimiento text, p_sexo text, p_tipo_identificacion text, p_efirma_rfc text, p_efirma_serial text, p_efirma_nombre text, p_efirma_vigencia_fin text)
CREATE OR REPLACE FUNCTION public.setup_free_workspace_and_subscription(p_user_id uuid, p_full_name text, p_account_type text, p_personalidad_juridica text, p_identity_method text, p_rfc text DEFAULT NULL::text, p_curp text DEFAULT NULL::text, p_phone text DEFAULT NULL::text, p_document_type_1 text DEFAULT NULL::text, p_document_type_2 text DEFAULT NULL::text, p_nombre text DEFAULT NULL::text, p_apellido_paterno text DEFAULT NULL::text, p_apellido_materno text DEFAULT NULL::text, p_telefono text DEFAULT NULL::text, p_fecha_nacimiento text DEFAULT NULL::text, p_sexo text DEFAULT NULL::text, p_tipo_identificacion text DEFAULT NULL::text, p_efirma_rfc text DEFAULT NULL::text, p_efirma_serial text DEFAULT NULL::text, p_efirma_nombre text DEFAULT NULL::text, p_efirma_vigencia_fin text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE
    v_workspace_id UUID;
    v_plan_id UUID;
    v_subscription_id UUID;
    v_workspace_type public.workspace_type;
    v_period_end TIMESTAMPTZ;
BEGIN
    -- Determine workspace type
    IF p_account_type = 'empresarial' THEN
        v_workspace_type := 'business'::public.workspace_type;
    ELSE
        v_workspace_type := 'personal'::public.workspace_type;
    END IF;

    -- Get free plan id
    SELECT id INTO v_plan_id
    FROM public.subscription_plans
    WHERE slug = 'free'
    LIMIT 1;

    IF v_plan_id IS NULL THEN
        RAISE EXCEPTION 'Free plan not found in subscription_plans';
    END IF;

    -- Calculate period end (1 month from now)
    v_period_end := CURRENT_TIMESTAMP + INTERVAL '1 month';

    -- Create workspace
    INSERT INTO public.workspaces (id, name, workspace_type, owner_id, description)
    VALUES (
        gen_random_uuid(),
        COALESCE(p_full_name, 'Mi Workspace'),
        v_workspace_type,
        p_user_id,
        'Workspace personal de ' || COALESCE(p_full_name, 'usuario')
    )
    RETURNING id INTO v_workspace_id;

    -- Add user as owner member
    INSERT INTO public.workspace_members (workspace_id, user_id, role)
    VALUES (v_workspace_id, p_user_id, 'owner'::public.workspace_member_role)
    ON CONFLICT DO NOTHING;

    -- Create free subscription
    INSERT INTO public.subscriptions (
        id, user_id, plan_id, workspace_id, status,
        documents_used, documents_limit,
        current_period_start, current_period_end
    )
    VALUES (
        gen_random_uuid(),
        p_user_id,
        v_plan_id,
        v_workspace_id,
        'active'::public.subscription_status,
        0,
        2,
        CURRENT_TIMESTAMP,
        v_period_end
    )
    RETURNING id INTO v_subscription_id;

    -- Record subscription history
    INSERT INTO public.subscription_history (
        user_id, subscription_id, plan_id, plan_name,
        amount, interval, event_type,
        period_start, period_end,
        notes
    )
    VALUES (
        p_user_id,
        v_subscription_id,
        v_plan_id,
        'Plan Gratuito',
        0.00,
        'monthly'::public.subscription_interval,
        'created',
        CURRENT_TIMESTAMP,
        v_period_end,
        'Plan gratuito activado al registrarse. Renovacion mensual automatica.'
    );

    -- Add validated documents to workspace
    IF p_document_type_1 IS NOT NULL THEN
        INSERT INTO public.workspace_documents (
            workspace_id, user_id, document_type, document_name,
            status, is_validated, validated_at
        )
        VALUES (
            v_workspace_id, p_user_id,
            p_document_type_1,
            CASE p_document_type_1
                WHEN 'biometrico' THEN 'Enrolamiento Biometrico'
                WHEN 'efirma_fisica' THEN 'e.Firma Persona Fisica'
                WHEN 'efirma_moral' THEN 'e.Firma Persona Moral'
                ELSE p_document_type_1
            END,
            'active'::public.document_status,
            true,
            CURRENT_TIMESTAMP
        );
    END IF;

    IF p_document_type_2 IS NOT NULL THEN
        INSERT INTO public.workspace_documents (
            workspace_id, user_id, document_type, document_name,
            status, is_validated, validated_at
        )
        VALUES (
            v_workspace_id, p_user_id,
            p_document_type_2,
            CASE p_document_type_2
                WHEN 'biometrico' THEN 'Enrolamiento Biometrico'
                WHEN 'efirma_fisica' THEN 'e.Firma Persona Fisica'
                WHEN 'efirma_moral' THEN 'e.Firma Persona Moral'
                ELSE p_document_type_2
            END,
            'active'::public.document_status,
            true,
            CURRENT_TIMESTAMP
        );
    END IF;

    -- Update user profile with ALL available data from registration
    UPDATE public.user_profiles
    SET
        full_name            = COALESCE(p_full_name, full_name),
        phone                = COALESCE(p_phone, phone),
        account_type         = COALESCE(p_account_type, account_type),
        personalidad_juridica = COALESCE(p_personalidad_juridica, personalidad_juridica),
        identity_method      = COALESCE(p_identity_method, identity_method),
        rfc                  = COALESCE(p_rfc, rfc),
        curp                 = COALESCE(p_curp, curp),
        -- Extended personal fields from CURP / biometric enrollment
        nombre               = COALESCE(p_nombre, nombre),
        apellido_paterno     = COALESCE(p_apellido_paterno, apellido_paterno),
        apellido_materno     = COALESCE(p_apellido_materno, apellido_materno),
        telefono             = COALESCE(p_telefono, p_phone, telefono),
        -- e.Firma specific fields (only set when identity method is efirma)
        efirma_rfc           = COALESCE(p_efirma_rfc, efirma_rfc),
        efirma_serial        = COALESCE(p_efirma_serial, efirma_serial),
        efirma_nombre        = COALESCE(p_efirma_nombre, efirma_nombre),
        efirma_vigencia_fin  = COALESCE(p_efirma_vigencia_fin, efirma_vigencia_fin),
        efirma_linked_at     = CASE
                                 WHEN p_efirma_serial IS NOT NULL AND efirma_linked_at IS NULL
                                 THEN CURRENT_TIMESTAMP
                                 ELSE efirma_linked_at
                               END,
        updated_at           = CURRENT_TIMESTAMP
    WHERE id = p_user_id;

    RETURN jsonb_build_object(
        'success', true,
        'workspace_id', v_workspace_id,
        'subscription_id', v_subscription_id,
        'plan_id', v_plan_id
    );

EXCEPTION
    WHEN OTHERS THEN
        RETURN jsonb_build_object(
            'success', false,
            'error', SQLERRM
        );
END;
$function$
;

-- [FUNCTION] public.shares_workspace_with(profile_id uuid)
CREATE OR REPLACE FUNCTION public.shares_workspace_with(profile_id uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
  SELECT EXISTS (
    SELECT 1
    FROM public.workspace_members target
    JOIN public.workspace_members viewer ON viewer.workspace_id = target.workspace_id
    WHERE target.user_id = profile_id
      AND target.status = 'active'
      AND viewer.user_id = auth.uid()
      AND viewer.status = 'active'
  );
$function$
;

