-- [FUNCTION] public.sync_encryption_metadata_dek_counts()
CREATE OR REPLACE FUNCTION public.sync_encryption_metadata_dek_counts()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE
  v_document_id UUID;
  v_active_count INT;
BEGIN
  -- Determine which document_id changed
  IF TG_OP = 'DELETE' THEN
    v_document_id := OLD.document_id;
  ELSE
    v_document_id := NEW.document_id;
  END IF;

  -- Count active participant DEKs for this document
  SELECT COUNT(*)
  INTO v_active_count
  FROM public.document_participant_deks
  WHERE document_id = v_document_id
    AND access_status = 'active';

  -- Update document_encryption_metadata
  -- uses_per_participant_deks = TRUE if at least one active DEK exists
  -- participant_deks_count = number of active DEKs
  UPDATE public.document_encryption_metadata
  SET
    uses_per_participant_deks = (v_active_count > 0),
    participant_deks_count    = v_active_count
  WHERE document_id = v_document_id;

  RETURN COALESCE(NEW, OLD);
END;
$function$
;

-- [FUNCTION] public.sync_form_template_schemas()
CREATE OR REPLACE FUNCTION public.sync_form_template_schemas()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  NEW.form_schema := jsonb_build_object(
    'version', 1,
    'sections', COALESCE(NEW.settings->'sections', '[]'::jsonb),
    'fields', COALESCE(NEW.schema, '[]'::jsonb)
  );
  NEW.pdf_schema := COALESCE(NEW.settings->'pdfSchema', '{}'::jsonb);
  NEW.requires_signature := COALESCE((NEW.settings->>'requiresSignature')::boolean, false);
  NEW.allowed_signature_types := COALESCE(
    ARRAY(SELECT jsonb_array_elements_text(NEW.settings->'allowedSignatureTypes')),
    ARRAY['click_sign']::text[]
  );
  RETURN NEW;
END;
$function$
;

