-- [FUNCTION] public.update_participante_estado(p_documento_id uuid, p_email text, p_estado text)
CREATE OR REPLACE FUNCTION public.update_participante_estado(p_documento_id uuid, p_email text, p_estado text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
BEGIN
  UPDATE public.documentos
  SET participantes = (
    SELECT jsonb_agg(
      CASE
        WHEN (elem->>'email') = p_email
          THEN jsonb_set(elem, '{estado}', to_jsonb(p_estado))
        ELSE elem
      END
    )
    FROM jsonb_array_elements(COALESCE(participantes, '[]'::jsonb)) AS elem
  )
  WHERE id = p_documento_id;
END;
$function$
;

-- [FUNCTION] public.update_participante_sub_estado(p_documento_id uuid, p_email text, p_sub_estado text)
CREATE OR REPLACE FUNCTION public.update_participante_sub_estado(p_documento_id uuid, p_email text, p_sub_estado text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE
  terminal_states TEXT[] := ARRAY['firmo', 'firmado', 'rechazo', 'rechazado', 'aprobo', 'aprobado', 'cancelo', 'cancelado'];
BEGIN
  UPDATE public.documentos
  SET participantes = (
    SELECT jsonb_agg(
      CASE
        WHEN (elem->>'email') = p_email
          -- Only update if current state is NOT a terminal state
          AND NOT ((elem->>'sub_estado') = ANY(terminal_states))
          THEN jsonb_set(elem, '{sub_estado}', to_jsonb(p_sub_estado))
        ELSE elem
      END
    )
    FROM jsonb_array_elements(COALESCE(participantes, '[]'::jsonb)) AS elem
  )
  WHERE id = p_documento_id;
END;
$function$
;

