-- [FUNCTION] public.validate_organization_authority_activation()
CREATE OR REPLACE FUNCTION public.validate_organization_authority_activation()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
DECLARE
  person_record RECORD;
  evidence_record RECORD;
BEGIN
  SELECT workspace_id, identity_status, status
    INTO person_record
  FROM public.organization_directory_people
  WHERE id = NEW.person_id;

  IF person_record.workspace_id IS DISTINCT FROM NEW.workspace_id THEN
    RAISE EXCEPTION 'organization_authority_person_workspace_mismatch' USING ERRCODE = '23514';
  END IF;

  IF NEW.evidence_id IS NOT NULL THEN
    SELECT workspace_id, person_id, status, valid_until
      INTO evidence_record
    FROM public.organization_directory_evidence
    WHERE id = NEW.evidence_id;
    IF evidence_record.workspace_id IS DISTINCT FROM NEW.workspace_id
       OR evidence_record.person_id IS DISTINCT FROM NEW.person_id THEN
      RAISE EXCEPTION 'organization_authority_evidence_scope_mismatch' USING ERRCODE = '23514';
    END IF;
  END IF;

  IF NEW.status = 'active' THEN
    IF person_record.status IS DISTINCT FROM 'active' THEN
      RAISE EXCEPTION 'organization_authority_person_inactive' USING ERRCODE = '23514';
    END IF;
    IF NEW.identity_required AND person_record.identity_status NOT IN ('verified', 'identity_verified') THEN
      RAISE EXCEPTION 'organization_authority_identity_not_verified' USING ERRCODE = '23514';
    END IF;
    IF NEW.evidence_id IS NULL OR evidence_record.status IS DISTINCT FROM 'verified' THEN
      RAISE EXCEPTION 'organization_authority_verified_evidence_required' USING ERRCODE = '23514';
    END IF;
    IF evidence_record.valid_until IS NOT NULL AND evidence_record.valid_until < CURRENT_DATE THEN
      RAISE EXCEPTION 'organization_authority_evidence_expired' USING ERRCODE = '23514';
    END IF;
    IF NEW.valid_until IS NOT NULL AND NEW.valid_until < CURRENT_DATE THEN
      RAISE EXCEPTION 'organization_authority_expired' USING ERRCODE = '23514';
    END IF;
  END IF;

  IF NEW.status = 'revoked' AND (TG_OP = 'INSERT' OR OLD.status IS DISTINCT FROM 'revoked') THEN
    NEW.revoked_at := COALESCE(NEW.revoked_at, CURRENT_TIMESTAMP);
  ELSIF NEW.status <> 'revoked' THEN
    NEW.revoked_at := NULL;
    NEW.revoked_by := NULL;
  END IF;

  RETURN NEW;
END;
$function$
;

-- [FUNCTION] public.validate_organization_security_settings()
CREATE OR REPLACE FUNCTION public.validate_organization_security_settings()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE
  session_hours INTEGER;
  concurrent_sessions INTEGER;
BEGIN
  IF NEW.workspace_type <> 'business'::public.workspace_type THEN
    RETURN NEW;
  END IF;

  session_hours := COALESCE((NEW.security_settings ->> 'session_max_hours')::INTEGER, 12);
  concurrent_sessions := COALESCE((NEW.security_settings ->> 'max_concurrent_sessions')::INTEGER, 3);
  IF session_hours < 1 OR session_hours > 168 THEN
    RAISE EXCEPTION 'organization_session_duration_out_of_range' USING ERRCODE = '22023';
  END IF;
  IF concurrent_sessions < 1 OR concurrent_sessions > 20 THEN
    RAISE EXCEPTION 'organization_concurrent_sessions_out_of_range' USING ERRCODE = '22023';
  END IF;

  IF COALESCE((NEW.security_settings ->> 'sso_enforced')::BOOLEAN, FALSE) THEN
    IF NOT COALESCE((NEW.security_settings ->> 'emergency_access')::BOOLEAN, FALSE) THEN
      RAISE EXCEPTION 'organization_sso_requires_emergency_access' USING ERRCODE = '23514';
    END IF;
    IF NOT EXISTS (
      SELECT 1 FROM public.organization_integrations oi
      WHERE oi.workspace_id = NEW.id
        AND oi.integration_type = 'sso'
        AND oi.status = 'connected'
    ) THEN
      RAISE EXCEPTION 'organization_sso_provider_not_operational' USING ERRCODE = '23514';
    END IF;
  END IF;
  RETURN NEW;
END;
$function$
;

-- [FUNCTION] public.validate_organization_unit_hierarchy()
CREATE OR REPLACE FUNCTION public.validate_organization_unit_hierarchy()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
DECLARE
  related_workspace_id UUID;
BEGIN
  IF NEW.parent_id = NEW.id THEN
    RAISE EXCEPTION 'organization_unit_self_parent' USING ERRCODE = '23514';
  END IF;

  IF NEW.parent_id IS NOT NULL AND EXISTS (
    WITH RECURSIVE lineage AS (
      SELECT unit.id, unit.parent_id
      FROM public.organization_units unit
      WHERE unit.id = NEW.parent_id AND unit.workspace_id = NEW.workspace_id
      UNION ALL
      SELECT parent.id, parent.parent_id
      FROM public.organization_units parent
      JOIN lineage child ON child.parent_id = parent.id
      WHERE parent.workspace_id = NEW.workspace_id
    )
    SELECT 1 FROM lineage WHERE id = NEW.id
  ) THEN
    RAISE EXCEPTION 'organization_unit_hierarchy_cycle' USING ERRCODE = '23514';
  END IF;

  IF NEW.deputy_member_id IS NOT NULL THEN
    SELECT workspace_id INTO related_workspace_id
    FROM public.workspace_members WHERE id = NEW.deputy_member_id;
    IF related_workspace_id IS DISTINCT FROM NEW.workspace_id THEN
      RAISE EXCEPTION 'organization_unit_deputy_workspace_mismatch' USING ERRCODE = '23514';
    END IF;
  END IF;

  IF NEW.cost_center_id IS NOT NULL THEN
    SELECT workspace_id INTO related_workspace_id
    FROM public.organization_cost_centers WHERE id = NEW.cost_center_id;
    IF related_workspace_id IS DISTINCT FROM NEW.workspace_id THEN
      RAISE EXCEPTION 'organization_unit_cost_center_workspace_mismatch' USING ERRCODE = '23514';
    END IF;
  END IF;

  IF NEW.status = 'inactive' AND (TG_OP = 'INSERT' OR OLD.status IS DISTINCT FROM 'inactive') THEN
    NEW.archived_at := COALESCE(NEW.archived_at, CURRENT_TIMESTAMP);
  ELSIF NEW.status = 'active' THEN
    NEW.archived_at := NULL;
  END IF;

  RETURN NEW;
END;
$function$
;

