-- [FUNCTION] public.verify_audit_chain(p_from_seq bigint)
CREATE OR REPLACE FUNCTION public.verify_audit_chain(p_from_seq bigint DEFAULT 1)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE
  v_rec           RECORD;
  v_prev_hash     TEXT;
  v_expected_hash TEXT;
  v_canonical     JSONB;
  v_count         INT := 0;
  v_last_hash     TEXT;
  v_genesis_hash  TEXT;
BEGIN
  v_genesis_hash := encode(digest('DOCUBOX_GENESIS', 'sha256'), 'hex');

  FOR v_rec IN
    SELECT event_id, event_seq, occurred_at, user_id, workspace_id,
           ip_address, event_type, resource_type, resource_id, outcome,
           prev_hash, event_hash
    FROM public.audit_log
    WHERE event_seq >= p_from_seq
    ORDER BY event_seq ASC
  LOOP
    -- Verificar prev_hash del primer evento
    IF v_count = 0 THEN
      IF v_rec.prev_hash <> v_genesis_hash THEN
        RETURN jsonb_build_object(
          'valid', false,
          'broken_at_seq', v_rec.event_seq,
          'broken_event_id', v_rec.event_id,
          'reason', 'prev_hash_mismatch: expected genesis hash'
        );
      END IF;
    ELSE
      IF v_rec.prev_hash <> v_last_hash THEN
        RETURN jsonb_build_object(
          'valid', false,
          'broken_at_seq', v_rec.event_seq,
          'broken_event_id', v_rec.event_id,
          'reason', 'prev_hash_mismatch'
        );
      END IF;
    END IF;

    -- Recalcular el hash del evento y comparar
    v_canonical := json_build_object(
      'occurred_at',    v_rec.occurred_at::TEXT,
      'user_id',        COALESCE(v_rec.user_id::TEXT, ''),
      'workspace_id',   COALESCE(v_rec.workspace_id::TEXT, ''),
      'ip_address',     v_rec.ip_address::TEXT,
      'event_type',     v_rec.event_type::TEXT,
      'resource_type',  COALESCE(v_rec.resource_type::TEXT, ''),
      'resource_id',    COALESCE(v_rec.resource_id::TEXT, ''),
      'outcome',        v_rec.outcome::TEXT,
      'prev_hash',      v_rec.prev_hash::TEXT
    );

    v_expected_hash := encode(digest(v_canonical::text, 'sha256'), 'hex');

    IF v_rec.event_hash <> v_expected_hash THEN
      RETURN jsonb_build_object(
        'valid', false,
        'broken_at_seq', v_rec.event_seq,
        'broken_event_id', v_rec.event_id,
        'reason', 'hash_mismatch'
      );
    END IF;

    v_last_hash := v_rec.event_hash;
    v_count := v_count + 1;
  END LOOP;

  RETURN jsonb_build_object(
    'valid', true,
    'events_verified', v_count,
    'last_hash', v_last_hash
  );
END;
$function$
;

-- [FUNCTION] public.verify_evidence_hash_consistency()
CREATE OR REPLACE FUNCTION public.verify_evidence_hash_consistency()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE
  v_sha256_original CHAR(64);
BEGIN
  SELECT sha256_original INTO v_sha256_original
  FROM public.documents
  WHERE id = NEW.document_id;

  IF v_sha256_original IS NULL THEN
    RAISE EXCEPTION
      'Inconsistencia de hash: no se encontró el documento con id % para verificar la evidencia.',
      NEW.document_id;
  END IF;

  IF NEW.sha256_file_at_event <> v_sha256_original THEN
    RAISE EXCEPTION
      'Inconsistencia de hash detectada: el hash SHA-256 del archivo en la evidencia (%) '
      'no coincide con el hash original del documento (%). '
      'El archivo puede haber sido alterado antes de registrar la evidencia.',
      NEW.sha256_file_at_event, v_sha256_original;
  END IF;

  RETURN NEW;
END;
$function$
;

-- [FUNCTION] public.verify_security_audit_chain(p_workspace_id uuid)
CREATE OR REPLACE FUNCTION public.verify_security_audit_chain(p_workspace_id uuid)
 RETURNS TABLE(event_id uuid, action text, event_hash character, previous_hash character, chain_valid boolean, created_at timestamp with time zone)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE
  v_rec         RECORD;
  v_prev_hash   CHAR(64) := NULL;
BEGIN
  FOR v_rec IN
    SELECT
      sac.id,
      sac.action,
      sac.event_hash,
      sac.previous_hash,
      sac.created_at
    FROM public.security_audit_chain sac
    WHERE sac.workspace_id = p_workspace_id
    ORDER BY sac.created_at ASC
  LOOP
    event_id      := v_rec.id;
    action        := v_rec.action;
    event_hash    := v_rec.event_hash;
    previous_hash := v_rec.previous_hash;
    created_at    := v_rec.created_at;

    IF v_prev_hash IS NULL THEN
      chain_valid := (v_rec.previous_hash IS NULL);
    ELSE
      chain_valid := (v_rec.previous_hash = v_prev_hash);
    END IF;

    v_prev_hash := v_rec.event_hash;
    RETURN NEXT;
  END LOOP;
END;
$function$
;

-- [FUNCTION] public.with_audit_sensitive_op(p_workspace_id uuid, p_actor_id uuid, p_category text, p_action text, p_resource_type text, p_resource_id uuid, p_outcome text, p_metadata jsonb, p_ip_address inet, p_is_legal boolean)
CREATE OR REPLACE FUNCTION public.with_audit_sensitive_op(p_workspace_id uuid, p_actor_id uuid, p_category text, p_action text, p_resource_type text, p_resource_id uuid, p_outcome text, p_metadata jsonb DEFAULT '{}'::jsonb, p_ip_address inet DEFAULT NULL::inet, p_is_legal boolean DEFAULT false)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE
  v_prev_hash   CHAR(64);
  v_event_hash  CHAR(64);
  v_event_id    UUID;
  v_timestamp   TEXT;
BEGIN
  v_timestamp := now()::TEXT;

  -- Obtener el hash del último evento del workspace (para cadena)
  SELECT event_hash INTO v_prev_hash
  FROM public.security_audit_chain
  WHERE workspace_id = p_workspace_id
  ORDER BY created_at DESC
  LIMIT 1;

  -- Calcular event_hash: SHA256(prev_hash || timestamp || actor || action || resource || outcome)
  v_event_hash := encode(
    digest(
      COALESCE(v_prev_hash, 'GENESIS') || '|' ||
      v_timestamp || '|' ||
      COALESCE(p_actor_id::TEXT, 'system') || '|' ||
      p_action || '|' ||
      COALESCE(p_resource_id::TEXT, '') || '|' ||
      p_outcome,
      'sha256'
    ),
    'hex'
  );

  -- Insertar evento de auditoría
  INSERT INTO public.security_audit_chain (
    actor_id, workspace_id, category, action,
    resource_type, resource_id, outcome,
    metadata, ip_address, is_legal_event,
    previous_hash, event_hash,
    -- server_hmac: en SQL usamos un HMAC simplificado
    -- El HMAC completo con clave del servidor se calcula en el backend TypeScript
    server_hmac,
    created_at
  )
  VALUES (
    p_actor_id, p_workspace_id, p_category, p_action,
    p_resource_type, p_resource_id, p_outcome,
    p_metadata, p_ip_address, p_is_legal,
    v_prev_hash, v_event_hash,
    encode(hmac(v_event_hash || '|' || p_action || '|' || p_workspace_id::TEXT, 'docubox-sql-hmac-v1', 'sha256'), 'hex'),
    now()
  )
  RETURNING id INTO v_event_id;

  RETURN v_event_id;
END;
$function$
;

